INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u4-X14','kor',3,'u4',ARRAY['K3-1-u4-C16']::text[],'영상이나 글에서 알게 된 내용을 나와 관계없는 일로 여긴다','나는 무엇을 할 수 있을까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
