INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L02_basic#5','kor',3,1,'u4','L02','g3_1_kor_u4_L02_basic','lesson_basic','K3-1-u4-C5',2,'mc','auto','메모하는 방법으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X01','K3-1-u4-X02','K3-1-u4-X03']::text[],false,'{"seq":5,"concept":"K3-1-u4-C5","difficulty":2,"kind":"mc","stem":"메모하는 방법으로 알맞은 것은 무엇일까요?","options":[{"t":"꼭 필요한 내용만 골라 짧게 적는다.","correct":true},{"t":"들은 말을 하나도 빼지 않고 모두 적는다.","mis":"K3-1-u4-X01"},{"t":"낱말 하나만 툭 적어 둔다.","mis":"K3-1-u4-X02"},{"t":"적지 않고 외우기만 한다.","mis":"K3-1-u4-X03"}],"explanation":["꼭 필요한 것","골라서","짧게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L02_basic#6','kor',3,1,'u4','L02','g3_1_kor_u4_L02_basic','lesson_basic','K3-1-u4-C4',2,'mc','auto','메모를 하면 좋은 때로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X04','K3-1-u4-X03','K3-1-u4-X05']::text[],false,'{"seq":6,"concept":"K3-1-u4-C4","difficulty":2,"kind":"mc","stem":"메모를 하면 좋은 때로 알맞은 것은 무엇일까요?","options":[{"t":"친구와 만날 날과 곳을 정할 때","correct":true},{"t":"공부할 때만 — 약속은 메모하지 않아요","mis":"K3-1-u4-X04"},{"t":"기억할 것이 하나도 없을 때","mis":"K3-1-u4-X03"},{"t":"설명을 듣지 않고 딴생각할 때","mis":"K3-1-u4-X05"}],"explanation":["약속","잊으면 곤란할 때","메모"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L02_basic#7','kor',3,1,'u4','L02','g3_1_kor_u4_L02_basic','lesson_basic','K3-1-u4-C8',2,'mc','auto','「꿀벌이 하는 일」에서 가장 힘주어 말한 내용은 무엇일까요?',ARRAY['K3-1-u4-X06','K3-1-u4-X07']::text[],false,'{"seq":7,"concept":"K3-1-u4-C8","difficulty":2,"kind":"mc","stem":"「꿀벌이 하는 일」에서 가장 힘주어 말한 내용은 무엇일까요?","options":[{"t":"꿀벌이 열매를 맺게 돕는다는 점","correct":true},{"t":"꿀벌이 춤을 춘다는 점 — 가장 신기하니까","mis":"K3-1-u4-X06"},{"t":"꿀벌이 꿀을 모은다는 점 — 맨 처음 들었으니까","mis":"K3-1-u4-X06"},{"t":"꿀벌이 모두 몇 마리인지","mis":"K3-1-u4-X07"}],"explanation":["가장 중요한 것은","힘주어","강조"],"asset":{"type":"passage","lines":["꿀벌이 하는 일을 세 가지 알려 줄게요.","첫째, 꿀벌은 꽃에서 꿀을 모아 벌집에 쌓아 둬요.","둘째, 꽃가루를 다른 꽃으로 옮겨 열매가 맺히게 도와요.","셋째, 춤을 추어 꽃이 있는 곳을 다른 벌에게 알려요.","가장 중요한 것은 꿀벌이 열매를 맺게 돕는다는 점이에요."],"title":"들은 설명 — 꿀벌이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L02_basic#8','kor',3,1,'u4','L02','g3_1_kor_u4_L02_basic','lesson_basic','K3-1-u4-C9',2,'mc','auto','「꿀벌이 하는 일」에서 알려 준 꿀벌이 하는 일은 몇 가지일까요?',ARRAY['K3-1-u4-X07']::text[],false,'{"seq":8,"concept":"K3-1-u4-C9","difficulty":2,"kind":"mc","stem":"「꿀벌이 하는 일」에서 알려 준 꿀벌이 하는 일은 몇 가지일까요?","options":[{"t":"세 가지","correct":true},{"t":"한 가지","mis":"K3-1-u4-X07"},{"t":"두 가지","mis":"K3-1-u4-X07"},{"t":"다섯 가지","mis":"K3-1-u4-X07"}],"explanation":["세 가지","첫째 · 둘째 · 셋째","빠짐없이"],"asset":{"type":"passage","lines":["꿀벌이 하는 일을 세 가지 알려 줄게요.","첫째, 꿀벌은 꽃에서 꿀을 모아 벌집에 쌓아 둬요.","둘째, 꽃가루를 다른 꽃으로 옮겨 열매가 맺히게 도와요.","셋째, 춤을 추어 꽃이 있는 곳을 다른 벌에게 알려요.","가장 중요한 것은 꿀벌이 열매를 맺게 돕는다는 점이에요."],"title":"들은 설명 — 꿀벌이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
