INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L02_challenge#1','kor',3,1,'u4','L02','g3_1_kor_u4_L02_challenge','lesson_challenge','K3-1-u4-C1',2,'mc','auto','이 단원에서 배울 내용으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X01','K3-1-u4-X06','K3-1-u4-X35']::text[],false,'{"seq":1,"concept":"K3-1-u4-C1","difficulty":2,"kind":"mc","stem":"이 단원에서 배울 내용으로 알맞은 것은 무엇일까요?","options":[{"t":"말이나 글에서 중요한 내용을 찾아 간단히 정리하기","correct":true},{"t":"들은 말을 빠짐없이 받아 적기","mis":"K3-1-u4-X01"},{"t":"신기한 말만 골라 외우기","mis":"K3-1-u4-X06"},{"t":"국어 시간에 들은 것만 정리하기","mis":"K3-1-u4-X35"}],"explanation":["말과 글","중요한 내용","간단히 정리"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
