INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L02_challenge#3','kor',3,1,'u4','L02','g3_1_kor_u4_L02_challenge','lesson_challenge','K3-1-u4-C5',3,'mc','auto','하은이의 메모를 고쳐 쓴다면 알맞은 방법은 무엇일까요?',ARRAY['K3-1-u4-X01','K3-1-u4-X02','K3-1-u4-X03']::text[],false,'{"seq":3,"concept":"K3-1-u4-C5","difficulty":3,"kind":"mc","stem":"하은이의 메모를 고쳐 쓴다면 알맞은 방법은 무엇일까요?","options":[{"t":"날짜 · 모이는 곳 · 준비물처럼 꼭 필요한 내용만 짧게 줄여 쓴다.","correct":true},{"t":"더 빠짐없이 모두 적는다.","mis":"K3-1-u4-X01"},{"t":"「수요일」 한 낱말만 남긴다.","mis":"K3-1-u4-X02"},{"t":"메모를 버리고 외운다.","mis":"K3-1-u4-X03"}],"explanation":["다 적음","너무 길어요","필요한 것만"],"asset":{"type":"passage","lines":["다음 주 수요일에 현장 체험학습을 가요. 아침 여덟 시 반까지","학교 정문에 모여요. 도시락과 물, 모자를 챙겨요. 꼭 기억할 것은","선생님 곁을 떠나지 않는 거예요. 다시 말할게요. 선생님 곁을 떠나지 않아요."],"title":"하은이의 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L02_challenge#4','kor',3,1,'u4','L02','g3_1_kor_u4_L02_challenge','lesson_challenge','K3-1-u4-C2',3,'mc','auto','시우의 메모를 다음 주에 다시 보면 생길 수 있는 문제는 무엇일까요?',ARRAY['K3-1-u4-X01','K3-1-u4-X02','K3-1-u4-X03']::text[],false,'{"seq":4,"concept":"K3-1-u4-C2","difficulty":3,"kind":"mc","stem":"시우의 메모를 다음 주에 다시 보면 생길 수 있는 문제는 무엇일까요?","options":[{"t":"몇 시까지 정문에 모이는지, 무엇을 챙기는지 알기 어려워요.","correct":true},{"t":"너무 길어서 읽기 어려워요.","mis":"K3-1-u4-X01"},{"t":"아무 문제가 없어요 — 낱말만 적어도 다 기억나요.","mis":"K3-1-u4-X02"},{"t":"메모는 원래 필요 없어요.","mis":"K3-1-u4-X03"}],"explanation":["낱말만","뜻을 몰라요","알아볼 수 있게"],"asset":{"type":"passage","lines":["수요일","정문","모자"],"title":"시우의 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L02_challenge#5','kor',3,1,'u4','L02','g3_1_kor_u4_L02_challenge','lesson_challenge','K3-1-u4-C8',3,'mc','auto','이 안내에서 강조한 내용을 어떻게 알 수 있을까요?',ARRAY['K3-1-u4-X06','K3-1-u4-X07']::text[],false,'{"seq":5,"concept":"K3-1-u4-C8","difficulty":3,"kind":"mc","stem":"이 안내에서 강조한 내용을 어떻게 알 수 있을까요?","options":[{"t":"「꼭 기억할 것」이라고 말하고 한 번 더 되풀이했어요.","correct":true},{"t":"가장 처음에 말해서요.","mis":"K3-1-u4-X06"},{"t":"가장 신기한 말이라서요.","mis":"K3-1-u4-X06"},{"t":"준비물이 세 가지라서요.","mis":"K3-1-u4-X07"}],"explanation":["꼭","되풀이","강조"],"asset":{"type":"speech","turns":[{"who":"선생님","text":"다음 주 수요일에 현장 체험학습을 가요."},{"who":"선생님","text":"아침 여덟 시 반까지 학교 정문에 모여요."},{"who":"선생님","text":"도시락과 물, 모자를 챙겨요."},{"who":"선생님","text":"꼭 기억할 것은 선생님 곁을 떠나지 않는 거예요. 다시 말할게요. 선생님 곁을 떠나지 않아요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L02_challenge#6','kor',3,1,'u4','L02','g3_1_kor_u4_L02_challenge','lesson_challenge','K3-1-u4-C9',3,'mc','auto','이 안내를 듣고 메모할 내용을 빠짐없이 고른 것은 무엇일까요?',ARRAY['K3-1-u4-X07','K3-1-u4-X01']::text[],false,'{"seq":6,"concept":"K3-1-u4-C9","difficulty":3,"kind":"mc","stem":"이 안내를 듣고 메모할 내용을 빠짐없이 고른 것은 무엇일까요?","options":[{"t":"날짜 · 모이는 시각과 곳 · 준비물 · 꼭 기억할 것","correct":true},{"t":"날짜만","mis":"K3-1-u4-X07"},{"t":"준비물만","mis":"K3-1-u4-X07"},{"t":"선생님이 한 말 모두 그대로","mis":"K3-1-u4-X01"}],"explanation":["언제","어디서 · 무엇을","꼭 기억할 것"],"asset":{"type":"speech","turns":[{"who":"선생님","text":"다음 주 수요일에 현장 체험학습을 가요."},{"who":"선생님","text":"아침 여덟 시 반까지 학교 정문에 모여요."},{"who":"선생님","text":"도시락과 물, 모자를 챙겨요."},{"who":"선생님","text":"꼭 기억할 것은 선생님 곁을 떠나지 않는 거예요. 다시 말할게요. 선생님 곁을 떠나지 않아요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L02_challenge#7','kor',3,1,'u4','L02','g3_1_kor_u4_L02_challenge','lesson_challenge','K3-1-u4-C10',3,'mc','auto','민재가 마지막 줄에 ★ 표시를 한 까닭은 무엇일까요?',ARRAY['K3-1-u4-X08','K3-1-u4-X09']::text[],false,'{"seq":7,"concept":"K3-1-u4-C10","difficulty":3,"kind":"mc","stem":"민재가 마지막 줄에 ★ 표시를 한 까닭은 무엇일까요?","options":[{"t":"가장 중요한 내용이라 눈에 띄게 하려고","correct":true},{"t":"차례를 매기려고","mis":"K3-1-u4-X08"},{"t":"메모의 제목이라서","mis":"K3-1-u4-X08"},{"t":"모든 줄에 붙이는 표시라서","mis":"K3-1-u4-X09"}],"explanation":["★","가장 중요한 곳","눈에 띄게"],"asset":{"type":"passage","lines":["제목: 현장 체험학습","1. 다음 주 수요일","2. 아침 8시 30분, 학교 정문","3. 도시락 · 물 · 모자","★ 선생님 곁을 떠나지 않기"],"title":"민재의 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L02_challenge#8','kor',3,1,'u4','L02','g3_1_kor_u4_L02_challenge','lesson_challenge','K3-1-u4-C5',4,'essay','teacher','이 안내를 듣고 제목 · 숫자 · 기호를 써서 메모하세요.','{}'::text[],false,'{"seq":8,"concept":"K3-1-u4-C5","difficulty":4,"kind":"essay","stem":"이 안내를 듣고 제목 · 숫자 · 기호를 써서 메모하세요.","answer_guide":{"answer":"예: 제목 — 현장 체험학습. 1. 다음 주 수요일 2. 아침 8시 30분, 학교 정문 3. 도시락 · 물 · 모자 ★ 선생님 곁을 떠나지 않기","scoring_points":["알맞은 제목을 썼는가","숫자로 차례를 나누었는가","가장 중요한 곳에 기호를 썼는가"]},"explanation":["제목","숫자","기호"],"asset":{"type":"speech","turns":[{"who":"선생님","text":"다음 주 수요일에 현장 체험학습을 가요."},{"who":"선생님","text":"아침 여덟 시 반까지 학교 정문에 모여요."},{"who":"선생님","text":"도시락과 물, 모자를 챙겨요."},{"who":"선생님","text":"꼭 기억할 것은 선생님 곁을 떠나지 않는 거예요. 다시 말할게요. 선생님 곁을 떠나지 않아요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L02_challenge#9','kor',3,1,'u4','L02','g3_1_kor_u4_L02_challenge','lesson_challenge','K3-1-u4-C3',4,'essay','teacher','메모를 하지 않아 곤란했던 일이나 곤란할 수 있는 일을 쓰고, 메모가 어떻게 도움이 되는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-1-u4-C3","difficulty":4,"kind":"essay","stem":"메모를 하지 않아 곤란했던 일이나 곤란할 수 있는 일을 쓰고, 메모가 어떻게 도움이 되는지 쓰세요.","answer_guide":{"answer":"예: 준비물을 듣고 메모하지 않아 다음 날 색종이를 빠뜨렸다. 메모해 두면 시간이 지나도 다시 보고 빠짐없이 챙길 수 있다.","scoring_points":["곤란한 일을 썼는가","메모가 돕는 점을 썼는가","오래 기억하거나 다시 확인하는 것과 이어지는가"]},"explanation":["곤란한 일","메모","다시 확인"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L02_challenge#10','kor',3,1,'u4','L02','g3_1_kor_u4_L02_challenge','lesson_challenge','K3-1-u4-C8',4,'essay','teacher','「꿀벌이 하는 일」을 듣고 중요한 내용을 정리하고, 그중 가장 중요한 내용이 무엇인지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-1-u4-C8","difficulty":4,"kind":"essay","stem":"「꿀벌이 하는 일」을 듣고 중요한 내용을 정리하고, 그중 가장 중요한 내용이 무엇인지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 꿀을 모은다 · 꽃가루를 옮겨 열매가 맺히게 돕는다 · 춤으로 꽃이 있는 곳을 알린다. 가장 중요한 내용은 열매를 맺게 돕는 일이다. 「가장 중요한 것은」이라고 힘주어 말했기 때문이다.","scoring_points":["세 가지를 정리했는가","가장 중요한 내용을 골랐는가","힘주어 말한 것을 까닭으로 썼는가"]},"explanation":["세 가지","가장 중요한 것","까닭"],"asset":{"type":"passage","lines":["꿀벌이 하는 일을 세 가지 알려 줄게요.","첫째, 꿀벌은 꽃에서 꿀을 모아 벌집에 쌓아 둬요.","둘째, 꽃가루를 다른 꽃으로 옮겨 열매가 맺히게 도와요.","셋째, 춤을 추어 꽃이 있는 곳을 다른 벌에게 알려요.","가장 중요한 것은 꿀벌이 열매를 맺게 돕는다는 점이에요."],"title":"들은 설명 — 꿀벌이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L04_basic#1','kor',3,1,'u4','L04','g3_1_kor_u4_L04_basic','lesson_basic','K3-1-u4-C11',1,'mc','auto','영상을 볼 때 함께 살펴야 할 세 가지는 무엇일까요?',ARRAY['K3-1-u4-X10','K3-1-u4-X11','K3-1-u4-X13']::text[],false,'{"seq":1,"concept":"K3-1-u4-C11","difficulty":1,"kind":"mc","stem":"영상을 볼 때 함께 살펴야 할 세 가지는 무엇일까요?","options":[{"t":"소리 · 화면의 글 · 그림(장면)","correct":true},{"t":"소리만","mis":"K3-1-u4-X10"},{"t":"그림만","mis":"K3-1-u4-X11"},{"t":"영상 길이 · 배경 음악 · 제목 색깔","mis":"K3-1-u4-X13"}],"explanation":["소리","화면 글","그림"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L04_basic#2','kor',3,1,'u4','L04','g3_1_kor_u4_L04_basic','lesson_basic','K3-1-u4-C12',1,'mc','auto','영상에서 화면에 나오는 글은 무슨 일을 할까요?',ARRAY['K3-1-u4-X11','K3-1-u4-X13']::text[],false,'{"seq":2,"concept":"K3-1-u4-C12","difficulty":1,"kind":"mc","stem":"영상에서 화면에 나오는 글은 무슨 일을 할까요?","options":[{"t":"중요한 말을 글자로 짧게 보여 줘요.","correct":true},{"t":"꾸밈이라 읽지 않아도 돼요.","mis":"K3-1-u4-X11"},{"t":"영상을 빨리 넘기라는 표시예요.","mis":"K3-1-u4-X13"},{"t":"소리와 아무 관계가 없어요.","mis":"K3-1-u4-X11"}],"explanation":["화면 글","중요한 말","짧게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
