INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L04_basic#4','kor',3,1,'u4','L04','g3_1_kor_u4_L04_basic','lesson_basic','K3-1-u4-C16',1,'mc','auto','영상을 보고 알게 된 것을 생활과 이어 보는 방법으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X14','K3-1-u4-X13']::text[],false,'{"seq":4,"concept":"K3-1-u4-C16","difficulty":1,"kind":"mc","stem":"영상을 보고 알게 된 것을 생활과 이어 보는 방법으로 알맞은 것은 무엇일까요?","options":[{"t":"「나는 무엇을 할 수 있을까?」 생각해 본다.","correct":true},{"t":"영상 속 일은 나와 관계없다고 여긴다.","mis":"K3-1-u4-X14"},{"t":"보고 나서 바로 잊는다.","mis":"K3-1-u4-X14"},{"t":"영상이 몇 분이었는지만 기억한다.","mis":"K3-1-u4-X13"}],"explanation":["나는","무엇을","실천"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L04_basic#5','kor',3,1,'u4','L04','g3_1_kor_u4_L04_basic','lesson_basic','K3-1-u4-C11',2,'mc','auto','이 영상에서 소리로 들려준 내용은 무엇일까요?',ARRAY['K3-1-u4-X10','K3-1-u4-X12','K3-1-u4-X11']::text[],false,'{"seq":5,"concept":"K3-1-u4-C11","difficulty":2,"kind":"mc","stem":"이 영상에서 소리로 들려준 내용은 무엇일까요?","options":[{"t":"초록불이 켜져도 차가 멈췄는지 꼭 살펴요.","correct":true},{"t":"영상에는 소리가 나오지 않아요.","mis":"K3-1-u4-X10"},{"t":"아이가 손을 들고 천천히 건너요.","mis":"K3-1-u4-X12"},{"t":"멈춰요 → 살펴요 → 건너요","mis":"K3-1-u4-X11"}],"explanation":["(소리)","귀로 들은 설명","소리"],"asset":{"type":"passage","lines":["(소리) 횡단보도를 건널 때는 세 가지를 기억해요.","(화면 글) 멈춰요 → 살펴요 → 건너요","(그림) 초록불 앞에 멈춘 아이가 왼쪽과 오른쪽을 봐요.","(소리) 초록불이 켜져도 차가 멈췄는지 꼭 살펴요.","(화면 글) 차가 멈췄는지 꼭 확인!","(그림) 아이가 손을 들고 천천히 건너요."],"title":"영상 — 횡단보도를 건너는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
