INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L04_basic#9','kor',3,1,'u4','L04','g3_1_kor_u4_L04_basic','lesson_basic','K3-1-u4-C15',2,'mc','auto','영상을 보며 메모할 때 알맞은 방법은 무엇일까요?',ARRAY['K3-1-u4-X10','K3-1-u4-X11','K3-1-u4-X13']::text[],false,'{"seq":9,"concept":"K3-1-u4-C15","difficulty":2,"kind":"mc","stem":"영상을 보며 메모할 때 알맞은 방법은 무엇일까요?","options":[{"t":"소리와 화면에서 찾은 중요한 내용을 숫자로 짧게 적는다.","correct":true},{"t":"소리로 들은 말만 모두 받아 적는다.","mis":"K3-1-u4-X10"},{"t":"화면 글은 빼고 적는다.","mis":"K3-1-u4-X11"},{"t":"빨리 넘기며 생각나는 대로 적는다.","mis":"K3-1-u4-X13"}],"explanation":["소리 · 화면","중요한 내용","숫자로 짧게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L04_basic#10','kor',3,1,'u4','L04','g3_1_kor_u4_L04_basic','lesson_basic','K3-1-u4-C16',3,'mc','auto','이 영상을 보고 실천할 일로 가장 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X14','K3-1-u4-X13']::text[],false,'{"seq":10,"concept":"K3-1-u4-C16","difficulty":3,"kind":"mc","stem":"이 영상을 보고 실천할 일로 가장 알맞은 것은 무엇일까요?","options":[{"t":"집에서 페트병을 비우고 비닐을 떼어 납작하게 눌러 내놓는다.","correct":true},{"t":"영상 속 아이만 하면 되는 일이라고 여긴다.","mis":"K3-1-u4-X14"},{"t":"페트병을 그대로 아무 데나 버린다.","mis":"K3-1-u4-X14"},{"t":"영상을 빨리 넘기고 잊는다.","mis":"K3-1-u4-X13"}],"explanation":["알게 된 것","나와 관련","실천"],"asset":{"type":"passage","lines":["(소리) 페트병은 이렇게 버려요.","(화면 글) 비우고 · 떼고 · 누르고","(그림) 아이가 페트병 속 물을 비워요.","(그림) 병에 붙은 비닐을 뜯어요.","(그림) 병을 발로 꾹 눌러 납작하게 해요.","(소리) 깨끗하게 버려야 다시 쓸 수 있어요.","(화면 글) 깨끗하게 버려야 다시 써요!"],"title":"영상 — 페트병 버리는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L04_challenge#1','kor',3,1,'u4','L04','g3_1_kor_u4_L04_challenge','lesson_challenge','K3-1-u4-C13',2,'mc','auto','「페트병 버리는 방법」 영상에서 그림이 보여 준 것은 무엇일까요?',ARRAY['K3-1-u4-X12','K3-1-u4-X10','K3-1-u4-X11']::text[],false,'{"seq":1,"concept":"K3-1-u4-C13","difficulty":2,"kind":"mc","stem":"「페트병 버리는 방법」 영상에서 그림이 보여 준 것은 무엇일까요?","options":[{"t":"병을 비우고, 비닐을 뜯고, 납작하게 누르는 모습","correct":true},{"t":"그림은 재미로 넣어서 보여 준 것이 없어요","mis":"K3-1-u4-X12"},{"t":"「깨끗하게 버려야 다시 쓸 수 있어요」라는 말","mis":"K3-1-u4-X10"},{"t":"「비우고 · 떼고 · 누르고」라는 글","mis":"K3-1-u4-X11"}],"explanation":["그림","하는 모습","실제로"],"asset":{"type":"passage","lines":["(소리) 페트병은 이렇게 버려요.","(화면 글) 비우고 · 떼고 · 누르고","(그림) 아이가 페트병 속 물을 비워요.","(그림) 병에 붙은 비닐을 뜯어요.","(그림) 병을 발로 꾹 눌러 납작하게 해요.","(소리) 깨끗하게 버려야 다시 쓸 수 있어요.","(화면 글) 깨끗하게 버려야 다시 써요!"],"title":"영상 — 페트병 버리는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L04_challenge#2','kor',3,1,'u4','L04','g3_1_kor_u4_L04_challenge','lesson_challenge','K3-1-u4-C12',2,'mc','auto','「페트병 버리는 방법」의 화면 글 「비우고 · 떼고 · 누르고」는 왜 나왔을까요?',ARRAY['K3-1-u4-X11','K3-1-u4-X10','K3-1-u4-X12']::text[],false,'{"seq":2,"concept":"K3-1-u4-C12","difficulty":2,"kind":"mc","stem":"「페트병 버리는 방법」의 화면 글 「비우고 · 떼고 · 누르고」는 왜 나왔을까요?","options":[{"t":"버리는 방법의 중요한 말을 짧게 보여 주려고","correct":true},{"t":"화면을 예쁘게 꾸미려고만","mis":"K3-1-u4-X11"},{"t":"소리 대신 넣어 영상을 짧게 하려고","mis":"K3-1-u4-X10"},{"t":"그림과 관계없는 다른 이야기를 하려고","mis":"K3-1-u4-X12"}],"explanation":["화면 글","중요한 말","짧게"],"asset":{"type":"passage","lines":["(소리) 페트병은 이렇게 버려요.","(화면 글) 비우고 · 떼고 · 누르고","(그림) 아이가 페트병 속 물을 비워요.","(그림) 병에 붙은 비닐을 뜯어요.","(그림) 병을 발로 꾹 눌러 납작하게 해요.","(소리) 깨끗하게 버려야 다시 쓸 수 있어요.","(화면 글) 깨끗하게 버려야 다시 써요!"],"title":"영상 — 페트병 버리는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L04_challenge#3','kor',3,1,'u4','L04','g3_1_kor_u4_L04_challenge','lesson_challenge','K3-1-u4-C11',3,'mc','auto','눈을 감고 소리만 들으며 영상을 보면 어떤 점이 아쉬울까요?',ARRAY['K3-1-u4-X10','K3-1-u4-X13','K3-1-u4-X12']::text[],false,'{"seq":3,"concept":"K3-1-u4-C11","difficulty":3,"kind":"mc","stem":"눈을 감고 소리만 들으며 영상을 보면 어떤 점이 아쉬울까요?","options":[{"t":"화면 글과 그림이 보여 주는 중요한 내용을 놓쳐요.","correct":true},{"t":"아쉬운 점이 없어요 — 영상은 소리만 들으면 돼요.","mis":"K3-1-u4-X10"},{"t":"더 빨리 볼 수 있어 좋아요.","mis":"K3-1-u4-X13"},{"t":"그림은 원래 내용과 관계없어요.","mis":"K3-1-u4-X12"}],"explanation":["소리만","놓치는 것","셋을 함께"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L04_challenge#4','kor',3,1,'u4','L04','g3_1_kor_u4_L04_challenge','lesson_challenge','K3-1-u4-C14',3,'mc','auto','「페트병 버리는 방법」에서 강조한 내용과 그것을 알 수 있는 까닭으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X06','K3-1-u4-X13']::text[],false,'{"seq":4,"concept":"K3-1-u4-C14","difficulty":3,"kind":"mc","stem":"「페트병 버리는 방법」에서 강조한 내용과 그것을 알 수 있는 까닭으로 알맞은 것은 무엇일까요?","options":[{"t":"깨끗하게 버려야 다시 쓸 수 있다는 것 — 소리와 화면 글로 두 번 나왔어요.","correct":true},{"t":"페트병의 색깔 — 그림에 나와서","mis":"K3-1-u4-X06"},{"t":"「이렇게 버려요」 — 맨 처음 말이라서","mis":"K3-1-u4-X06"},{"t":"강조한 내용은 없어요 — 모두 똑같아요","mis":"K3-1-u4-X13"}],"explanation":["소리로 한 번","화면 글로 또","강조"],"asset":{"type":"passage","lines":["(소리) 페트병은 이렇게 버려요.","(화면 글) 비우고 · 떼고 · 누르고","(그림) 아이가 페트병 속 물을 비워요.","(그림) 병에 붙은 비닐을 뜯어요.","(그림) 병을 발로 꾹 눌러 납작하게 해요.","(소리) 깨끗하게 버려야 다시 쓸 수 있어요.","(화면 글) 깨끗하게 버려야 다시 써요!"],"title":"영상 — 페트병 버리는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L04_challenge#5','kor',3,1,'u4','L04','g3_1_kor_u4_L04_challenge','lesson_challenge','K3-1-u4-C15',3,'mc','auto','건우는 이 영상을 보며 「세 가지 / 손」이라고만 메모했어요. 더 알맞게 고친 메모는 무엇일까요?',ARRAY['K3-1-u4-X01','K3-1-u4-X02','K3-1-u4-X03']::text[],false,'{"seq":5,"concept":"K3-1-u4-C15","difficulty":3,"kind":"mc","stem":"건우는 이 영상을 보며 「세 가지 / 손」이라고만 메모했어요. 더 알맞게 고친 메모는 무엇일까요?","options":[{"t":"1. 멈춰요 2. 살펴요(차가 멈췄는지 꼭!) 3. 손 들고 건너요","correct":true},{"t":"영상에서 들린 말을 처음부터 끝까지 모두 적은 메모","mis":"K3-1-u4-X01"},{"t":"「횡단보도」 한 낱말","mis":"K3-1-u4-X02"},{"t":"메모하지 않고 다시 보기만 하기","mis":"K3-1-u4-X03"}],"explanation":["숫자로 차례","강조한 것","짧게"],"asset":{"type":"passage","lines":["(소리) 횡단보도를 건널 때는 세 가지를 기억해요.","(화면 글) 멈춰요 → 살펴요 → 건너요","(그림) 초록불 앞에 멈춘 아이가 왼쪽과 오른쪽을 봐요.","(소리) 초록불이 켜져도 차가 멈췄는지 꼭 살펴요.","(화면 글) 차가 멈췄는지 꼭 확인!","(그림) 아이가 손을 들고 천천히 건너요."],"title":"영상 — 횡단보도를 건너는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L04_challenge#6','kor',3,1,'u4','L04','g3_1_kor_u4_L04_challenge','lesson_challenge','K3-1-u4-C16',3,'mc','auto','영상을 보고 「나와 관련짓기」를 한 말로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X14','K3-1-u4-X13','K3-1-u4-X12']::text[],false,'{"seq":6,"concept":"K3-1-u4-C16","difficulty":3,"kind":"mc","stem":"영상을 보고 「나와 관련짓기」를 한 말로 알맞은 것은 무엇일까요?","options":[{"t":"「나도 학교 앞 횡단보도에서 차가 멈췄는지 꼭 살펴야겠어.」","correct":true},{"t":"「영상 속 아이는 조심성이 많네. 나랑은 상관없어.」","mis":"K3-1-u4-X14"},{"t":"「영상이 짧아서 좋았어.」","mis":"K3-1-u4-X13"},{"t":"「그림 색깔이 예뻤어.」","mis":"K3-1-u4-X12"}],"explanation":["나도","학교 앞에서","실천"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L04_challenge#7','kor',3,1,'u4','L04','g3_1_kor_u4_L04_challenge','lesson_challenge','K3-1-u4-C13',3,'mc','auto','「횡단보도를 건너는 방법」에서 아이가 왼쪽과 오른쪽을 보는 장면이 알려 주는 것은 무엇일까요?',ARRAY['K3-1-u4-X12']::text[],false,'{"seq":7,"concept":"K3-1-u4-C13","difficulty":3,"kind":"mc","stem":"「횡단보도를 건너는 방법」에서 아이가 왼쪽과 오른쪽을 보는 장면이 알려 주는 것은 무엇일까요?","options":[{"t":"「살펴요」를 어떻게 하는지 실제 모습","correct":true},{"t":"아이가 길을 잃었다는 것","mis":"K3-1-u4-X12"},{"t":"그림은 꾸밈이라 알려 주는 것이 없다는 것","mis":"K3-1-u4-X12"},{"t":"횡단보도와 관계없는 장면이라는 것","mis":"K3-1-u4-X12"}],"explanation":["그림","살피는 모습","하는 방법"],"asset":{"type":"passage","lines":["(소리) 횡단보도를 건널 때는 세 가지를 기억해요.","(화면 글) 멈춰요 → 살펴요 → 건너요","(그림) 초록불 앞에 멈춘 아이가 왼쪽과 오른쪽을 봐요.","(소리) 초록불이 켜져도 차가 멈췄는지 꼭 살펴요.","(화면 글) 차가 멈췄는지 꼭 확인!","(그림) 아이가 손을 들고 천천히 건너요."],"title":"영상 — 횡단보도를 건너는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L04_challenge#8','kor',3,1,'u4','L04','g3_1_kor_u4_L04_challenge','lesson_challenge','K3-1-u4-C11',4,'essay','teacher','이 영상에서 소리 · 화면 글 · 그림으로 알게 된 내용을 하나씩 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-1-u4-C11","difficulty":4,"kind":"essay","stem":"이 영상에서 소리 · 화면 글 · 그림으로 알게 된 내용을 하나씩 쓰세요.","answer_guide":{"answer":"예: 소리 — 초록불이 켜져도 차가 멈췄는지 꼭 살펴야 한다. 화면 글 — 멈춰요, 살펴요, 건너요의 차례. 그림 — 아이가 손을 들고 천천히 건너는 모습.","scoring_points":["소리로 알게 된 것을 썼는가","화면 글로 알게 된 것을 썼는가","그림으로 알게 된 것을 썼는가"]},"explanation":["소리","화면 글","그림"],"asset":{"type":"passage","lines":["(소리) 횡단보도를 건널 때는 세 가지를 기억해요.","(화면 글) 멈춰요 → 살펴요 → 건너요","(그림) 초록불 앞에 멈춘 아이가 왼쪽과 오른쪽을 봐요.","(소리) 초록불이 켜져도 차가 멈췄는지 꼭 살펴요.","(화면 글) 차가 멈췄는지 꼭 확인!","(그림) 아이가 손을 들고 천천히 건너요."],"title":"영상 — 횡단보도를 건너는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L04_challenge#9','kor',3,1,'u4','L04','g3_1_kor_u4_L04_challenge','lesson_challenge','K3-1-u4-C15',4,'essay','teacher','「페트병 버리는 방법」 영상을 보고 제목과 숫자를 써서 메모하세요.','{}'::text[],false,'{"seq":9,"concept":"K3-1-u4-C15","difficulty":4,"kind":"essay","stem":"「페트병 버리는 방법」 영상을 보고 제목과 숫자를 써서 메모하세요.","answer_guide":{"answer":"예: 제목 — 페트병 버리는 방법. 1. 속을 비운다. 2. 비닐을 뗀다. 3. 눌러 납작하게 한다. ★ 깨끗하게 버려야 다시 쓸 수 있다.","scoring_points":["알맞은 제목을 썼는가","숫자로 차례를 매겼는가","강조한 내용을 넣었는가"]},"explanation":["제목","숫자","강조"],"asset":{"type":"passage","lines":["(소리) 페트병은 이렇게 버려요.","(화면 글) 비우고 · 떼고 · 누르고","(그림) 아이가 페트병 속 물을 비워요.","(그림) 병에 붙은 비닐을 뜯어요.","(그림) 병을 발로 꾹 눌러 납작하게 해요.","(소리) 깨끗하게 버려야 다시 쓸 수 있어요.","(화면 글) 깨끗하게 버려야 다시 써요!"],"title":"영상 — 페트병 버리는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L04_challenge#10','kor',3,1,'u4','L04','g3_1_kor_u4_L04_challenge','lesson_challenge','K3-1-u4-C16',4,'essay','teacher','이 단원에서 본 영상 가운데 하나를 골라, 내가 생활에서 실천할 일을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-1-u4-C16","difficulty":4,"kind":"essay","stem":"이 단원에서 본 영상 가운데 하나를 골라, 내가 생활에서 실천할 일을 두 가지 쓰세요.","answer_guide":{"answer":"예: 「횡단보도를 건너는 방법」을 보고, 등굣길 횡단보도에서 초록불이 켜져도 차가 멈췄는지 살핀 뒤 건너겠다. 동생과 함께 건널 때 손을 들고 천천히 건너는 방법을 알려 주겠다.","scoring_points":["영상을 골랐는가","실천할 일 두 가지를 썼는가","영상에서 알게 된 내용과 이어지는가"]},"explanation":["영상","실천 둘","나와 관련"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L06_basic#1','kor',3,1,'u4','L06','g3_1_kor_u4_L06_basic','lesson_basic','K3-1-u4-C17',1,'mc','auto','설명하는 글은 어떤 글일까요?',ARRAY['K3-1-u4-X36','K3-1-u4-X15','K3-1-u4-X18']::text[],false,'{"seq":1,"concept":"K3-1-u4-C17","difficulty":1,"kind":"mc","stem":"설명하는 글은 어떤 글일까요?","options":[{"t":"무엇에 대해 알려 주는 글","correct":true},{"t":"있었던 일을 지어내 들려주는 글","mis":"K3-1-u4-X36"},{"t":"아무 문장이나 골라 외우면 되는 글","mis":"K3-1-u4-X15"},{"t":"제목이 필요 없는 글","mis":"K3-1-u4-X18"}],"explanation":["무엇에 대해","알려 주는","설명하는 글"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L06_basic#2','kor',3,1,'u4','L06','g3_1_kor_u4_L06_basic','lesson_basic','K3-1-u4-C18',1,'mc','auto','중심 문장은 무엇일까요?',ARRAY['K3-1-u4-X16','K3-1-u4-X17']::text[],false,'{"seq":2,"concept":"K3-1-u4-C18","difficulty":1,"kind":"mc","stem":"중심 문장은 무엇일까요?","options":[{"t":"문단을 대표하는 문장","correct":true},{"t":"문단에서 가장 긴 문장","mis":"K3-1-u4-X16"},{"t":"예를 들어 덧붙인 문장","mis":"K3-1-u4-X17"},{"t":"언제나 첫 번째 문장","mis":"K3-1-u4-X16"}],"explanation":["문단","대표","중심 문장"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L06_basic#3','kor',3,1,'u4','L06','g3_1_kor_u4_L06_basic','lesson_basic','K3-1-u4-C21',1,'mc','auto','설명하는 글에서 모르는 낱말이 나오면 어떻게 할까요?',ARRAY['K3-1-u4-X19']::text[],false,'{"seq":3,"concept":"K3-1-u4-C21","difficulty":1,"kind":"mc","stem":"설명하는 글에서 모르는 낱말이 나오면 어떻게 할까요?","options":[{"t":"앞뒤 문장을 읽고 뜻을 짐작해요.","correct":true},{"t":"건너뛰고 읽어요.","mis":"K3-1-u4-X19"},{"t":"낱말 소리만 듣고 뜻을 정해요.","mis":"K3-1-u4-X19"},{"t":"글 읽기를 그만둬요.","mis":"K3-1-u4-X19"}],"explanation":["모르는 낱말","앞뒤 문장","짐작"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L06_basic#4','kor',3,1,'u4','L06','g3_1_kor_u4_L06_basic','lesson_basic','K3-1-u4-C22',1,'mc','auto','설명하는 글을 간추리는 방법으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X20','K3-1-u4-X21','K3-1-u4-X18']::text[],false,'{"seq":4,"concept":"K3-1-u4-C22","difficulty":1,"kind":"mc","stem":"설명하는 글을 간추리는 방법으로 알맞은 것은 무엇일까요?","options":[{"t":"문단마다 중심 문장을 찾아 이어요.","correct":true},{"t":"모든 문장을 그대로 옮겨 써요.","mis":"K3-1-u4-X20"},{"t":"재미있는 예만 골라 모아요.","mis":"K3-1-u4-X21"},{"t":"제목만 써요.","mis":"K3-1-u4-X18"}],"explanation":["문단마다","중심 문장","이어서"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L06_basic#5','kor',3,1,'u4','L06','g3_1_kor_u4_L06_basic','lesson_basic','K3-1-u4-C19',2,'mc','auto','「거북의 등딱지」의 중심 문장은 무엇일까요?',ARRAY['K3-1-u4-X16','K3-1-u4-X17']::text[],false,'{"seq":5,"concept":"K3-1-u4-C19","difficulty":2,"kind":"mc","stem":"「거북의 등딱지」의 중심 문장은 무엇일까요?","options":[{"t":"이처럼 등딱지는 거북의 몸을 지켜 줍니다.","correct":true},{"t":"거북은 위험하면 머리와 다리를 등딱지 속에 쏙 넣습니다.","mis":"K3-1-u4-X16"},{"t":"단단한 등딱지는 다른 동물이 깨물어도 잘 부서지지 않습니다.","mis":"K3-1-u4-X17"},{"t":"뜨거운 햇볕도 등딱지가 막아 줍니다.","mis":"K3-1-u4-X17"}],"explanation":["세 가지 예","모두 묶는","끝 문장"],"asset":{"type":"passage","lines":["거북은 위험하면 머리와 다리를 등딱지 속에 쏙 넣습니다.","단단한 등딱지는 다른 동물이 깨물어도 잘 부서지지 않습니다.","뜨거운 햇볕도 등딱지가 막아 줍니다.","이처럼 등딱지는 거북의 몸을 지켜 줍니다."],"title":"거북의 등딱지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L06_basic#6','kor',3,1,'u4','L06','g3_1_kor_u4_L06_basic','lesson_basic','K3-1-u4-C21',2,'mc','auto','「겨울 채비」에서 「채비」의 뜻으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X19']::text[],false,'{"seq":6,"concept":"K3-1-u4-C21","difficulty":2,"kind":"mc","stem":"「겨울 채비」에서 「채비」의 뜻으로 알맞은 것은 무엇일까요?","options":[{"t":"어떤 일을 하려고 미리 갖추는 준비","correct":true},{"t":"나무의 한 종류","mis":"K3-1-u4-X19"},{"t":"겨울에 내리는 비","mis":"K3-1-u4-X19"},{"t":"나뭇잎의 색깔","mis":"K3-1-u4-X19"}],"explanation":["잎을 떨구고","껍질로 감싸고","미리 준비"],"asset":{"type":"passage","lines":["가을이 깊어지면 나무는 겨울 채비를 합니다.","잎을 떨구어 몸속의 물이 빠져나가지 않게 합니다.","봄에 틔울 겨울눈은 단단한 껍질로 꼭꼭 감쌉니다.","줄기는 두꺼운 껍질로 찬 바람을 막습니다."],"title":"겨울 채비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L06_basic#7','kor',3,1,'u4','L06','g3_1_kor_u4_L06_basic','lesson_basic','K3-1-u4-C23',2,'mc','auto','「두부가 만들어지는 과정」에서 차례를 알려 주는 말이 아닌 것은 무엇일까요?',ARRAY['K3-1-u4-X22']::text[],false,'{"seq":7,"concept":"K3-1-u4-C23","difficulty":2,"kind":"mc","stem":"「두부가 만들어지는 과정」에서 차례를 알려 주는 말이 아닌 것은 무엇일까요?","options":[{"t":"통통하게","correct":true},{"t":"먼저","mis":"K3-1-u4-X22"},{"t":"그다음","mis":"K3-1-u4-X22"},{"t":"마지막으로","mis":"K3-1-u4-X22"}],"explanation":["먼저","그다음","마지막으로"],"asset":{"type":"passage","lines":["① 먼저 콩을 물에 하룻밤 불립니다.","콩이 물을 먹어 통통하게 부풀어 오릅니다.","② 그다음 불린 콩을 갈아 끓인 뒤 천에 거릅니다.","찌꺼기는 천에 남고 콩물만 빠져나옵니다.","③ 마지막으로 콩물에 굳히는 물을 넣어 엉기게 합니다.","몽글몽글 엉긴 것을 틀에 눌러 담으면 두부가 됩니다."],"title":"두부가 만들어지는 과정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L06_basic#8','kor',3,1,'u4','L06','g3_1_kor_u4_L06_basic','lesson_basic','K3-1-u4-C18',2,'match','auto','말과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K3-1-u4-C18","difficulty":2,"kind":"match","stem":"말과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"문단","r":"한 가지 생각을 나타내는 글의 단위"},{"l":"중심 문장","r":"문단을 대표하는 문장"},{"l":"뒷받침 문장","r":"덧붙여 설명하거나 예를 드는 문장"}],"mis":"K3-1-u4-X17","explanation":["문단","중심","뒷받침"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L06_basic#9','kor',3,1,'u4','L06','g3_1_kor_u4_L06_basic','lesson_basic','K3-1-u4-C20',2,'mc','auto','설명하는 글을 읽을 때 제목을 먼저 보면 좋은 점은 무엇일까요?',ARRAY['K3-1-u4-X18','K3-1-u4-X15','K3-1-u4-X16']::text[],false,'{"seq":9,"concept":"K3-1-u4-C20","difficulty":2,"kind":"mc","stem":"설명하는 글을 읽을 때 제목을 먼저 보면 좋은 점은 무엇일까요?","options":[{"t":"무엇에 대한 글인지 미리 알 수 있어요.","correct":true},{"t":"좋은 점이 없어 건너뛰어도 돼요.","mis":"K3-1-u4-X18"},{"t":"제목만 외우면 글을 다 읽은 거예요.","mis":"K3-1-u4-X15"},{"t":"제목이 가장 긴 문장이에요.","mis":"K3-1-u4-X16"}],"explanation":["제목","무엇에 대한 글","미리 짐작"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
