INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L06_challenge#4','kor',3,1,'u4','L06','g3_1_kor_u4_L06_challenge','lesson_challenge','K3-1-u4-C18',3,'mc','auto','「거북의 등딱지」에서 「뜨거운 햇볕도 등딱지가 막아 줍니다.」는 어떤 문장일까요?',ARRAY['K3-1-u4-X17','K3-1-u4-X15','K3-1-u4-X18']::text[],false,'{"seq":4,"concept":"K3-1-u4-C18","difficulty":3,"kind":"mc","stem":"「거북의 등딱지」에서 「뜨거운 햇볕도 등딱지가 막아 줍니다.」는 어떤 문장일까요?","options":[{"t":"등딱지가 몸을 지키는 예를 덧붙인 뒷받침 문장","correct":true},{"t":"문단을 대표하는 중심 문장","mis":"K3-1-u4-X17"},{"t":"문단과 관계없는 문장","mis":"K3-1-u4-X15"},{"t":"글의 제목","mis":"K3-1-u4-X18"}],"explanation":["햇볕을 막음","지키는 예","뒷받침"],"asset":{"type":"passage","lines":["거북은 위험하면 머리와 다리를 등딱지 속에 쏙 넣습니다.","단단한 등딱지는 다른 동물이 깨물어도 잘 부서지지 않습니다.","뜨거운 햇볕도 등딱지가 막아 줍니다.","이처럼 등딱지는 거북의 몸을 지켜 줍니다."],"title":"거북의 등딱지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L06_challenge#5','kor',3,1,'u4','L06','g3_1_kor_u4_L06_challenge','lesson_challenge','K3-1-u4-C21',3,'mc','auto','「천에 거릅니다. 찌꺼기는 천에 남고 콩물만 빠져나옵니다.」에서 「거르다」의 뜻으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X19']::text[],false,'{"seq":5,"concept":"K3-1-u4-C21","difficulty":3,"kind":"mc","stem":"「천에 거릅니다. 찌꺼기는 천에 남고 콩물만 빠져나옵니다.」에서 「거르다」의 뜻으로 알맞은 것은 무엇일까요?","options":[{"t":"찌꺼기는 남기고 물만 빠져나가게 하다","correct":true},{"t":"걸어서 다니다","mis":"K3-1-u4-X19"},{"t":"물에 오래 담가 두다","mis":"K3-1-u4-X19"},{"t":"끓여서 뜨겁게 하다","mis":"K3-1-u4-X19"}],"explanation":["찌꺼기는 남고","콩물만 빠져나옴","거르다"],"asset":{"type":"passage","lines":["① 먼저 콩을 물에 하룻밤 불립니다.","콩이 물을 먹어 통통하게 부풀어 오릅니다.","② 그다음 불린 콩을 갈아 끓인 뒤 천에 거릅니다.","찌꺼기는 천에 남고 콩물만 빠져나옵니다.","③ 마지막으로 콩물에 굳히는 물을 넣어 엉기게 합니다.","몽글몽글 엉긴 것을 틀에 눌러 담으면 두부가 됩니다."],"title":"두부가 만들어지는 과정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L06_challenge#6','kor',3,1,'u4','L06','g3_1_kor_u4_L06_challenge','lesson_challenge','K3-1-u4-C22',3,'mc','auto','「겨울 채비」를 한 문장으로 간추린 것으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X21','K3-1-u4-X20']::text[],false,'{"seq":6,"concept":"K3-1-u4-C22","difficulty":3,"kind":"mc","stem":"「겨울 채비」를 한 문장으로 간추린 것으로 알맞은 것은 무엇일까요?","options":[{"t":"나무는 잎을 떨구고 겨울눈과 줄기를 껍질로 감싸 겨울 채비를 한다.","correct":true},{"t":"나무는 잎을 떨군다.","mis":"K3-1-u4-X21"},{"t":"글의 네 문장을 하나도 빼지 않고 그대로 옮긴 것","mis":"K3-1-u4-X20"},{"t":"나무는 봄을 기다린다.","mis":"K3-1-u4-X21"}],"explanation":["중심 생각","예를 묶어","한 문장"],"asset":{"type":"passage","lines":["가을이 깊어지면 나무는 겨울 채비를 합니다.","잎을 떨구어 몸속의 물이 빠져나가지 않게 합니다.","봄에 틔울 겨울눈은 단단한 껍질로 꼭꼭 감쌉니다.","줄기는 두꺼운 껍질로 찬 바람을 막습니다."],"title":"겨울 채비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L06_challenge#7','kor',3,1,'u4','L06','g3_1_kor_u4_L06_challenge','lesson_challenge','K3-1-u4-C23',3,'mc','auto','「두부가 만들어지는 과정」에서 콩을 갈아 끓이는 일은 언제 할까요?',ARRAY['K3-1-u4-X22']::text[],false,'{"seq":7,"concept":"K3-1-u4-C23","difficulty":3,"kind":"mc","stem":"「두부가 만들어지는 과정」에서 콩을 갈아 끓이는 일은 언제 할까요?","options":[{"t":"콩을 물에 불린 다음","correct":true},{"t":"콩물을 틀에 눌러 담은 다음","mis":"K3-1-u4-X22"},{"t":"콩을 불리기 전","mis":"K3-1-u4-X22"},{"t":"맨 마지막","mis":"K3-1-u4-X22"}],"explanation":["먼저 불리기","그다음 갈기","차례"],"asset":{"type":"passage","lines":["① 먼저 콩을 물에 하룻밤 불립니다.","콩이 물을 먹어 통통하게 부풀어 오릅니다.","② 그다음 불린 콩을 갈아 끓인 뒤 천에 거릅니다.","찌꺼기는 천에 남고 콩물만 빠져나옵니다.","③ 마지막으로 콩물에 굳히는 물을 넣어 엉기게 합니다.","몽글몽글 엉긴 것을 틀에 눌러 담으면 두부가 됩니다."],"title":"두부가 만들어지는 과정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L06_challenge#8','kor',3,1,'u4','L06','g3_1_kor_u4_L06_challenge','lesson_challenge','K3-1-u4-C19',4,'essay','teacher','「거북의 등딱지」의 중심 문장을 찾아 쓰고, 그 문장이 중심 문장인 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-1-u4-C19","difficulty":4,"kind":"essay","stem":"「거북의 등딱지」의 중심 문장을 찾아 쓰고, 그 문장이 중심 문장인 까닭을 쓰세요.","answer_guide":{"answer":"예: 중심 문장은 「이처럼 등딱지는 거북의 몸을 지켜 줍니다.」이다. 나머지 세 문장이 머리와 다리 숨기기 · 깨물어도 안 부서짐 · 햇볕 막기처럼 몸을 지키는 예를 하나씩 말하고, 이 문장이 그것을 모두 묶어 주기 때문이다.","scoring_points":["중심 문장을 바르게 찾았는가","나머지 문장이 예라는 것을 썼는가","모두 묶어 준다는 까닭을 썼는가"]},"explanation":["중심 문장","예","묶어 주는 까닭"],"asset":{"type":"passage","lines":["거북은 위험하면 머리와 다리를 등딱지 속에 쏙 넣습니다.","단단한 등딱지는 다른 동물이 깨물어도 잘 부서지지 않습니다.","뜨거운 햇볕도 등딱지가 막아 줍니다.","이처럼 등딱지는 거북의 몸을 지켜 줍니다."],"title":"거북의 등딱지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L06_challenge#9','kor',3,1,'u4','L06','g3_1_kor_u4_L06_challenge','lesson_challenge','K3-1-u4-C22',4,'essay','teacher','「두부가 만들어지는 과정」의 문단마다 중심 문장을 찾아 이어서 간추려 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-1-u4-C22","difficulty":4,"kind":"essay","stem":"「두부가 만들어지는 과정」의 문단마다 중심 문장을 찾아 이어서 간추려 쓰세요.","answer_guide":{"answer":"예: 먼저 콩을 물에 하룻밤 불린다. 그다음 불린 콩을 갈아 끓인 뒤 천에 거른다. 마지막으로 콩물에 굳히는 물을 넣어 엉기게 한다.","scoring_points":["세 문단의 중심 문장을 찾았는가","차례대로 이었는가","뒷받침 내용은 줄였는가"]},"explanation":["문단마다","중심 문장","차례대로"],"asset":{"type":"passage","lines":["① 먼저 콩을 물에 하룻밤 불립니다.","콩이 물을 먹어 통통하게 부풀어 오릅니다.","② 그다음 불린 콩을 갈아 끓인 뒤 천에 거릅니다.","찌꺼기는 천에 남고 콩물만 빠져나옵니다.","③ 마지막으로 콩물에 굳히는 물을 넣어 엉기게 합니다.","몽글몽글 엉긴 것을 틀에 눌러 담으면 두부가 됩니다."],"title":"두부가 만들어지는 과정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L06_challenge#10','kor',3,1,'u4','L06','g3_1_kor_u4_L06_challenge','lesson_challenge','K3-1-u4-C21',4,'essay','teacher','「겨울 채비」에서 뜻을 짐작한 낱말 하나를 골라 짐작한 뜻과 그렇게 짐작한 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-1-u4-C21","difficulty":4,"kind":"essay","stem":"「겨울 채비」에서 뜻을 짐작한 낱말 하나를 골라 짐작한 뜻과 그렇게 짐작한 까닭을 쓰세요.","answer_guide":{"answer":"예: 「떨구다」 — 아래로 떨어지게 하다. 가을에 나뭇잎이 떨어지는 모습이 떠오르고, 앞에 「잎을」이 있어서 그렇게 짐작했다.","scoring_points":["낱말을 골랐는가","짐작한 뜻을 썼는가","앞뒤 문장에서 까닭을 찾았는가"]},"explanation":["낱말","뜻","앞뒤 문장"],"asset":{"type":"passage","lines":["가을이 깊어지면 나무는 겨울 채비를 합니다.","잎을 떨구어 몸속의 물이 빠져나가지 않게 합니다.","봄에 틔울 겨울눈은 단단한 껍질로 꼭꼭 감쌉니다.","줄기는 두꺼운 껍질로 찬 바람을 막습니다."],"title":"겨울 채비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L08_basic#1','kor',3,1,'u4','L08','g3_1_kor_u4_L08_basic','lesson_basic','K3-1-u4-C24',1,'mc','auto','이야기에서 일어난 일을 정리하는 방법으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X23','K3-1-u4-X27']::text[],false,'{"seq":1,"concept":"K3-1-u4-C24","difficulty":1,"kind":"mc","stem":"이야기에서 일어난 일을 정리하는 방법으로 알맞은 것은 무엇일까요?","options":[{"t":"시간 차례대로 정리한다.","correct":true},{"t":"생각나는 대로 뒤섞어 정리한다.","mis":"K3-1-u4-X23"},{"t":"끝부분만 읽고 정리한다.","mis":"K3-1-u4-X27"},{"t":"그림만 보고 정리한다.","mis":"K3-1-u4-X27"}],"explanation":["처음","그다음","시간 차례"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L08_basic#2','kor',3,1,'u4','L08','g3_1_kor_u4_L08_basic','lesson_basic','K3-1-u4-C25',1,'mc','auto','이야기를 읽을 때 장소를 살피면 좋은 점은 무엇일까요?',ARRAY['K3-1-u4-X24','K3-1-u4-X27','K3-1-u4-X25']::text[],false,'{"seq":2,"concept":"K3-1-u4-C25","difficulty":1,"kind":"mc","stem":"이야기를 읽을 때 장소를 살피면 좋은 점은 무엇일까요?","options":[{"t":"일이 어디에서 일어났는지 알아 장면이 잘 떠올라요.","correct":true},{"t":"장소는 중요하지 않아 살필 필요가 없어요.","mis":"K3-1-u4-X24"},{"t":"장소만 알면 이야기를 다 알아요.","mis":"K3-1-u4-X27"},{"t":"장소를 보면 인물의 마음이 언제나 같아요.","mis":"K3-1-u4-X25"}],"explanation":["어디에서","장면","장소"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
