INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L08_basic#4','kor',3,1,'u4','L08','g3_1_kor_u4_L08_basic','lesson_basic','K3-1-u4-C29',1,'mc','auto','이야기를 읽고 비슷한 내 경험을 떠올리면 좋은 점은 무엇일까요?',ARRAY['K3-1-u4-X28','K3-1-u4-X27','K3-1-u4-X25']::text[],false,'{"seq":4,"concept":"K3-1-u4-C29","difficulty":1,"kind":"mc","stem":"이야기를 읽고 비슷한 내 경험을 떠올리면 좋은 점은 무엇일까요?","options":[{"t":"인물의 마음을 더 잘 알 수 있어요.","correct":true},{"t":"이야기와 관계없는 내 이야기를 길게 할 수 있어요.","mis":"K3-1-u4-X28"},{"t":"이야기를 끝까지 읽지 않아도 돼요.","mis":"K3-1-u4-X27"},{"t":"인물의 마음은 늘 같다는 것을 알아요.","mis":"K3-1-u4-X25"}],"explanation":["닮은 경험","마음","가깝게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L08_basic#5','kor',3,1,'u4','L08','g3_1_kor_u4_L08_basic','lesson_basic','K3-1-u4-C24',2,'mc','auto','「할머니 댁 감나무」에서 가장 먼저 일어난 일은 무엇일까요?',ARRAY['K3-1-u4-X23']::text[],false,'{"seq":5,"concept":"K3-1-u4-C24","difficulty":2,"kind":"mc","stem":"「할머니 댁 감나무」에서 가장 먼저 일어난 일은 무엇일까요?","options":[{"t":"준서가 할머니 댁에 감을 따러 갔다.","correct":true},{"t":"감이 땅에 떨어져 터졌다.","mis":"K3-1-u4-X23"},{"t":"옆집 할아버지께 감을 갖다드렸다.","mis":"K3-1-u4-X23"},{"t":"할머니와 함께 감을 땄다.","mis":"K3-1-u4-X23"}],"explanation":["가을","할머니 댁","처음"],"asset":{"type":"passage","lines":["가을, 준서는 시골 할머니 댁에 감을 따러 갔습니다.","마당의 감나무에는 주황색 감이 주렁주렁 달려 있었습니다.","준서는 신이 나서 긴 장대로 감을 툭 쳤습니다.","감은 땅에 떨어져 퍽 터져 버렸습니다. 준서는 울상이 되었습니다.","할머니가 웃으며 「감은 바구니로 받쳐야 안 터진단다.」 하셨습니다.","둘이 함께 감을 따니 바구니가 금세 가득 찼습니다.","저녁에 준서는 옆집 할아버지께 감 한 바구니를 갖다드렸습니다.","「고맙다.」라는 말을 듣고 준서의 얼굴이 환해졌습니다."],"title":"할머니 댁 감나무"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
