INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L08_challenge#7','kor',3,1,'u4','L08','g3_1_kor_u4_L08_challenge','lesson_challenge','K3-1-u4-C28',3,'mc','auto','이야기를 간추릴 때 알맞은 방법은 무엇일까요?',ARRAY['K3-1-u4-X27','K3-1-u4-X20','K3-1-u4-X21']::text[],false,'{"seq":7,"concept":"K3-1-u4-C28","difficulty":3,"kind":"mc","stem":"이야기를 간추릴 때 알맞은 방법은 무엇일까요?","options":[{"t":"처음 · 가운데 · 끝에서 중요한 일만 골라 차례대로 잇는다.","correct":true},{"t":"끝부분만 읽고 끝에 일어난 일만 쓴다.","mis":"K3-1-u4-X27"},{"t":"모든 문장을 그대로 옮긴다.","mis":"K3-1-u4-X20"},{"t":"재미있는 장면 하나만 길게 쓴다.","mis":"K3-1-u4-X21"}],"explanation":["처음 · 가운데 · 끝","중요한 일","차례대로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L08_challenge#8','kor',3,1,'u4','L08','g3_1_kor_u4_L08_challenge','lesson_challenge','K3-1-u4-C24',4,'essay','teacher','「할머니 댁 감나무」에서 일어난 일을 처음 · 가운데 · 끝으로 나누어 차례대로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-1-u4-C24","difficulty":4,"kind":"essay","stem":"「할머니 댁 감나무」에서 일어난 일을 처음 · 가운데 · 끝으로 나누어 차례대로 쓰세요.","answer_guide":{"answer":"예: 처음 — 준서가 할머니 댁에 감을 따러 가서 장대로 감을 쳤다. 가운데 — 감이 터지자 할머니가 바구니로 받치는 방법을 알려 주셨다. 끝 — 함께 딴 감을 옆집 할아버지께 드리고 고맙다는 말을 들었다.","scoring_points":["처음에 일어난 일을 썼는가","가운데에 일어난 일을 썼는가","끝에 일어난 일을 차례대로 썼는가"]},"explanation":["처음","가운데","끝"],"asset":{"type":"passage","lines":["가을, 준서는 시골 할머니 댁에 감을 따러 갔습니다.","마당의 감나무에는 주황색 감이 주렁주렁 달려 있었습니다.","준서는 신이 나서 긴 장대로 감을 툭 쳤습니다.","감은 땅에 떨어져 퍽 터져 버렸습니다. 준서는 울상이 되었습니다.","할머니가 웃으며 「감은 바구니로 받쳐야 안 터진단다.」 하셨습니다.","둘이 함께 감을 따니 바구니가 금세 가득 찼습니다.","저녁에 준서는 옆집 할아버지께 감 한 바구니를 갖다드렸습니다.","「고맙다.」라는 말을 듣고 준서의 얼굴이 환해졌습니다."],"title":"할머니 댁 감나무"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L08_challenge#9','kor',3,1,'u4','L08','g3_1_kor_u4_L08_challenge','lesson_challenge','K3-1-u4-C26',4,'essay','teacher','준서의 마음이 어떻게 바뀌었는지 쓰고, 그렇게 짐작한 단서를 이야기에서 찾아 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-1-u4-C26","difficulty":4,"kind":"essay","stem":"준서의 마음이 어떻게 바뀌었는지 쓰고, 그렇게 짐작한 단서를 이야기에서 찾아 쓰세요.","answer_guide":{"answer":"예: 신났다가 속상했다가 기뻐졌다. 「신이 나서」, 「울상이 되었습니다」, 「얼굴이 환해졌습니다」라는 말과 표정을 보고 짐작했다.","scoring_points":["마음의 변화를 차례대로 썼는가","이야기 속 말 · 행동 · 표정을 단서로 들었는가","단서와 마음이 어울리는가"]},"explanation":["바뀐 마음","단서","이야기 속"],"asset":{"type":"passage","lines":["가을, 준서는 시골 할머니 댁에 감을 따러 갔습니다.","마당의 감나무에는 주황색 감이 주렁주렁 달려 있었습니다.","준서는 신이 나서 긴 장대로 감을 툭 쳤습니다.","감은 땅에 떨어져 퍽 터져 버렸습니다. 준서는 울상이 되었습니다.","할머니가 웃으며 「감은 바구니로 받쳐야 안 터진단다.」 하셨습니다.","둘이 함께 감을 따니 바구니가 금세 가득 찼습니다.","저녁에 준서는 옆집 할아버지께 감 한 바구니를 갖다드렸습니다.","「고맙다.」라는 말을 듣고 준서의 얼굴이 환해졌습니다."],"title":"할머니 댁 감나무"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L08_challenge#10','kor',3,1,'u4','L08','g3_1_kor_u4_L08_challenge','lesson_challenge','K3-1-u4-C29',4,'essay','teacher','준서처럼 처음에는 잘 안 되었다가 해낸 내 경험을 쓰고, 그때 마음이 어떻게 바뀌었는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-1-u4-C29","difficulty":4,"kind":"essay","stem":"준서처럼 처음에는 잘 안 되었다가 해낸 내 경험을 쓰고, 그때 마음이 어떻게 바뀌었는지 쓰세요.","answer_guide":{"answer":"예: 처음 리코더를 불 때 삑삑 소리만 나서 속상했다. 선생님께 손가락 막는 법을 배워 다시 연습했더니 노래 한 곡을 끝까지 불 수 있어 뿌듯했다.","scoring_points":["이야기와 닮은 경험을 썼는가","처음 마음을 썼는가","바뀐 마음을 썼는가"]},"explanation":["닮은 경험","처음 마음","바뀐 마음"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L11_basic#1','kor',3,1,'u4','L11','g3_1_kor_u4_L11_basic','lesson_basic','K3-1-u4-C30',1,'mc','auto','만드는 방법을 알려 주는 영상을 보고 메모할 때 알맞은 방법은 무엇일까요?',ARRAY['K3-1-u4-X29','K3-1-u4-X01','K3-1-u4-X02']::text[],false,'{"seq":1,"concept":"K3-1-u4-C30","difficulty":1,"kind":"mc","stem":"만드는 방법을 알려 주는 영상을 보고 메모할 때 알맞은 방법은 무엇일까요?","options":[{"t":"만드는 차례대로 숫자를 붙여 적는다.","correct":true},{"t":"차례를 섞어 생각나는 대로 적는다.","mis":"K3-1-u4-X29"},{"t":"들은 말을 하나도 빼지 않고 적는다.","mis":"K3-1-u4-X01"},{"t":"낱말 하나만 적는다.","mis":"K3-1-u4-X02"}],"explanation":["만드는 차례","숫자","메모"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L11_basic#2','kor',3,1,'u4','L11','g3_1_kor_u4_L11_basic','lesson_basic','K3-1-u4-C31',1,'mc','auto','메모한 내용을 발표할 때 알맞은 태도는 무엇일까요?',ARRAY['K3-1-u4-X30']::text[],false,'{"seq":2,"concept":"K3-1-u4-C31","difficulty":1,"kind":"mc","stem":"메모한 내용을 발표할 때 알맞은 태도는 무엇일까요?","options":[{"t":"듣는 친구를 보며 또박또박 말한다.","correct":true},{"t":"메모를 아주 빠르게 읽어 버린다.","mis":"K3-1-u4-X30"},{"t":"친구 발표의 흠만 찾는다.","mis":"K3-1-u4-X30"},{"t":"작은 목소리로 혼잣말하듯 말한다.","mis":"K3-1-u4-X30"}],"explanation":["듣는 친구","또박또박","발표"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L11_basic#3','kor',3,1,'u4','L11','g3_1_kor_u4_L11_basic','lesson_basic','K3-1-u4-C33',1,'mc','auto','띄어쓰기를 바르게 한 문장은 무엇일까요?',ARRAY['K3-1-u4-X33','K3-1-u4-X32']::text[],false,'{"seq":3,"concept":"K3-1-u4-C33","difficulty":1,"kind":"mc","stem":"띄어쓰기를 바르게 한 문장은 무엇일까요?","options":[{"t":"나는 학교에 간다.","correct":true},{"t":"나 는 학교 에 간다.","mis":"K3-1-u4-X33"},{"t":"나는학교에간다.","mis":"K3-1-u4-X32"},{"t":"나는 학 교에 간다.","mis":"K3-1-u4-X32"}],"explanation":["낱말은 띄우고","붙는 말은 붙여","바르게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L11_basic#4','kor',3,1,'u4','L11','g3_1_kor_u4_L11_basic','lesson_basic','K3-1-u4-C34',1,'mc','auto','생각그물은 무엇일까요?',ARRAY['K3-1-u4-X34','K3-1-u4-X01']::text[],false,'{"seq":4,"concept":"K3-1-u4-C34","difficulty":1,"kind":"mc","stem":"생각그물은 무엇일까요?","options":[{"t":"한 가지 주제와 관련된 낱말을 기준에 따라 가지처럼 나누어 모은 것","correct":true},{"t":"아무 낱말이나 섞어 늘어놓은 것","mis":"K3-1-u4-X34"},{"t":"그림 한 장","mis":"K3-1-u4-X34"},{"t":"들은 말을 모두 받아 적은 것","mis":"K3-1-u4-X01"}],"explanation":["주제","기준","가지"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L11_basic#5','kor',3,1,'u4','L11','g3_1_kor_u4_L11_basic','lesson_basic','K3-1-u4-C30',2,'mc','auto','「종이컵 전화기 만들기」에서 두 번째로 할 일은 무엇일까요?',ARRAY['K3-1-u4-X29']::text[],false,'{"seq":5,"concept":"K3-1-u4-C30","difficulty":2,"kind":"mc","stem":"「종이컵 전화기 만들기」에서 두 번째로 할 일은 무엇일까요?","options":[{"t":"구멍에 실을 넣고 컵 안쪽에서 매듭을 짓는다.","correct":true},{"t":"종이컵 바닥에 구멍을 뚫는다.","mis":"K3-1-u4-X29"},{"t":"실을 팽팽하게 당겨 말한다.","mis":"K3-1-u4-X29"},{"t":"컵에 색칠을 한다.","mis":"K3-1-u4-X29"}],"explanation":["구멍","실 · 매듭","차례"],"asset":{"type":"passage","lines":["(소리) 종이컵 전화기를 만들어 봐요.","(그림) 어른과 함께 종이컵 두 개의 바닥 가운데에 작은 구멍을 뚫어요.","(그림) 구멍에 실을 넣고 컵 안쪽에서 매듭을 지어요.","(그림) 다른 컵에도 실 끝을 똑같이 끼워 묶어요.","(소리) 가장 중요한 것! 실을 팽팽하게 당겨야 소리가 잘 들려요.","(화면 글) 실은 팽팽하게!"],"title":"영상 — 종이컵 전화기 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L11_basic#6','kor',3,1,'u4','L11','g3_1_kor_u4_L11_basic','lesson_basic','K3-1-u4-C31',2,'mc','auto','이 설명에서 손가락 사이와 손톱 밑을 씻으면 좋은 점은 무엇일까요?',ARRAY['K3-1-u4-X37']::text[],false,'{"seq":6,"concept":"K3-1-u4-C31","difficulty":2,"kind":"mc","stem":"이 설명에서 손가락 사이와 손톱 밑을 씻으면 좋은 점은 무엇일까요?","options":[{"t":"숨은 때까지 없앨 수 있어요.","correct":true},{"t":"손이 트지 않아요.","mis":"K3-1-u4-X37"},{"t":"비누 거품이 많이 나요.","mis":"K3-1-u4-X37"},{"t":"손이 빨리 말라요.","mis":"K3-1-u4-X37"}],"explanation":["방법","좋은 점","짝"],"asset":{"type":"passage","lines":["손을 바르게 씻는 방법을 알려 줄게요.","첫째, 비누 거품을 내어 손바닥과 손등을 문질러요. 그러면 묻은 때가 잘 빠져요.","둘째, 손가락 사이와 손톱 밑도 꼼꼼히 씻어요. 그러면 숨은 때까지 없앨 수 있어요.","셋째, 깨끗한 수건으로 물기를 닦아요. 그러면 손이 트지 않아요."],"title":"들은 설명 — 손을 바르게 씻는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L11_basic#7','kor',3,1,'u4','L11','g3_1_kor_u4_L11_basic','lesson_basic','K3-1-u4-C32',2,'mc','auto','내 메모를 점검하는 물음으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X31','K3-1-u4-X01']::text[],false,'{"seq":7,"concept":"K3-1-u4-C32","difficulty":2,"kind":"mc","stem":"내 메모를 점검하는 물음으로 알맞은 것은 무엇일까요?","options":[{"t":"중요한 내용을 한눈에 알아볼 수 있나요?","correct":true},{"t":"글자가 몇 개인가요?","mis":"K3-1-u4-X31"},{"t":"친구 메모보다 긴가요?","mis":"K3-1-u4-X31"},{"t":"들은 말을 하나도 빼지 않았나요?","mis":"K3-1-u4-X01"}],"explanation":["제목","숫자 · 기호","한눈에"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L11_basic#8','kor',3,1,'u4','L11','g3_1_kor_u4_L11_basic','lesson_basic','K3-1-u4-C33',2,'mc','auto','「누나가 죽을 먹는다」를 「누나 가죽을 먹는다」로 쓰면 어떻게 될까요?',ARRAY['K3-1-u4-X32','K3-1-u4-X33']::text[],false,'{"seq":8,"concept":"K3-1-u4-C33","difficulty":2,"kind":"mc","stem":"「누나가 죽을 먹는다」를 「누나 가죽을 먹는다」로 쓰면 어떻게 될까요?","options":[{"t":"누나의 가죽을 먹는다는 엉뚱한 뜻이 돼요.","correct":true},{"t":"뜻은 그대로예요 — 띄어쓰기는 뜻과 관계없어요.","mis":"K3-1-u4-X32"},{"t":"더 바르게 쓴 문장이 돼요.","mis":"K3-1-u4-X33"},{"t":"읽기가 더 쉬워져요.","mis":"K3-1-u4-X32"}],"explanation":["띄어쓰기","뜻","달라져요"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
