INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L11_challenge#3','kor',3,1,'u4','L11','g3_1_kor_u4_L11_challenge','lesson_challenge','K3-1-u4-C30',3,'mc','auto','건우의 메모 「실을 묶는다 / 구멍을 뚫는다 / 팽팽하게」를 바르게 고친 것은 무엇일까요?',ARRAY['K3-1-u4-X29','K3-1-u4-X01']::text[],false,'{"seq":3,"concept":"K3-1-u4-C30","difficulty":3,"kind":"mc","stem":"건우의 메모 「실을 묶는다 / 구멍을 뚫는다 / 팽팽하게」를 바르게 고친 것은 무엇일까요?","options":[{"t":"1. 바닥에 구멍 뚫기 2. 실 넣고 매듭 짓기 3. ★ 실을 팽팽하게 당기기","correct":true},{"t":"1. 실 묶기 2. 구멍 뚫기 3. 팽팽하게","mis":"K3-1-u4-X29"},{"t":"구멍 · 실 · 매듭 · 팽팽(차례 없이)","mis":"K3-1-u4-X29"},{"t":"영상에서 들린 말을 처음부터 끝까지 모두","mis":"K3-1-u4-X01"}],"explanation":["차례","숫자","강조"],"asset":{"type":"passage","lines":["(소리) 종이컵 전화기를 만들어 봐요.","(그림) 어른과 함께 종이컵 두 개의 바닥 가운데에 작은 구멍을 뚫어요.","(그림) 구멍에 실을 넣고 컵 안쪽에서 매듭을 지어요.","(그림) 다른 컵에도 실 끝을 똑같이 끼워 묶어요.","(소리) 가장 중요한 것! 실을 팽팽하게 당겨야 소리가 잘 들려요.","(화면 글) 실은 팽팽하게!"],"title":"영상 — 종이컵 전화기 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L11_challenge#4','kor',3,1,'u4','L11','g3_1_kor_u4_L11_challenge','lesson_challenge','K3-1-u4-C31',3,'mc','auto','이 설명을 메모할 때 방법과 좋은 점을 바르게 짝지은 것은 무엇일까요?',ARRAY['K3-1-u4-X37']::text[],false,'{"seq":4,"concept":"K3-1-u4-C31","difficulty":3,"kind":"mc","stem":"이 설명을 메모할 때 방법과 좋은 점을 바르게 짝지은 것은 무엇일까요?","options":[{"t":"수건으로 물기 닦기 — 손이 트지 않음","correct":true},{"t":"비누 거품으로 문지르기 — 손이 트지 않음","mis":"K3-1-u4-X37"},{"t":"손가락 사이 씻기 — 묻은 때가 잘 빠짐","mis":"K3-1-u4-X37"},{"t":"수건으로 물기 닦기 — 숨은 때까지 없앰","mis":"K3-1-u4-X37"}],"explanation":["그러면","좋은 점","짝"],"asset":{"type":"passage","lines":["손을 바르게 씻는 방법을 알려 줄게요.","첫째, 비누 거품을 내어 손바닥과 손등을 문질러요. 그러면 묻은 때가 잘 빠져요.","둘째, 손가락 사이와 손톱 밑도 꼼꼼히 씻어요. 그러면 숨은 때까지 없앨 수 있어요.","셋째, 깨끗한 수건으로 물기를 닦아요. 그러면 손이 트지 않아요."],"title":"들은 설명 — 손을 바르게 씻는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L11_challenge#5','kor',3,1,'u4','L11','g3_1_kor_u4_L11_challenge','lesson_challenge','K3-1-u4-C31',3,'mc','auto','소율이의 발표를 듣고 해 줄 말로 가장 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X30']::text[],false,'{"seq":5,"concept":"K3-1-u4-C31","difficulty":3,"kind":"mc","stem":"소율이의 발표를 듣고 해 줄 말로 가장 알맞은 것은 무엇일까요?","options":[{"t":"「차례를 숫자로 말해서 따라 하기 쉬웠어.」","correct":true},{"t":"「빨리 끝내서 좋았어. 다음엔 더 빨리 읽어.」","mis":"K3-1-u4-X30"},{"t":"「흠 하나만 말할게. 그것밖에 안 들렸어.」","mis":"K3-1-u4-X30"},{"t":"「발표는 들을 필요 없어.」","mis":"K3-1-u4-X30"}],"explanation":["잘한 점","칭찬","구체적으로"],"asset":{"type":"speech","turns":[{"who":"소율","text":"종이컵 전화기 만드는 방법을 발표할게요."},{"who":"소율","text":"첫째, 종이컵 바닥에 작은 구멍을 뚫어요. 둘째, 실을 넣고 매듭을 지어요."},{"who":"소율","text":"셋째, 가장 중요한 것! 실을 팽팽하게 당겨요. 그래야 소리가 잘 들려요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L11_challenge#6','kor',3,1,'u4','L11','g3_1_kor_u4_L11_challenge','lesson_challenge','K3-1-u4-C32',3,'mc','auto','예린이의 메모를 점검표로 살폈어요. 더 고치면 좋을 점은 무엇일까요?',ARRAY['K3-1-u4-X31','K3-1-u4-X09']::text[],false,'{"seq":6,"concept":"K3-1-u4-C32","difficulty":3,"kind":"mc","stem":"예린이의 메모를 점검표로 살폈어요. 더 고치면 좋을 점은 무엇일까요?","options":[{"t":"무엇에 대한 메모인지 알맞은 제목을 붙인다.","correct":true},{"t":"글자 수를 더 늘린다.","mis":"K3-1-u4-X31"},{"t":"모든 줄에 별표를 붙인다.","mis":"K3-1-u4-X09"},{"t":"점검할 필요 없이 그대로 낸다.","mis":"K3-1-u4-X31"}],"explanation":["제목","숫자 ✓","한눈에"],"asset":{"type":"passage","lines":["1. 비누 거품으로 문지르기 → 때가 잘 빠짐","2. 손가락 사이 · 손톱 밑 씻기 → 숨은 때까지","3. 수건으로 물기 닦기 → 손이 트지 않음"],"title":"예린이의 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L11_challenge#7','kor',3,1,'u4','L11','g3_1_kor_u4_L11_challenge','lesson_challenge','K3-1-u4-C35',3,'mc','auto','안내 방송을 들을 때 배운 내용을 살린 모습으로 가장 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X35','K3-1-u4-X01','K3-1-u4-X06']::text[],false,'{"seq":7,"concept":"K3-1-u4-C35","difficulty":3,"kind":"mc","stem":"안내 방송을 들을 때 배운 내용을 살린 모습으로 가장 알맞은 것은 무엇일까요?","options":[{"t":"무엇을 알려 주는지 생각하며 듣고 꼭 해야 할 일을 짧게 적는다.","correct":true},{"t":"국어 공부가 아니니 흘려듣는다.","mis":"K3-1-u4-X35"},{"t":"방송한 말을 하나도 빼지 않고 받아 적는다.","mis":"K3-1-u4-X01"},{"t":"가장 신기한 말 하나만 기억한다.","mis":"K3-1-u4-X06"}],"explanation":["목적","꼭 해야 할 일","짧게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L11_challenge#8','kor',3,1,'u4','L11','g3_1_kor_u4_L11_challenge','lesson_challenge','K3-1-u4-C30',4,'essay','teacher','「종이컵 전화기 만들기」 영상을 보고 제목 · 숫자 · 기호를 써서 메모하세요.','{}'::text[],false,'{"seq":8,"concept":"K3-1-u4-C30","difficulty":4,"kind":"essay","stem":"「종이컵 전화기 만들기」 영상을 보고 제목 · 숫자 · 기호를 써서 메모하세요.","answer_guide":{"answer":"예: 제목 — 종이컵 전화기 만들기. 1. 어른과 함께 컵 바닥에 구멍 뚫기 2. 실을 넣고 안쪽에서 매듭 짓기 3. 다른 컵에도 묶기 ★ 실을 팽팽하게 당기기","scoring_points":["알맞은 제목을 썼는가","만드는 차례대로 숫자를 붙였는가","강조한 내용에 기호를 썼는가"]},"explanation":["제목","숫자","기호"],"asset":{"type":"passage","lines":["(소리) 종이컵 전화기를 만들어 봐요.","(그림) 어른과 함께 종이컵 두 개의 바닥 가운데에 작은 구멍을 뚫어요.","(그림) 구멍에 실을 넣고 컵 안쪽에서 매듭을 지어요.","(그림) 다른 컵에도 실 끝을 똑같이 끼워 묶어요.","(소리) 가장 중요한 것! 실을 팽팽하게 당겨야 소리가 잘 들려요.","(화면 글) 실은 팽팽하게!"],"title":"영상 — 종이컵 전화기 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L11_challenge#9','kor',3,1,'u4','L11','g3_1_kor_u4_L11_challenge','lesson_challenge','K3-1-u4-C33',4,'essay','teacher','「큰 집에 갔다」와 「큰집에 갔다」의 뜻을 각각 쓰고, 띄어쓰기를 바르게 해야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-1-u4-C33","difficulty":4,"kind":"essay","stem":"「큰 집에 갔다」와 「큰집에 갔다」의 뜻을 각각 쓰고, 띄어쓰기를 바르게 해야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 「큰 집에 갔다」는 커다란 집에 갔다는 뜻이다. 「큰집에 갔다」는 큰아버지 댁에 갔다는 뜻이다. 띄어쓰기에 따라 뜻이 달라지므로 바르게 띄어 써야 한다.","scoring_points":["「큰 집」의 뜻을 썼는가","「큰집」의 뜻을 썼는가","띄어쓰기와 뜻을 이어 까닭을 썼는가"]},"explanation":["큰 집","큰집","뜻이 달라짐"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_L11_challenge#10','kor',3,1,'u4','L11','g3_1_kor_u4_L11_challenge','lesson_challenge','K3-1-u4-C34',4,'essay','teacher','「바다」를 주제로 생각그물을 만들려고 해요. 기준 두 가지를 정하고 기준마다 어울리는 낱말을 두 개씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-1-u4-C34","difficulty":4,"kind":"essay","stem":"「바다」를 주제로 생각그물을 만들려고 해요. 기준 두 가지를 정하고 기준마다 어울리는 낱말을 두 개씩 쓰세요.","answer_guide":{"answer":"예: 바다에 사는 생물 — 게, 조개. 바다에서 하는 놀이 — 모래성 쌓기, 물놀이.","scoring_points":["기준 두 가지를 정했는가","기준마다 낱말 두 개를 썼는가","낱말이 기준에 맞는가"]},"explanation":["주제","기준","낱말"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_a#1','kor',3,1,'u4','','g3_1_kor_u4_review_a','unit_review','K3-1-u4-C2',1,'mc','auto','중요한 내용을 간단히 적어 둔 글을 무엇이라고 할까요?',ARRAY['K3-1-u4-X01','K3-1-u4-X02','K3-1-u4-X03']::text[],false,'{"seq":1,"concept":"K3-1-u4-C2","difficulty":1,"kind":"mc","stem":"중요한 내용을 간단히 적어 둔 글을 무엇이라고 할까요?","options":[{"t":"메모","correct":true},{"t":"받아쓰기 — 들은 말을 모두 적은 글","mis":"K3-1-u4-X01"},{"t":"동시","mis":"K3-1-u4-X02"},{"t":"일기","mis":"K3-1-u4-X03"}],"explanation":["중요한 내용","간단히","메모"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_a#2','kor',3,1,'u4','','g3_1_kor_u4_review_a','unit_review','K3-1-u4-C6',1,'mc','auto','「도서실 이용 안내」를 듣는 목적으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X05','K3-1-u4-X06']::text[],false,'{"seq":2,"concept":"K3-1-u4-C6","difficulty":1,"kind":"mc","stem":"「도서실 이용 안내」를 듣는 목적으로 알맞은 것은 무엇일까요?","options":[{"t":"도서실을 언제, 어떻게 이용하는지 알기","correct":true},{"t":"안내하는 목소리 흉내 내기","mis":"K3-1-u4-X05"},{"t":"가장 신기한 말 찾기","mis":"K3-1-u4-X06"},{"t":"아무 생각 없이 듣기","mis":"K3-1-u4-X05"}],"explanation":["언제","어떻게","듣는 목적"],"asset":{"type":"speech","turns":[{"who":"사서 선생님","text":"도서실을 새로 열었어요."},{"who":"사서 선생님","text":"쉬는 시간과 점심시간에 이용할 수 있어요."},{"who":"사서 선생님","text":"책은 한 번에 두 권까지 빌려요."},{"who":"사서 선생님","text":"가장 중요한 약속! 빌린 책은 일주일 안에 꼭 돌려주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_a#3','kor',3,1,'u4','','g3_1_kor_u4_review_a','unit_review','K3-1-u4-C11',1,'mc','auto','영상에서 소리는 무슨 일을 할까요?',ARRAY['K3-1-u4-X10','K3-1-u4-X11']::text[],false,'{"seq":3,"concept":"K3-1-u4-C11","difficulty":1,"kind":"mc","stem":"영상에서 소리는 무슨 일을 할까요?","options":[{"t":"설명을 귀로 들려줘요.","correct":true},{"t":"중요한 말을 글자로 보여 줘요.","mis":"K3-1-u4-X10"},{"t":"실제 모습을 그림으로 보여 줘요.","mis":"K3-1-u4-X10"},{"t":"아무 일도 하지 않아요 — 영상은 보기만 해요.","mis":"K3-1-u4-X11"}],"explanation":["소리","설명","귀로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_a#4','kor',3,1,'u4','','g3_1_kor_u4_review_a','unit_review','K3-1-u4-C17',1,'mc','auto','이 글은 어떤 글일까요?',ARRAY['K3-1-u4-X36','K3-1-u4-X15','K3-1-u4-X18']::text[],false,'{"seq":4,"concept":"K3-1-u4-C17","difficulty":1,"kind":"mc","stem":"이 글은 어떤 글일까요?","options":[{"t":"무엇에 대해 알려 주는 설명하는 글","correct":true},{"t":"있었던 일을 지어내 들려주는 글","mis":"K3-1-u4-X36"},{"t":"아무 문장이나 외우면 되는 글","mis":"K3-1-u4-X15"},{"t":"제목이 필요 없는 글","mis":"K3-1-u4-X18"}],"explanation":["다람쥐 · 도토리","알려 주는","설명하는 글"],"asset":{"type":"passage","lines":["다람쥐는 가을에 도토리를 모아 땅에 묻어 둡니다.","겨울잠을 자다 깨면 묻어 둔 도토리를 꺼내 먹습니다.","찾지 못한 도토리는 봄에 싹을 틔워 나무로 자랍니다.","이렇게 다람쥐가 묻은 도토리는 다람쥐도 살리고 숲도 키웁니다."],"title":"다람쥐가 묻은 도토리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_a#5','kor',3,1,'u4','','g3_1_kor_u4_review_a','unit_review','K3-1-u4-C21',1,'mc','auto','모르는 낱말의 뜻을 짐작할 때 가장 도움이 되는 것은 무엇일까요?',ARRAY['K3-1-u4-X19']::text[],false,'{"seq":5,"concept":"K3-1-u4-C21","difficulty":1,"kind":"mc","stem":"모르는 낱말의 뜻을 짐작할 때 가장 도움이 되는 것은 무엇일까요?","options":[{"t":"그 낱말의 앞뒤 문장","correct":true},{"t":"낱말의 소리","mis":"K3-1-u4-X19"},{"t":"낱말의 글자 수","mis":"K3-1-u4-X19"},{"t":"건너뛰기","mis":"K3-1-u4-X19"}],"explanation":["앞 문장","뒤 문장","짐작"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_a#6','kor',3,1,'u4','','g3_1_kor_u4_review_a','unit_review','K3-1-u4-C24',1,'mc','auto','이야기의 일어난 일을 정리할 때 따라야 할 것은 무엇일까요?',ARRAY['K3-1-u4-X27']::text[],false,'{"seq":6,"concept":"K3-1-u4-C24","difficulty":1,"kind":"mc","stem":"이야기의 일어난 일을 정리할 때 따라야 할 것은 무엇일까요?","options":[{"t":"시간 차례","correct":true},{"t":"그림 색깔","mis":"K3-1-u4-X27"},{"t":"글자 크기","mis":"K3-1-u4-X27"},{"t":"끝 문장 하나","mis":"K3-1-u4-X27"}],"explanation":["처음","그다음","시간 차례"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_a#7','kor',3,1,'u4','','g3_1_kor_u4_review_a','unit_review','K3-1-u4-C30',1,'mc','auto','「종이컵 전화기 만들기」를 메모할 때 꼭 지킬 것은 무엇일까요?',ARRAY['K3-1-u4-X29','K3-1-u4-X01']::text[],false,'{"seq":7,"concept":"K3-1-u4-C30","difficulty":1,"kind":"mc","stem":"「종이컵 전화기 만들기」를 메모할 때 꼭 지킬 것은 무엇일까요?","options":[{"t":"만드는 차례대로 숫자를 붙인다.","correct":true},{"t":"생각나는 대로 섞어 적는다.","mis":"K3-1-u4-X29"},{"t":"들린 말을 모두 받아 적는다.","mis":"K3-1-u4-X01"},{"t":"차례 없이 낱말만 늘어놓는다.","mis":"K3-1-u4-X29"}],"explanation":["만드는 차례","숫자","메모"],"asset":{"type":"passage","lines":["(소리) 종이컵 전화기를 만들어 봐요.","(그림) 어른과 함께 종이컵 두 개의 바닥 가운데에 작은 구멍을 뚫어요.","(그림) 구멍에 실을 넣고 컵 안쪽에서 매듭을 지어요.","(그림) 다른 컵에도 실 끝을 똑같이 끼워 묶어요.","(소리) 가장 중요한 것! 실을 팽팽하게 당겨야 소리가 잘 들려요.","(화면 글) 실은 팽팽하게!"],"title":"영상 — 종이컵 전화기 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_a#8','kor',3,1,'u4','','g3_1_kor_u4_review_a','unit_review','K3-1-u4-C33',1,'mc','auto','띄어쓰기를 바르게 해야 하는 까닭은 무엇일까요?',ARRAY['K3-1-u4-X32']::text[],false,'{"seq":8,"concept":"K3-1-u4-C33","difficulty":1,"kind":"mc","stem":"띄어쓰기를 바르게 해야 하는 까닭은 무엇일까요?","options":[{"t":"띄어쓰기에 따라 뜻이 달라질 수 있어서","correct":true},{"t":"띄어쓰기는 뜻과 관계없어서","mis":"K3-1-u4-X32"},{"t":"글자를 크게 보이려고","mis":"K3-1-u4-X32"},{"t":"글을 길어 보이게 하려고","mis":"K3-1-u4-X32"}],"explanation":["띄어쓰기","뜻","달라져요"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_a#9','kor',3,1,'u4','','g3_1_kor_u4_review_a','unit_review','K3-1-u4-C9',2,'mc','auto','「도서실 이용 안내」를 듣고 메모할 내용을 빠짐없이 고른 것은 무엇일까요?',ARRAY['K3-1-u4-X07','K3-1-u4-X01']::text[],false,'{"seq":9,"concept":"K3-1-u4-C9","difficulty":2,"kind":"mc","stem":"「도서실 이용 안내」를 듣고 메모할 내용을 빠짐없이 고른 것은 무엇일까요?","options":[{"t":"이용 시간 · 빌리는 권수 · 돌려주는 때","correct":true},{"t":"빌리는 권수만","mis":"K3-1-u4-X07"},{"t":"「새로 열었어요」만","mis":"K3-1-u4-X07"},{"t":"안내한 말 전부 그대로","mis":"K3-1-u4-X01"}],"explanation":["언제","몇 권","언제까지"],"asset":{"type":"speech","turns":[{"who":"사서 선생님","text":"도서실을 새로 열었어요."},{"who":"사서 선생님","text":"쉬는 시간과 점심시간에 이용할 수 있어요."},{"who":"사서 선생님","text":"책은 한 번에 두 권까지 빌려요."},{"who":"사서 선생님","text":"가장 중요한 약속! 빌린 책은 일주일 안에 꼭 돌려주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_a#10','kor',3,1,'u4','','g3_1_kor_u4_review_a','unit_review','K3-1-u4-C5',2,'mc','auto','하은이의 메모는 어떤 점이 아쉬울까요?',ARRAY['K3-1-u4-X02','K3-1-u4-X01','K3-1-u4-X08']::text[],false,'{"seq":10,"concept":"K3-1-u4-C5","difficulty":2,"kind":"mc","stem":"하은이의 메모는 어떤 점이 아쉬울까요?","options":[{"t":"들은 말을 모두 적어 너무 길어요.","correct":true},{"t":"너무 짧아 뜻을 알 수 없어요.","mis":"K3-1-u4-X02"},{"t":"아쉬운 점이 없어요 — 다 적을수록 좋아요.","mis":"K3-1-u4-X01"},{"t":"제목이 너무 많아요.","mis":"K3-1-u4-X08"}],"explanation":["다 적음","너무 김","한눈에 안 보임"],"asset":{"type":"passage","lines":["다음 주 수요일에 현장 체험학습을 가요. 아침 여덟 시 반까지","학교 정문에 모여요. 도시락과 물, 모자를 챙겨요. 꼭 기억할 것은","선생님 곁을 떠나지 않는 거예요. 다시 말할게요. 선생님 곁을 떠나지 않아요."],"title":"하은이의 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_a#11','kor',3,1,'u4','','g3_1_kor_u4_review_a','unit_review','K3-1-u4-C11',2,'mc','auto','「우유갑 화분 만들기」에서 화면 글로 보여 준 말은 무엇일까요?',ARRAY['K3-1-u4-X10','K3-1-u4-X11']::text[],false,'{"seq":11,"concept":"K3-1-u4-C11","difficulty":2,"kind":"mc","stem":"「우유갑 화분 만들기」에서 화면 글로 보여 준 말은 무엇일까요?","options":[{"t":"구멍은 꼭!","correct":true},{"t":"우유갑을 물로 깨끗이 씻는 모습","mis":"K3-1-u4-X10"},{"t":"물이 빠질 구멍을 꼭 뚫어야 뿌리가 썩지 않아요.","mis":"K3-1-u4-X10"},{"t":"영상에는 화면 글이 없어요","mis":"K3-1-u4-X11"}],"explanation":["(화면 글)","글자로","구멍은 꼭!"],"asset":{"type":"passage","lines":["(소리) 다 마신 우유갑으로 화분을 만들어 봐요.","(그림) 우유갑을 물로 깨끗이 씻어요.","(그림) 어른과 함께 우유갑 옆면을 잘라 내요.","(그림) 바닥에 작은 구멍을 서너 개 뚫어요.","(소리) 물이 빠질 구멍을 꼭 뚫어야 뿌리가 썩지 않아요.","(화면 글) 구멍은 꼭!"],"title":"영상 — 우유갑 화분 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_a#12','kor',3,1,'u4','','g3_1_kor_u4_review_a','unit_review','K3-1-u4-C16',2,'mc','auto','「우유갑 화분 만들기」를 보고 나와 관련지은 말로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X14','K3-1-u4-X13','K3-1-u4-X12']::text[],false,'{"seq":12,"concept":"K3-1-u4-C16","difficulty":2,"kind":"mc","stem":"「우유갑 화분 만들기」를 보고 나와 관련지은 말로 알맞은 것은 무엇일까요?","options":[{"t":"「집에 있는 우유갑으로 화분을 만들어 상추를 길러 봐야지.」","correct":true},{"t":"「나와는 상관없는 영상이야.」","mis":"K3-1-u4-X14"},{"t":"「영상이 빨리 끝났으면 좋겠어.」","mis":"K3-1-u4-X13"},{"t":"「그림이 귀여워.」","mis":"K3-1-u4-X12"}],"explanation":["나도","집에서","실천"],"asset":{"type":"passage","lines":["(소리) 다 마신 우유갑으로 화분을 만들어 봐요.","(그림) 우유갑을 물로 깨끗이 씻어요.","(그림) 어른과 함께 우유갑 옆면을 잘라 내요.","(그림) 바닥에 작은 구멍을 서너 개 뚫어요.","(소리) 물이 빠질 구멍을 꼭 뚫어야 뿌리가 썩지 않아요.","(화면 글) 구멍은 꼭!"],"title":"영상 — 우유갑 화분 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_a#13','kor',3,1,'u4','','g3_1_kor_u4_review_a','unit_review','K3-1-u4-C19',2,'mc','auto','「다람쥐가 묻은 도토리」의 중심 문장은 무엇일까요?',ARRAY['K3-1-u4-X16','K3-1-u4-X17']::text[],false,'{"seq":13,"concept":"K3-1-u4-C19","difficulty":2,"kind":"mc","stem":"「다람쥐가 묻은 도토리」의 중심 문장은 무엇일까요?","options":[{"t":"이렇게 다람쥐가 묻은 도토리는 다람쥐도 살리고 숲도 키웁니다.","correct":true},{"t":"다람쥐는 가을에 도토리를 모아 땅에 묻어 둡니다.","mis":"K3-1-u4-X16"},{"t":"찾지 못한 도토리는 봄에 싹을 틔워 나무로 자랍니다.","mis":"K3-1-u4-X17"},{"t":"겨울잠을 자다 깨면 묻어 둔 도토리를 꺼내 먹습니다.","mis":"K3-1-u4-X17"}],"explanation":["묻기 · 먹기 · 자라기","모두 묶는","끝 문장"],"asset":{"type":"passage","lines":["다람쥐는 가을에 도토리를 모아 땅에 묻어 둡니다.","겨울잠을 자다 깨면 묻어 둔 도토리를 꺼내 먹습니다.","찾지 못한 도토리는 봄에 싹을 틔워 나무로 자랍니다.","이렇게 다람쥐가 묻은 도토리는 다람쥐도 살리고 숲도 키웁니다."],"title":"다람쥐가 묻은 도토리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_a#14','kor',3,1,'u4','','g3_1_kor_u4_review_a','unit_review','K3-1-u4-C23',2,'mc','auto','「두부가 만들어지는 과정」에서 가장 마지막에 하는 일은 무엇일까요?',ARRAY['K3-1-u4-X22']::text[],false,'{"seq":14,"concept":"K3-1-u4-C23","difficulty":2,"kind":"mc","stem":"「두부가 만들어지는 과정」에서 가장 마지막에 하는 일은 무엇일까요?","options":[{"t":"엉긴 것을 틀에 눌러 담는다.","correct":true},{"t":"콩을 물에 불린다.","mis":"K3-1-u4-X22"},{"t":"콩을 갈아 끓인다.","mis":"K3-1-u4-X22"},{"t":"천에 거른다.","mis":"K3-1-u4-X22"}],"explanation":["마지막으로","틀에 눌러","두부"],"asset":{"type":"passage","lines":["① 먼저 콩을 물에 하룻밤 불립니다.","콩이 물을 먹어 통통하게 부풀어 오릅니다.","② 그다음 불린 콩을 갈아 끓인 뒤 천에 거릅니다.","찌꺼기는 천에 남고 콩물만 빠져나옵니다.","③ 마지막으로 콩물에 굳히는 물을 넣어 엉기게 합니다.","몽글몽글 엉긴 것을 틀에 눌러 담으면 두부가 됩니다."],"title":"두부가 만들어지는 과정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_a#15','kor',3,1,'u4','','g3_1_kor_u4_review_a','unit_review','K3-1-u4-C24',2,'mc','auto','「비 오는 하굣길」에서 가장 나중에 일어난 일은 무엇일까요?',ARRAY['K3-1-u4-X23']::text[],false,'{"seq":15,"concept":"K3-1-u4-C24","difficulty":2,"kind":"mc","stem":"「비 오는 하굣길」에서 가장 나중에 일어난 일은 무엇일까요?","options":[{"t":"하은이가 예린이에게 줄 사탕을 챙겨 학교에 갔다.","correct":true},{"t":"예린이가 우산을 펼쳤다.","mis":"K3-1-u4-X23"},{"t":"하은이의 우산이 보이지 않았다.","mis":"K3-1-u4-X23"},{"t":"둘이 어깨를 맞대고 걸었다.","mis":"K3-1-u4-X23"}],"explanation":["다음 날","사탕","끝"],"asset":{"type":"passage","lines":["아침부터 비가 내렸습니다.","수업이 끝나고 보니 하은이의 우산이 우산꽂이에 없었습니다.","하은이는 학교 현관 앞에서 발을 동동 굴렀습니다.","그때 예린이가 다가와 「같이 쓰고 가자.」 하고 우산을 펼쳤습니다.","둘은 어깨를 맞대고 빗속을 걸었습니다.","하은이네 집 앞에서 하은이는 「정말 고마워.」 하고 손을 흔들었습니다.","다음 날, 하은이는 예린이에게 줄 사탕을 주머니에 넣고 학교에 갔습니다."],"title":"비 오는 하굣길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_a#16','kor',3,1,'u4','','g3_1_kor_u4_review_a','unit_review','K3-1-u4-C33',2,'mc','auto','「큰집에 갔다」와 「큰 집에 갔다」에 대해 바르게 말한 것은 무엇일까요?',ARRAY['K3-1-u4-X32']::text[],false,'{"seq":16,"concept":"K3-1-u4-C33","difficulty":2,"kind":"mc","stem":"「큰집에 갔다」와 「큰 집에 갔다」에 대해 바르게 말한 것은 무엇일까요?","options":[{"t":"띄어쓰기에 따라 「큰아버지 댁」과 「커다란 집」으로 뜻이 달라요.","correct":true},{"t":"둘은 뜻이 같아요.","mis":"K3-1-u4-X32"},{"t":"「큰 집」만 바른 말이에요.","mis":"K3-1-u4-X32"},{"t":"「큰집」만 바른 말이에요.","mis":"K3-1-u4-X32"}],"explanation":["큰집","큰 집","뜻이 달라요"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_a#17','kor',3,1,'u4','','g3_1_kor_u4_review_a','unit_review','K3-1-u4-C8',3,'mc','auto','말하는 사람이 내용을 강조할 때 쓰는 방법이 아닌 것은 무엇일까요?',ARRAY['K3-1-u4-X06']::text[],false,'{"seq":17,"concept":"K3-1-u4-C8","difficulty":3,"kind":"mc","stem":"말하는 사람이 내용을 강조할 때 쓰는 방법이 아닌 것은 무엇일까요?","options":[{"t":"아무 말이나 가장 작게 속삭인다.","correct":true},{"t":"「가장 중요한 것은」이라고 말한다.","mis":"K3-1-u4-X06"},{"t":"같은 말을 한 번 더 되풀이한다.","mis":"K3-1-u4-X06"},{"t":"「꼭」이라는 말을 넣는다.","mis":"K3-1-u4-X06"}],"explanation":["가장 중요한","되풀이","꼭"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_a#18','kor',3,1,'u4','','g3_1_kor_u4_review_a','unit_review','K3-1-u4-C11',3,'mc','auto','「우유갑 화분 만들기」를 소리로만 들으면 알기 어려운 것은 무엇일까요?',ARRAY['K3-1-u4-X10','K3-1-u4-X11']::text[],false,'{"seq":18,"concept":"K3-1-u4-C11","difficulty":3,"kind":"mc","stem":"「우유갑 화분 만들기」를 소리로만 들으면 알기 어려운 것은 무엇일까요?","options":[{"t":"옆면을 어떻게 잘라 내는지 같은 실제 모습","correct":true},{"t":"구멍을 뚫는 까닭","mis":"K3-1-u4-X10"},{"t":"어려운 것은 없다 — 소리면 충분하다","mis":"K3-1-u4-X10"},{"t":"화면 글은 원래 볼 필요가 없다","mis":"K3-1-u4-X11"}],"explanation":["소리만","모습은 그림으로","함께 보기"],"asset":{"type":"passage","lines":["(소리) 다 마신 우유갑으로 화분을 만들어 봐요.","(그림) 우유갑을 물로 깨끗이 씻어요.","(그림) 어른과 함께 우유갑 옆면을 잘라 내요.","(그림) 바닥에 작은 구멍을 서너 개 뚫어요.","(소리) 물이 빠질 구멍을 꼭 뚫어야 뿌리가 썩지 않아요.","(화면 글) 구멍은 꼭!"],"title":"영상 — 우유갑 화분 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_a#19','kor',3,1,'u4','','g3_1_kor_u4_review_a','unit_review','K3-1-u4-C19',3,'mc','auto','「다람쥐가 묻은 도토리」처럼 중심 문장이 끝에 오면 좋은 점은 무엇일까요?',ARRAY['K3-1-u4-X16','K3-1-u4-X17']::text[],false,'{"seq":19,"concept":"K3-1-u4-C19","difficulty":3,"kind":"mc","stem":"「다람쥐가 묻은 도토리」처럼 중심 문장이 끝에 오면 좋은 점은 무엇일까요?","options":[{"t":"예를 모두 읽은 뒤 생각을 한데 모아 정리해 줘요.","correct":true},{"t":"중심 문장은 끝에 오면 안 돼요.","mis":"K3-1-u4-X16"},{"t":"끝 문장이 가장 길어서 좋아요.","mis":"K3-1-u4-X16"},{"t":"뒷받침 문장이 필요 없어져요.","mis":"K3-1-u4-X17"}],"explanation":["예 먼저","끝에서","모아 정리"],"asset":{"type":"passage","lines":["다람쥐는 가을에 도토리를 모아 땅에 묻어 둡니다.","겨울잠을 자다 깨면 묻어 둔 도토리를 꺼내 먹습니다.","찾지 못한 도토리는 봄에 싹을 틔워 나무로 자랍니다.","이렇게 다람쥐가 묻은 도토리는 다람쥐도 살리고 숲도 키웁니다."],"title":"다람쥐가 묻은 도토리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_a#20','kor',3,1,'u4','','g3_1_kor_u4_review_a','unit_review','K3-1-u4-C26',3,'mc','auto','「하은이는 예린이에게 줄 사탕을 주머니에 넣고」에서 짐작할 수 있는 하은이의 마음은 무엇일까요?',ARRAY['K3-1-u4-X26','K3-1-u4-X25']::text[],false,'{"seq":20,"concept":"K3-1-u4-C26","difficulty":3,"kind":"mc","stem":"「하은이는 예린이에게 줄 사탕을 주머니에 넣고」에서 짐작할 수 있는 하은이의 마음은 무엇일까요?","options":[{"t":"고마운 마음을 갚고 싶은 마음","correct":true},{"t":"예린이에게 화가 난 마음","mis":"K3-1-u4-X26"},{"t":"우산을 잃어 아직도 걱정하는 마음","mis":"K3-1-u4-X25"},{"t":"사탕이 먹고 싶은 마음만","mis":"K3-1-u4-X26"}],"explanation":["다음 날","사탕","고마움"],"asset":{"type":"passage","lines":["아침부터 비가 내렸습니다.","수업이 끝나고 보니 하은이의 우산이 우산꽂이에 없었습니다.","하은이는 학교 현관 앞에서 발을 동동 굴렀습니다.","그때 예린이가 다가와 「같이 쓰고 가자.」 하고 우산을 펼쳤습니다.","둘은 어깨를 맞대고 빗속을 걸었습니다.","하은이네 집 앞에서 하은이는 「정말 고마워.」 하고 손을 흔들었습니다.","다음 날, 하은이는 예린이에게 줄 사탕을 주머니에 넣고 학교에 갔습니다."],"title":"비 오는 하굣길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_a#21','kor',3,1,'u4','','g3_1_kor_u4_review_a','unit_review','K3-1-u4-C31',3,'mc','auto','소율이의 발표에서 잘한 점은 무엇일까요?',ARRAY['K3-1-u4-X30','K3-1-u4-X01']::text[],false,'{"seq":21,"concept":"K3-1-u4-C31","difficulty":3,"kind":"mc","stem":"소율이의 발표에서 잘한 점은 무엇일까요?","options":[{"t":"첫째 · 둘째 · 셋째로 차례를 나누고 가장 중요한 것을 강조했다.","correct":true},{"t":"메모를 아주 빠르게 읽었다.","mis":"K3-1-u4-X30"},{"t":"들은 말을 하나도 빼지 않았다.","mis":"K3-1-u4-X01"},{"t":"친구 발표의 흠을 찾았다.","mis":"K3-1-u4-X30"}],"explanation":["차례","강조","잘한 점"],"asset":{"type":"speech","turns":[{"who":"소율","text":"종이컵 전화기 만드는 방법을 발표할게요."},{"who":"소율","text":"첫째, 종이컵 바닥에 작은 구멍을 뚫어요. 둘째, 실을 넣고 매듭을 지어요."},{"who":"소율","text":"셋째, 가장 중요한 것! 실을 팽팽하게 당겨요. 그래야 소리가 잘 들려요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_a#22','kor',3,1,'u4','','g3_1_kor_u4_review_a','unit_review','K3-1-u4-C33',3,'mc','auto','「아기가방에서잔다」를 아기가 방에서 잔다는 뜻으로 바르게 띄어 쓴 것은 무엇일까요?',ARRAY['K3-1-u4-X32','K3-1-u4-X33']::text[],false,'{"seq":22,"concept":"K3-1-u4-C33","difficulty":3,"kind":"mc","stem":"「아기가방에서잔다」를 아기가 방에서 잔다는 뜻으로 바르게 띄어 쓴 것은 무엇일까요?","options":[{"t":"아기가 방에서 잔다","correct":true},{"t":"아기 가방에서 잔다","mis":"K3-1-u4-X32"},{"t":"아기가 방 에서 잔다","mis":"K3-1-u4-X33"},{"t":"아기 가 방에서 잔다","mis":"K3-1-u4-X33"}],"explanation":["아기가","방에서","잔다"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_a#23','kor',3,1,'u4','','g3_1_kor_u4_review_a','unit_review','K3-1-u4-C5',4,'essay','teacher','「도서실 이용 안내」를 듣고 제목 · 숫자 · 기호를 써서 메모하세요.','{}'::text[],false,'{"seq":23,"concept":"K3-1-u4-C5","difficulty":4,"kind":"essay","stem":"「도서실 이용 안내」를 듣고 제목 · 숫자 · 기호를 써서 메모하세요.","answer_guide":{"answer":"예: 제목 — 도서실 이용 안내. 1. 쉬는 시간 · 점심시간에 이용 2. 한 번에 두 권까지 ★ 빌린 책은 일주일 안에 돌려주기","scoring_points":["알맞은 제목을 썼는가","숫자로 나누었는가","가장 중요한 약속에 기호를 썼는가"]},"explanation":["제목","숫자","기호"],"asset":{"type":"speech","turns":[{"who":"사서 선생님","text":"도서실을 새로 열었어요."},{"who":"사서 선생님","text":"쉬는 시간과 점심시간에 이용할 수 있어요."},{"who":"사서 선생님","text":"책은 한 번에 두 권까지 빌려요."},{"who":"사서 선생님","text":"가장 중요한 약속! 빌린 책은 일주일 안에 꼭 돌려주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_a#24','kor',3,1,'u4','','g3_1_kor_u4_review_a','unit_review','K3-1-u4-C19',4,'essay','teacher','「다람쥐가 묻은 도토리」의 중심 문장을 찾아 쓰고, 뒷받침 문장들이 중심 문장을 어떻게 돕는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-1-u4-C19","difficulty":4,"kind":"essay","stem":"「다람쥐가 묻은 도토리」의 중심 문장을 찾아 쓰고, 뒷받침 문장들이 중심 문장을 어떻게 돕는지 쓰세요.","answer_guide":{"answer":"예: 중심 문장은 「이렇게 다람쥐가 묻은 도토리는 다람쥐도 살리고 숲도 키웁니다.」이다. 앞의 세 문장이 도토리를 묻고, 꺼내 먹고, 남은 것이 나무로 자라는 일을 차례로 말해 중심 문장을 자세히 설명한다.","scoring_points":["중심 문장을 바르게 찾았는가","뒷받침 문장의 내용을 썼는가","어떻게 돕는지 썼는가"]},"explanation":["중심","뒷받침","돕기"],"asset":{"type":"passage","lines":["다람쥐는 가을에 도토리를 모아 땅에 묻어 둡니다.","겨울잠을 자다 깨면 묻어 둔 도토리를 꺼내 먹습니다.","찾지 못한 도토리는 봄에 싹을 틔워 나무로 자랍니다.","이렇게 다람쥐가 묻은 도토리는 다람쥐도 살리고 숲도 키웁니다."],"title":"다람쥐가 묻은 도토리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_a#25','kor',3,1,'u4','','g3_1_kor_u4_review_a','unit_review','K3-1-u4-C31',4,'essay','teacher','「손을 바르게 씻는 방법」을 방법과 좋은 점으로 나누어 메모하고, 발표할 때 지킬 점을 한 가지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-1-u4-C31","difficulty":4,"kind":"essay","stem":"「손을 바르게 씻는 방법」을 방법과 좋은 점으로 나누어 메모하고, 발표할 때 지킬 점을 한 가지 쓰세요.","answer_guide":{"answer":"예: 1. 비누 거품으로 문지르기 → 때가 잘 빠짐 2. 손가락 사이 · 손톱 밑 씻기 → 숨은 때까지 3. 수건으로 닦기 → 손이 트지 않음. 발표할 때는 듣는 친구를 보며 또박또박 말하겠다.","scoring_points":["방법을 차례대로 썼는가","방법마다 좋은 점을 짝지어 썼는가","발표할 때 지킬 점을 썼는가"]},"explanation":["방법","좋은 점","발표"],"asset":{"type":"passage","lines":["손을 바르게 씻는 방법을 알려 줄게요.","첫째, 비누 거품을 내어 손바닥과 손등을 문질러요. 그러면 묻은 때가 잘 빠져요.","둘째, 손가락 사이와 손톱 밑도 꼼꼼히 씻어요. 그러면 숨은 때까지 없앨 수 있어요.","셋째, 깨끗한 수건으로 물기를 닦아요. 그러면 손이 트지 않아요."],"title":"들은 설명 — 손을 바르게 씻는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_b#1','kor',3,1,'u4','','g3_1_kor_u4_review_b','unit_review','K3-1-u4-C5',1,'mc','auto','메모를 짧게 쓰는 까닭은 무엇일까요?',ARRAY['K3-1-u4-X01','K3-1-u4-X02','K3-1-u4-X03']::text[],false,'{"seq":1,"concept":"K3-1-u4-C5","difficulty":1,"kind":"mc","stem":"메모를 짧게 쓰는 까닭은 무엇일까요?","options":[{"t":"꼭 필요한 내용을 빨리 적고 한눈에 보려고","correct":true},{"t":"짧게 쓰면 안 돼요 — 다 적을수록 좋아요","mis":"K3-1-u4-X01"},{"t":"낱말 하나면 무엇이든 다 기억나니까","mis":"K3-1-u4-X02"},{"t":"메모는 나중에 볼 일이 없으니까","mis":"K3-1-u4-X03"}],"explanation":["빨리 적기","한눈에","짧게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_b#2','kor',3,1,'u4','','g3_1_kor_u4_review_b','unit_review','K3-1-u4-C8',1,'mc','auto','이 안내에서 강조하는 내용을 알 수 있는 말은 무엇일까요?',ARRAY['K3-1-u4-X06','K3-1-u4-X07']::text[],false,'{"seq":2,"concept":"K3-1-u4-C8","difficulty":1,"kind":"mc","stem":"이 안내에서 강조하는 내용을 알 수 있는 말은 무엇일까요?","options":[{"t":"「가장 중요한 약속!」","correct":true},{"t":"「도서실을 새로 열었어요.」 — 처음 말이라서","mis":"K3-1-u4-X06"},{"t":"「쉬는 시간」 — 신기한 말이라서","mis":"K3-1-u4-X06"},{"t":"없어요 — 강조는 알 수 없어요","mis":"K3-1-u4-X07"}],"explanation":["가장 중요한","약속","강조"],"asset":{"type":"speech","turns":[{"who":"사서 선생님","text":"도서실을 새로 열었어요."},{"who":"사서 선생님","text":"쉬는 시간과 점심시간에 이용할 수 있어요."},{"who":"사서 선생님","text":"책은 한 번에 두 권까지 빌려요."},{"who":"사서 선생님","text":"가장 중요한 약속! 빌린 책은 일주일 안에 꼭 돌려주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_b#3','kor',3,1,'u4','','g3_1_kor_u4_review_b','unit_review','K3-1-u4-C12',1,'mc','auto','영상을 볼 때 화면에 나온 글은 어떻게 할까요?',ARRAY['K3-1-u4-X11','K3-1-u4-X10','K3-1-u4-X13']::text[],false,'{"seq":3,"concept":"K3-1-u4-C12","difficulty":1,"kind":"mc","stem":"영상을 볼 때 화면에 나온 글은 어떻게 할까요?","options":[{"t":"중요한 말이 담겨 있으니 꼭 읽어요.","correct":true},{"t":"꾸밈이니 읽지 않아요.","mis":"K3-1-u4-X11"},{"t":"소리만 들으면 되니 눈을 감아요.","mis":"K3-1-u4-X10"},{"t":"빨리 넘겨요.","mis":"K3-1-u4-X13"}],"explanation":["화면 글","중요한 말","읽기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_b#4','kor',3,1,'u4','','g3_1_kor_u4_review_b','unit_review','K3-1-u4-C19',1,'mc','auto','중심 문장을 찾는 방법으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X16','K3-1-u4-X17']::text[],false,'{"seq":4,"concept":"K3-1-u4-C19","difficulty":1,"kind":"mc","stem":"중심 문장을 찾는 방법으로 알맞은 것은 무엇일까요?","options":[{"t":"다른 문장의 내용을 모두 묶어 주는 문장을 찾는다.","correct":true},{"t":"가장 긴 문장을 찾는다.","mis":"K3-1-u4-X16"},{"t":"예를 든 문장을 찾는다.","mis":"K3-1-u4-X17"},{"t":"늘 첫 문장을 고른다.","mis":"K3-1-u4-X16"}],"explanation":["길이가 아니라","모두 묶는","중심 문장"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_b#5','kor',3,1,'u4','','g3_1_kor_u4_review_b','unit_review','K3-1-u4-C22',1,'mc','auto','설명하는 글을 간추린다는 것은 무엇일까요?',ARRAY['K3-1-u4-X20','K3-1-u4-X21','K3-1-u4-X18']::text[],false,'{"seq":5,"concept":"K3-1-u4-C22","difficulty":1,"kind":"mc","stem":"설명하는 글을 간추린다는 것은 무엇일까요?","options":[{"t":"중요한 내용만 골라 짧게 정리하는 것","correct":true},{"t":"모든 문장을 그대로 옮겨 쓰는 것","mis":"K3-1-u4-X20"},{"t":"재미있는 예만 모으는 것","mis":"K3-1-u4-X21"},{"t":"제목만 남기는 것","mis":"K3-1-u4-X18"}],"explanation":["중요한 내용","골라서","짧게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_b#6','kor',3,1,'u4','','g3_1_kor_u4_review_b','unit_review','K3-1-u4-C25',1,'mc','auto','「하은이는 학교 현관 앞에서 발을 동동 굴렀습니다.」에서 장소는 어디일까요?',ARRAY['K3-1-u4-X24']::text[],false,'{"seq":6,"concept":"K3-1-u4-C25","difficulty":1,"kind":"mc","stem":"「하은이는 학교 현관 앞에서 발을 동동 굴렀습니다.」에서 장소는 어디일까요?","options":[{"t":"학교 현관 앞","correct":true},{"t":"하은이네 집 앞","mis":"K3-1-u4-X24"},{"t":"교실 안","mis":"K3-1-u4-X24"},{"t":"장소는 나오지 않아요","mis":"K3-1-u4-X24"}],"explanation":["어디에서","현관 앞","장소"],"asset":{"type":"passage","lines":["아침부터 비가 내렸습니다.","수업이 끝나고 보니 하은이의 우산이 우산꽂이에 없었습니다.","하은이는 학교 현관 앞에서 발을 동동 굴렀습니다.","그때 예린이가 다가와 「같이 쓰고 가자.」 하고 우산을 펼쳤습니다.","둘은 어깨를 맞대고 빗속을 걸었습니다.","하은이네 집 앞에서 하은이는 「정말 고마워.」 하고 손을 흔들었습니다.","다음 날, 하은이는 예린이에게 줄 사탕을 주머니에 넣고 학교에 갔습니다."],"title":"비 오는 하굣길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_b#7','kor',3,1,'u4','','g3_1_kor_u4_review_b','unit_review','K3-1-u4-C31',1,'mc','auto','친구의 발표를 듣고 할 일로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X30']::text[],false,'{"seq":7,"concept":"K3-1-u4-C31","difficulty":1,"kind":"mc","stem":"친구의 발표를 듣고 할 일로 알맞은 것은 무엇일까요?","options":[{"t":"잘한 점을 칭찬해 준다.","correct":true},{"t":"흠만 찾아 말한다.","mis":"K3-1-u4-X30"},{"t":"듣지 않고 내 발표만 준비한다.","mis":"K3-1-u4-X30"},{"t":"발표가 빨리 끝나기만 기다린다.","mis":"K3-1-u4-X30"}],"explanation":["끝까지 듣기","잘한 점","칭찬"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_b#8','kor',3,1,'u4','','g3_1_kor_u4_review_b','unit_review','K3-1-u4-C33',1,'mc','auto','「가」 · 「를」 · 「에」처럼 낱말 뒤에 붙는 말은 어떻게 쓸까요?',ARRAY['K3-1-u4-X33','K3-1-u4-X32']::text[],false,'{"seq":8,"concept":"K3-1-u4-C33","difficulty":1,"kind":"mc","stem":"「가」 · 「를」 · 「에」처럼 낱말 뒤에 붙는 말은 어떻게 쓸까요?","options":[{"t":"앞말에 붙여 써요.","correct":true},{"t":"앞말과 띄어 써요.","mis":"K3-1-u4-X33"},{"t":"아무렇게나 써도 돼요.","mis":"K3-1-u4-X32"},{"t":"쓰지 않아요.","mis":"K3-1-u4-X33"}],"explanation":["붙는 말","앞말에","붙여 쓰기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_b#9','kor',3,1,'u4','','g3_1_kor_u4_review_b','unit_review','K3-1-u4-C8',2,'mc','auto','「도서실 이용 안내」에서 가장 강조한 내용은 무엇일까요?',ARRAY['K3-1-u4-X06','K3-1-u4-X07']::text[],false,'{"seq":9,"concept":"K3-1-u4-C8","difficulty":2,"kind":"mc","stem":"「도서실 이용 안내」에서 가장 강조한 내용은 무엇일까요?","options":[{"t":"빌린 책은 일주일 안에 꼭 돌려주기","correct":true},{"t":"도서실을 새로 열었다는 것 — 처음 들었으니까","mis":"K3-1-u4-X06"},{"t":"쉬는 시간에 이용한다는 것 — 신기하니까","mis":"K3-1-u4-X06"},{"t":"강조한 내용은 없다","mis":"K3-1-u4-X07"}],"explanation":["가장 중요한 약속","꼭","강조"],"asset":{"type":"speech","turns":[{"who":"사서 선생님","text":"도서실을 새로 열었어요."},{"who":"사서 선생님","text":"쉬는 시간과 점심시간에 이용할 수 있어요."},{"who":"사서 선생님","text":"책은 한 번에 두 권까지 빌려요."},{"who":"사서 선생님","text":"가장 중요한 약속! 빌린 책은 일주일 안에 꼭 돌려주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_b#10','kor',3,1,'u4','','g3_1_kor_u4_review_b','unit_review','K3-1-u4-C2',2,'mc','auto','시우의 메모에 대해 바르게 말한 것은 무엇일까요?',ARRAY['K3-1-u4-X02','K3-1-u4-X03','K3-1-u4-X01']::text[],false,'{"seq":10,"concept":"K3-1-u4-C2","difficulty":2,"kind":"mc","stem":"시우의 메모에 대해 바르게 말한 것은 무엇일까요?","options":[{"t":"낱말만 적어서 몇 시에 모이는지 같은 뜻을 알기 어려워요.","correct":true},{"t":"모이는 시각까지 모두 알 수 있어요.","mis":"K3-1-u4-X02"},{"t":"메모가 필요 없다는 것을 보여 줘요.","mis":"K3-1-u4-X03"},{"t":"들은 말을 빠짐없이 적었어요.","mis":"K3-1-u4-X01"}],"explanation":["낱말만","뜻을 몰라요","알아볼 수 있게"],"asset":{"type":"passage","lines":["수요일","정문","모자"],"title":"시우의 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_b#11','kor',3,1,'u4','','g3_1_kor_u4_review_b','unit_review','K3-1-u4-C14',2,'mc','auto','「우유갑 화분 만들기」에서 가장 강조한 것은 무엇일까요?',ARRAY['K3-1-u4-X06','K3-1-u4-X13']::text[],false,'{"seq":11,"concept":"K3-1-u4-C14","difficulty":2,"kind":"mc","stem":"「우유갑 화분 만들기」에서 가장 강조한 것은 무엇일까요?","options":[{"t":"바닥에 물 빠질 구멍을 꼭 뚫는 것","correct":true},{"t":"우유갑의 색깔","mis":"K3-1-u4-X06"},{"t":"옆면을 자르는 모습 — 신기해서","mis":"K3-1-u4-X06"},{"t":"강조한 것은 없다","mis":"K3-1-u4-X13"}],"explanation":["소리로 「꼭」","화면 글로 또","강조"],"asset":{"type":"passage","lines":["(소리) 다 마신 우유갑으로 화분을 만들어 봐요.","(그림) 우유갑을 물로 깨끗이 씻어요.","(그림) 어른과 함께 우유갑 옆면을 잘라 내요.","(그림) 바닥에 작은 구멍을 서너 개 뚫어요.","(소리) 물이 빠질 구멍을 꼭 뚫어야 뿌리가 썩지 않아요.","(화면 글) 구멍은 꼭!"],"title":"영상 — 우유갑 화분 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_b#12','kor',3,1,'u4','','g3_1_kor_u4_review_b','unit_review','K3-1-u4-C12',2,'mc','auto','「횡단보도를 건너는 방법」에서 「차가 멈췄는지 꼭 확인!」이 화면 글로 나온 까닭은 무엇일까요?',ARRAY['K3-1-u4-X11','K3-1-u4-X10','K3-1-u4-X12']::text[],false,'{"seq":12,"concept":"K3-1-u4-C12","difficulty":2,"kind":"mc","stem":"「횡단보도를 건너는 방법」에서 「차가 멈췄는지 꼭 확인!」이 화면 글로 나온 까닭은 무엇일까요?","options":[{"t":"꼭 지켜야 할 중요한 말이라서","correct":true},{"t":"화면을 꾸미려고","mis":"K3-1-u4-X11"},{"t":"소리가 나오지 않아서","mis":"K3-1-u4-X10"},{"t":"그림과 관계없는 말이라서","mis":"K3-1-u4-X12"}],"explanation":["화면 글","중요한 말","꼭"],"asset":{"type":"passage","lines":["(소리) 횡단보도를 건널 때는 세 가지를 기억해요.","(화면 글) 멈춰요 → 살펴요 → 건너요","(그림) 초록불 앞에 멈춘 아이가 왼쪽과 오른쪽을 봐요.","(소리) 초록불이 켜져도 차가 멈췄는지 꼭 살펴요.","(화면 글) 차가 멈췄는지 꼭 확인!","(그림) 아이가 손을 들고 천천히 건너요."],"title":"영상 — 횡단보도를 건너는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_b#13','kor',3,1,'u4','','g3_1_kor_u4_review_b','unit_review','K3-1-u4-C18',2,'mc','auto','「찾지 못한 도토리는 봄에 싹을 틔워 나무로 자랍니다.」는 어떤 문장일까요?',ARRAY['K3-1-u4-X17','K3-1-u4-X15','K3-1-u4-X18']::text[],false,'{"seq":13,"concept":"K3-1-u4-C18","difficulty":2,"kind":"mc","stem":"「찾지 못한 도토리는 봄에 싹을 틔워 나무로 자랍니다.」는 어떤 문장일까요?","options":[{"t":"숲을 키운다는 것을 덧붙여 설명하는 뒷받침 문장","correct":true},{"t":"문단을 대표하는 중심 문장","mis":"K3-1-u4-X17"},{"t":"글과 관계없는 문장","mis":"K3-1-u4-X15"},{"t":"글의 제목","mis":"K3-1-u4-X18"}],"explanation":["숲을 키움","덧붙임","뒷받침"],"asset":{"type":"passage","lines":["다람쥐는 가을에 도토리를 모아 땅에 묻어 둡니다.","겨울잠을 자다 깨면 묻어 둔 도토리를 꺼내 먹습니다.","찾지 못한 도토리는 봄에 싹을 틔워 나무로 자랍니다.","이렇게 다람쥐가 묻은 도토리는 다람쥐도 살리고 숲도 키웁니다."],"title":"다람쥐가 묻은 도토리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_b#14','kor',3,1,'u4','','g3_1_kor_u4_review_b','unit_review','K3-1-u4-C20',2,'mc','auto','이 글을 읽기 전에 제목을 보고 짐작할 수 있는 것은 무엇일까요?',ARRAY['K3-1-u4-X18','K3-1-u4-X36']::text[],false,'{"seq":14,"concept":"K3-1-u4-C20","difficulty":2,"kind":"mc","stem":"이 글을 읽기 전에 제목을 보고 짐작할 수 있는 것은 무엇일까요?","options":[{"t":"두부를 만드는 차례를 알려 주는 글이라는 것","correct":true},{"t":"제목으로는 알 수 있는 것이 없다는 것","mis":"K3-1-u4-X18"},{"t":"두부를 좋아하는 아이의 이야기라는 것","mis":"K3-1-u4-X36"},{"t":"두부 가게가 어디에 있는지","mis":"K3-1-u4-X18"}],"explanation":["제목","무엇에 대한 글","짐작"],"asset":{"type":"passage","lines":["① 먼저 콩을 물에 하룻밤 불립니다.","콩이 물을 먹어 통통하게 부풀어 오릅니다.","② 그다음 불린 콩을 갈아 끓인 뒤 천에 거릅니다.","찌꺼기는 천에 남고 콩물만 빠져나옵니다.","③ 마지막으로 콩물에 굳히는 물을 넣어 엉기게 합니다.","몽글몽글 엉긴 것을 틀에 눌러 담으면 두부가 됩니다."],"title":"두부가 만들어지는 과정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_b#15','kor',3,1,'u4','','g3_1_kor_u4_review_b','unit_review','K3-1-u4-C27',2,'mc','auto','하은이의 마음이 걱정에서 고마움으로 바뀐 까닭은 무엇일까요?',ARRAY['K3-1-u4-X26','K3-1-u4-X25']::text[],false,'{"seq":15,"concept":"K3-1-u4-C27","difficulty":2,"kind":"mc","stem":"하은이의 마음이 걱정에서 고마움으로 바뀐 까닭은 무엇일까요?","options":[{"t":"예린이가 우산을 같이 쓰자고 해서","correct":true},{"t":"비가 내려서","mis":"K3-1-u4-X26"},{"t":"우산이 없어져서","mis":"K3-1-u4-X26"},{"t":"마음은 바뀌지 않았다","mis":"K3-1-u4-X25"}],"explanation":["같이 쓰고 가자","고마움","바뀐 마음"],"asset":{"type":"passage","lines":["아침부터 비가 내렸습니다.","수업이 끝나고 보니 하은이의 우산이 우산꽂이에 없었습니다.","하은이는 학교 현관 앞에서 발을 동동 굴렀습니다.","그때 예린이가 다가와 「같이 쓰고 가자.」 하고 우산을 펼쳤습니다.","둘은 어깨를 맞대고 빗속을 걸었습니다.","하은이네 집 앞에서 하은이는 「정말 고마워.」 하고 손을 흔들었습니다.","다음 날, 하은이는 예린이에게 줄 사탕을 주머니에 넣고 학교에 갔습니다."],"title":"비 오는 하굣길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_b#16','kor',3,1,'u4','','g3_1_kor_u4_review_b','unit_review','K3-1-u4-C34',2,'mc','auto','소율이의 생각그물에서 기준과 맞지 않게 들어간 낱말은 무엇일까요?',ARRAY['K3-1-u4-X34']::text[],false,'{"seq":16,"concept":"K3-1-u4-C34","difficulty":2,"kind":"mc","stem":"소율이의 생각그물에서 기준과 맞지 않게 들어간 낱말은 무엇일까요?","options":[{"t":"운동장","correct":true},{"t":"책상","mis":"K3-1-u4-X34"},{"t":"칠판","mis":"K3-1-u4-X34"},{"t":"도서실","mis":"K3-1-u4-X34"}],"explanation":["물건 가지","운동장은 장소","기준"],"asset":{"type":"passage","lines":["가운데 낱말: 학교","장소 — 도서실 · 급식실 · 강당","사람 — 선생님 · 친구 · 사서 선생님","물건 — 책상 · 칠판 · 운동장"],"title":"소율이의 생각그물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_b#17','kor',3,1,'u4','','g3_1_kor_u4_review_b','unit_review','K3-1-u4-C9',3,'mc','auto','「꿀벌이 하는 일」에서 처음에 「세 가지」라고 말한 것을 들으면 좋은 점은 무엇일까요?',ARRAY['K3-1-u4-X07','K3-1-u4-X06']::text[],false,'{"seq":17,"concept":"K3-1-u4-C9","difficulty":3,"kind":"mc","stem":"「꿀벌이 하는 일」에서 처음에 「세 가지」라고 말한 것을 들으면 좋은 점은 무엇일까요?","options":[{"t":"세 가지를 모두 찾았는지 살피며 빠짐없이 메모할 수 있어요.","correct":true},{"t":"첫째만 적으면 돼요.","mis":"K3-1-u4-X07"},{"t":"「세 가지」가 가장 중요한 내용이에요.","mis":"K3-1-u4-X06"},{"t":"좋은 점이 없어요.","mis":"K3-1-u4-X07"}],"explanation":["세 가지","빠짐없이","확인"],"asset":{"type":"passage","lines":["꿀벌이 하는 일을 세 가지 알려 줄게요.","첫째, 꿀벌은 꽃에서 꿀을 모아 벌집에 쌓아 둬요.","둘째, 꽃가루를 다른 꽃으로 옮겨 열매가 맺히게 도와요.","셋째, 춤을 추어 꽃이 있는 곳을 다른 벌에게 알려요.","가장 중요한 것은 꿀벌이 열매를 맺게 돕는다는 점이에요."],"title":"들은 설명 — 꿀벌이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_b#18','kor',3,1,'u4','','g3_1_kor_u4_review_b','unit_review','K3-1-u4-C14',3,'mc','auto','「종이컵 전화기 만들기」에서 강조한 내용을 알 수 있는 단서로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X12','K3-1-u4-X06']::text[],false,'{"seq":18,"concept":"K3-1-u4-C14","difficulty":3,"kind":"mc","stem":"「종이컵 전화기 만들기」에서 강조한 내용을 알 수 있는 단서로 알맞은 것은 무엇일까요?","options":[{"t":"소리로 「가장 중요한 것!」이라고 하고 화면 글로도 보여 줬다.","correct":true},{"t":"그림이 가장 많이 나왔다.","mis":"K3-1-u4-X12"},{"t":"맨 처음에 나왔다.","mis":"K3-1-u4-X06"},{"t":"가장 짧은 말이었다.","mis":"K3-1-u4-X06"}],"explanation":["소리","화면 글","두 번"],"asset":{"type":"passage","lines":["(소리) 종이컵 전화기를 만들어 봐요.","(그림) 어른과 함께 종이컵 두 개의 바닥 가운데에 작은 구멍을 뚫어요.","(그림) 구멍에 실을 넣고 컵 안쪽에서 매듭을 지어요.","(그림) 다른 컵에도 실 끝을 똑같이 끼워 묶어요.","(소리) 가장 중요한 것! 실을 팽팽하게 당겨야 소리가 잘 들려요.","(화면 글) 실은 팽팽하게!"],"title":"영상 — 종이컵 전화기 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_b#19','kor',3,1,'u4','','g3_1_kor_u4_review_b','unit_review','K3-1-u4-C21',3,'mc','auto','「잎을 떨구어」에서 「떨구다」의 뜻을 짐작하는 데 도움이 되는 것은 무엇일까요?',ARRAY['K3-1-u4-X19']::text[],false,'{"seq":19,"concept":"K3-1-u4-C21","difficulty":3,"kind":"mc","stem":"「잎을 떨구어」에서 「떨구다」의 뜻을 짐작하는 데 도움이 되는 것은 무엇일까요?","options":[{"t":"가을이 깊어진다는 때와 앞말 「잎을」","correct":true},{"t":"「떨」이라는 소리가 「떨리다」와 같아서","mis":"K3-1-u4-X19"},{"t":"도움이 되는 것은 없다","mis":"K3-1-u4-X19"},{"t":"글과 관계없는 다른 책","mis":"K3-1-u4-X19"}],"explanation":["때","앞말","짐작"],"asset":{"type":"passage","lines":["가을이 깊어지면 나무는 겨울 채비를 합니다.","잎을 떨구어 몸속의 물이 빠져나가지 않게 합니다.","봄에 틔울 겨울눈은 단단한 껍질로 꼭꼭 감쌉니다.","줄기는 두꺼운 껍질로 찬 바람을 막습니다."],"title":"겨울 채비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_b#20','kor',3,1,'u4','','g3_1_kor_u4_review_b','unit_review','K3-1-u4-C24',3,'mc','auto','「비 오는 하굣길」의 일을 차례대로 늘어놓은 것은 무엇일까요? (가) 어깨를 맞대고 걸음 (나) 우산이 없음 (다) 고맙다고 손을 흔듦 (라) 예린이가 우산을 펼침',ARRAY['K3-1-u4-X23']::text[],false,'{"seq":20,"concept":"K3-1-u4-C24","difficulty":3,"kind":"mc","stem":"「비 오는 하굣길」의 일을 차례대로 늘어놓은 것은 무엇일까요? (가) 어깨를 맞대고 걸음 (나) 우산이 없음 (다) 고맙다고 손을 흔듦 (라) 예린이가 우산을 펼침","options":[{"t":"나 → 라 → 가 → 다","correct":true},{"t":"라 → 나 → 가 → 다","mis":"K3-1-u4-X23"},{"t":"나 → 가 → 라 → 다","mis":"K3-1-u4-X23"},{"t":"다 → 가 → 라 → 나","mis":"K3-1-u4-X23"}],"explanation":["우산 없음","함께 씀","고마움"],"asset":{"type":"passage","lines":["아침부터 비가 내렸습니다.","수업이 끝나고 보니 하은이의 우산이 우산꽂이에 없었습니다.","하은이는 학교 현관 앞에서 발을 동동 굴렀습니다.","그때 예린이가 다가와 「같이 쓰고 가자.」 하고 우산을 펼쳤습니다.","둘은 어깨를 맞대고 빗속을 걸었습니다.","하은이네 집 앞에서 하은이는 「정말 고마워.」 하고 손을 흔들었습니다.","다음 날, 하은이는 예린이에게 줄 사탕을 주머니에 넣고 학교에 갔습니다."],"title":"비 오는 하굣길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_b#21','kor',3,1,'u4','','g3_1_kor_u4_review_b','unit_review','K3-1-u4-C32',3,'mc','auto','예린이의 메모에 제목을 붙인다면 가장 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X02','K3-1-u4-X01','K3-1-u4-X31']::text[],false,'{"seq":21,"concept":"K3-1-u4-C32","difficulty":3,"kind":"mc","stem":"예린이의 메모에 제목을 붙인다면 가장 알맞은 것은 무엇일까요?","options":[{"t":"손을 바르게 씻는 방법","correct":true},{"t":"비누","mis":"K3-1-u4-X02"},{"t":"오늘 들은 이야기 전부","mis":"K3-1-u4-X01"},{"t":"제목은 필요 없다","mis":"K3-1-u4-X31"}],"explanation":["무엇에 대한","메모","제목"],"asset":{"type":"passage","lines":["1. 비누 거품으로 문지르기 → 때가 잘 빠짐","2. 손가락 사이 · 손톱 밑 씻기 → 숨은 때까지","3. 수건으로 물기 닦기 → 손이 트지 않음"],"title":"예린이의 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_b#22','kor',3,1,'u4','','g3_1_kor_u4_review_b','unit_review','K3-1-u4-C34',3,'mc','auto','생각그물 「바다」에서 「바다에 사는 생물」 가지에 들어갈 낱말끼리 묶은 것은 무엇일까요?',ARRAY['K3-1-u4-X34']::text[],false,'{"seq":22,"concept":"K3-1-u4-C34","difficulty":3,"kind":"mc","stem":"생각그물 「바다」에서 「바다에 사는 생물」 가지에 들어갈 낱말끼리 묶은 것은 무엇일까요?","options":[{"t":"게 · 조개 · 오징어","correct":true},{"t":"모래성 · 물놀이 · 게","mis":"K3-1-u4-X34"},{"t":"수영복 · 튜브 · 조개","mis":"K3-1-u4-X34"},{"t":"모래 · 파도 · 바람","mis":"K3-1-u4-X34"}],"explanation":["기준","바다에 사는","생물"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_b#23','kor',3,1,'u4','','g3_1_kor_u4_review_b','unit_review','K3-1-u4-C8',4,'essay','teacher','체험학습 안내에서 강조한 내용을 찾아 쓰고, 강조했다는 것을 어떻게 알 수 있었는지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-1-u4-C8","difficulty":4,"kind":"essay","stem":"체험학습 안내에서 강조한 내용을 찾아 쓰고, 강조했다는 것을 어떻게 알 수 있었는지 쓰세요.","answer_guide":{"answer":"예: 강조한 내용은 선생님 곁을 떠나지 않는 것이다. 「꼭 기억할 것은」이라고 말했고, 「다시 말할게요」 하며 한 번 더 되풀이했기 때문에 알 수 있었다.","scoring_points":["강조한 내용을 바르게 찾았는가","「꼭」 같은 말을 단서로 들었는가","되풀이를 단서로 들었는가"]},"explanation":["꼭","되풀이","강조"],"asset":{"type":"speech","turns":[{"who":"선생님","text":"다음 주 수요일에 현장 체험학습을 가요."},{"who":"선생님","text":"아침 여덟 시 반까지 학교 정문에 모여요."},{"who":"선생님","text":"도시락과 물, 모자를 챙겨요."},{"who":"선생님","text":"꼭 기억할 것은 선생님 곁을 떠나지 않는 거예요. 다시 말할게요. 선생님 곁을 떠나지 않아요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_b#24','kor',3,1,'u4','','g3_1_kor_u4_review_b','unit_review','K3-1-u4-C22',4,'essay','teacher','「다람쥐가 묻은 도토리」를 두세 문장으로 간추려 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-1-u4-C22","difficulty":4,"kind":"essay","stem":"「다람쥐가 묻은 도토리」를 두세 문장으로 간추려 쓰세요.","answer_guide":{"answer":"예: 다람쥐는 가을에 도토리를 묻어 두었다가 겨울에 꺼내 먹는다. 찾지 못한 도토리는 나무로 자라 숲을 키운다.","scoring_points":["중요한 내용을 담았는가","두세 문장으로 짧게 썼는가","중심 생각이 드러나는가"]},"explanation":["중요한 내용","짧게","중심 생각"],"asset":{"type":"passage","lines":["다람쥐는 가을에 도토리를 모아 땅에 묻어 둡니다.","겨울잠을 자다 깨면 묻어 둔 도토리를 꺼내 먹습니다.","찾지 못한 도토리는 봄에 싹을 틔워 나무로 자랍니다.","이렇게 다람쥐가 묻은 도토리는 다람쥐도 살리고 숲도 키웁니다."],"title":"다람쥐가 묻은 도토리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_b#25','kor',3,1,'u4','','g3_1_kor_u4_review_b','unit_review','K3-1-u4-C33',4,'essay','teacher','띄어쓰기를 바꾸면 뜻이 달라지는 문장을 하나 만들어 두 가지로 쓰고, 각각의 뜻을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-1-u4-C33","difficulty":4,"kind":"essay","stem":"띄어쓰기를 바꾸면 뜻이 달라지는 문장을 하나 만들어 두 가지로 쓰고, 각각의 뜻을 쓰세요.","answer_guide":{"answer":"예: 「누나가 죽을 먹는다」는 누나가 죽을 먹는다는 뜻이다. 「누나 가죽을 먹는다」는 누나의 가죽을 먹는다는 엉뚱한 뜻이 된다.","scoring_points":["두 가지로 띄어 썼는가","첫째 뜻을 썼는가","둘째 뜻을 썼는가"]},"explanation":["띄어쓰기","뜻 하나","뜻 둘"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_c#1','kor',3,1,'u4','','g3_1_kor_u4_review_c','unit_review','K3-1-u4-C4',1,'mc','auto','준비물을 잊지 않으려면 어떻게 하면 좋을까요?',ARRAY['K3-1-u4-X03','K3-1-u4-X04','K3-1-u4-X05']::text[],false,'{"seq":1,"concept":"K3-1-u4-C4","difficulty":1,"kind":"mc","stem":"준비물을 잊지 않으려면 어떻게 하면 좋을까요?","options":[{"t":"들을 때 준비물을 메모해 둔다.","correct":true},{"t":"한 번 들었으니 잊지 않을 거라 믿는다.","mis":"K3-1-u4-X03"},{"t":"메모는 공부할 때만 하니 적지 않는다.","mis":"K3-1-u4-X04"},{"t":"준비물 이야기는 흘려듣는다.","mis":"K3-1-u4-X05"}],"explanation":["준비물","들을 때","메모"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_c#2','kor',3,1,'u4','','g3_1_kor_u4_review_c','unit_review','K3-1-u4-C7',1,'mc','auto','설명을 듣기 전에 아는 내용을 떠올리는 까닭은 무엇일까요?',ARRAY['K3-1-u4-X05','K3-1-u4-X07','K3-1-u4-X06']::text[],false,'{"seq":2,"concept":"K3-1-u4-C7","difficulty":1,"kind":"mc","stem":"설명을 듣기 전에 아는 내용을 떠올리는 까닭은 무엇일까요?","options":[{"t":"새로 듣는 내용을 더 잘 알아들으려고","correct":true},{"t":"아는 내용이면 듣지 않으려고","mis":"K3-1-u4-X05"},{"t":"아는 내용만 적으려고","mis":"K3-1-u4-X07"},{"t":"아는 내용이 가장 중요해서","mis":"K3-1-u4-X06"}],"explanation":["아는 것","새로운 것","잘 알아듣기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_c#3','kor',3,1,'u4','','g3_1_kor_u4_review_c','unit_review','K3-1-u4-C13',1,'mc','auto','영상에서 그림 · 장면을 살피면 좋은 점은 무엇일까요?',ARRAY['K3-1-u4-X12','K3-1-u4-X10','K3-1-u4-X13']::text[],false,'{"seq":3,"concept":"K3-1-u4-C13","difficulty":1,"kind":"mc","stem":"영상에서 그림 · 장면을 살피면 좋은 점은 무엇일까요?","options":[{"t":"어떻게 하는지 실제 모습을 알 수 있어요.","correct":true},{"t":"좋은 점이 없어요 — 그림은 재미로 넣어요.","mis":"K3-1-u4-X12"},{"t":"소리를 듣지 않아도 돼요.","mis":"K3-1-u4-X10"},{"t":"영상을 빨리 넘길 수 있어요.","mis":"K3-1-u4-X13"}],"explanation":["그림","실제 모습","하는 방법"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_c#4','kor',3,1,'u4','','g3_1_kor_u4_review_c','unit_review','K3-1-u4-C18',1,'mc','auto','뒷받침 문장이 하는 일은 무엇일까요?',ARRAY['K3-1-u4-X17','K3-1-u4-X15','K3-1-u4-X18']::text[],false,'{"seq":4,"concept":"K3-1-u4-C18","difficulty":1,"kind":"mc","stem":"뒷받침 문장이 하는 일은 무엇일까요?","options":[{"t":"중심 문장을 덧붙여 설명하거나 예를 들어요.","correct":true},{"t":"문단을 대표해요.","mis":"K3-1-u4-X17"},{"t":"중심 문장과 관계없는 이야기를 해요.","mis":"K3-1-u4-X15"},{"t":"제목을 알려 줘요.","mis":"K3-1-u4-X18"}],"explanation":["덧붙여 설명","예","뒷받침"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_c#5','kor',3,1,'u4','','g3_1_kor_u4_review_c','unit_review','K3-1-u4-C23',1,'mc','auto','과정을 설명하는 글에서 차례를 알려 주는 말은 무엇일까요?',ARRAY['K3-1-u4-X22']::text[],false,'{"seq":5,"concept":"K3-1-u4-C23","difficulty":1,"kind":"mc","stem":"과정을 설명하는 글에서 차례를 알려 주는 말은 무엇일까요?","options":[{"t":"먼저 · 그다음 · 마지막으로","correct":true},{"t":"예쁘게 · 크게 · 작게","mis":"K3-1-u4-X22"},{"t":"그런데 · 하지만 · 그러나","mis":"K3-1-u4-X22"},{"t":"언제나 · 모두 · 아주","mis":"K3-1-u4-X22"}],"explanation":["먼저","그다음","마지막으로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_c#6','kor',3,1,'u4','','g3_1_kor_u4_review_c','unit_review','K3-1-u4-C26',1,'mc','auto','우산이 없어 발을 동동 구를 때 하은이의 마음은 어땠을까요?',ARRAY['K3-1-u4-X25','K3-1-u4-X26']::text[],false,'{"seq":6,"concept":"K3-1-u4-C26","difficulty":1,"kind":"mc","stem":"우산이 없어 발을 동동 구를 때 하은이의 마음은 어땠을까요?","options":[{"t":"걱정스럽다","correct":true},{"t":"신난다","mis":"K3-1-u4-X25"},{"t":"뿌듯하다","mis":"K3-1-u4-X26"},{"t":"졸리다","mis":"K3-1-u4-X26"}],"explanation":["우산이 없음","발을 동동","걱정"],"asset":{"type":"passage","lines":["아침부터 비가 내렸습니다.","수업이 끝나고 보니 하은이의 우산이 우산꽂이에 없었습니다.","하은이는 학교 현관 앞에서 발을 동동 굴렀습니다.","그때 예린이가 다가와 「같이 쓰고 가자.」 하고 우산을 펼쳤습니다.","둘은 어깨를 맞대고 빗속을 걸었습니다.","하은이네 집 앞에서 하은이는 「정말 고마워.」 하고 손을 흔들었습니다.","다음 날, 하은이는 예린이에게 줄 사탕을 주머니에 넣고 학교에 갔습니다."],"title":"비 오는 하굣길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_c#7','kor',3,1,'u4','','g3_1_kor_u4_review_c','unit_review','K3-1-u4-C32',1,'mc','auto','메모를 다 쓴 뒤에 할 일은 무엇일까요?',ARRAY['K3-1-u4-X31','K3-1-u4-X09']::text[],false,'{"seq":7,"concept":"K3-1-u4-C32","difficulty":1,"kind":"mc","stem":"메모를 다 쓴 뒤에 할 일은 무엇일까요?","options":[{"t":"제목 · 숫자 · 기호를 알맞게 썼는지 점검한다.","correct":true},{"t":"점검 없이 덮는다.","mis":"K3-1-u4-X31"},{"t":"글자 수만 센다.","mis":"K3-1-u4-X31"},{"t":"모든 줄에 별표를 더 붙인다.","mis":"K3-1-u4-X09"}],"explanation":["다 쓴 뒤","점검","한눈에"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_c#8','kor',3,1,'u4','','g3_1_kor_u4_review_c','unit_review','K3-1-u4-C34',1,'mc','auto','생각그물을 만들 때 낱말을 나누는 방법으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X34']::text[],false,'{"seq":8,"concept":"K3-1-u4-C34","difficulty":1,"kind":"mc","stem":"생각그물을 만들 때 낱말을 나누는 방법으로 알맞은 것은 무엇일까요?","options":[{"t":"기준을 정해 기준에 맞는 낱말끼리 모은다.","correct":true},{"t":"기준 없이 생각나는 대로 섞는다.","mis":"K3-1-u4-X34"},{"t":"글자 수가 같은 낱말끼리 모은다.","mis":"K3-1-u4-X34"},{"t":"한 가지에 모든 낱말을 넣는다.","mis":"K3-1-u4-X34"}],"explanation":["기준","맞는 낱말","모으기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_c#9','kor',3,1,'u4','','g3_1_kor_u4_review_c','unit_review','K3-1-u4-C10',2,'mc','auto','「도서실 이용 안내」를 메모할 때 별표를 붙이기에 가장 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X09','K3-1-u4-X08','K3-1-u4-X06']::text[],false,'{"seq":9,"concept":"K3-1-u4-C10","difficulty":2,"kind":"mc","stem":"「도서실 이용 안내」를 메모할 때 별표를 붙이기에 가장 알맞은 것은 무엇일까요?","options":[{"t":"일주일 안에 꼭 돌려주기","correct":true},{"t":"모든 줄","mis":"K3-1-u4-X09"},{"t":"제목 줄","mis":"K3-1-u4-X08"},{"t":"「새로 열었어요」","mis":"K3-1-u4-X06"}],"explanation":["★","가장 중요한 곳","하나만"],"asset":{"type":"speech","turns":[{"who":"사서 선생님","text":"도서실을 새로 열었어요."},{"who":"사서 선생님","text":"쉬는 시간과 점심시간에 이용할 수 있어요."},{"who":"사서 선생님","text":"책은 한 번에 두 권까지 빌려요."},{"who":"사서 선생님","text":"가장 중요한 약속! 빌린 책은 일주일 안에 꼭 돌려주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_c#10','kor',3,1,'u4','','g3_1_kor_u4_review_c','unit_review','K3-1-u4-C10',2,'mc','auto','민재의 메모에서 숫자 1, 2, 3이 하는 일은 무엇일까요?',ARRAY['K3-1-u4-X08']::text[],false,'{"seq":10,"concept":"K3-1-u4-C10","difficulty":2,"kind":"mc","stem":"민재의 메모에서 숫자 1, 2, 3이 하는 일은 무엇일까요?","options":[{"t":"내용을 하나씩 나누어 차례를 매겨 줘요.","correct":true},{"t":"메모의 제목이에요.","mis":"K3-1-u4-X08"},{"t":"가장 중요한 곳을 알려 줘요.","mis":"K3-1-u4-X08"},{"t":"아무 뜻이 없어요.","mis":"K3-1-u4-X08"}],"explanation":["1, 2, 3","나누기","차례"],"asset":{"type":"passage","lines":["제목: 현장 체험학습","1. 다음 주 수요일","2. 아침 8시 30분, 학교 정문","3. 도시락 · 물 · 모자","★ 선생님 곁을 떠나지 않기"],"title":"민재의 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_c#11','kor',3,1,'u4','','g3_1_kor_u4_review_c','unit_review','K3-1-u4-C13',2,'mc','auto','「우유갑 화분 만들기」의 그림을 보면 알 수 있는 것은 무엇일까요?',ARRAY['K3-1-u4-X12','K3-1-u4-X10','K3-1-u4-X11']::text[],false,'{"seq":11,"concept":"K3-1-u4-C13","difficulty":2,"kind":"mc","stem":"「우유갑 화분 만들기」의 그림을 보면 알 수 있는 것은 무엇일까요?","options":[{"t":"우유갑을 씻고 자르고 구멍을 내는 모습","correct":true},{"t":"그림은 꾸밈이라 알 수 있는 것이 없다","mis":"K3-1-u4-X12"},{"t":"구멍을 뚫는 까닭","mis":"K3-1-u4-X10"},{"t":"「구멍은 꼭!」이라는 글","mis":"K3-1-u4-X11"}],"explanation":["그림","하는 모습","차례"],"asset":{"type":"passage","lines":["(소리) 다 마신 우유갑으로 화분을 만들어 봐요.","(그림) 우유갑을 물로 깨끗이 씻어요.","(그림) 어른과 함께 우유갑 옆면을 잘라 내요.","(그림) 바닥에 작은 구멍을 서너 개 뚫어요.","(소리) 물이 빠질 구멍을 꼭 뚫어야 뿌리가 썩지 않아요.","(화면 글) 구멍은 꼭!"],"title":"영상 — 우유갑 화분 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_c#12','kor',3,1,'u4','','g3_1_kor_u4_review_c','unit_review','K3-1-u4-C11',2,'mc','auto','「횡단보도를 건너는 방법」에서 그림으로 보여 준 모습은 무엇일까요?',ARRAY['K3-1-u4-X10','K3-1-u4-X11','K3-1-u4-X12']::text[],false,'{"seq":12,"concept":"K3-1-u4-C11","difficulty":2,"kind":"mc","stem":"「횡단보도를 건너는 방법」에서 그림으로 보여 준 모습은 무엇일까요?","options":[{"t":"아이가 손을 들고 천천히 건너는 모습","correct":true},{"t":"「세 가지를 기억해요」라는 말","mis":"K3-1-u4-X10"},{"t":"「멈춰요 → 살펴요 → 건너요」라는 글","mis":"K3-1-u4-X11"},{"t":"그림은 나오지 않는다","mis":"K3-1-u4-X12"}],"explanation":["(그림)","눈으로 본 것","모습"],"asset":{"type":"passage","lines":["(소리) 횡단보도를 건널 때는 세 가지를 기억해요.","(화면 글) 멈춰요 → 살펴요 → 건너요","(그림) 초록불 앞에 멈춘 아이가 왼쪽과 오른쪽을 봐요.","(소리) 초록불이 켜져도 차가 멈췄는지 꼭 살펴요.","(화면 글) 차가 멈췄는지 꼭 확인!","(그림) 아이가 손을 들고 천천히 건너요."],"title":"영상 — 횡단보도를 건너는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_c#13','kor',3,1,'u4','','g3_1_kor_u4_review_c','unit_review','K3-1-u4-C21',2,'mc','auto','「싹을 틔워」에서 「틔우다」의 뜻으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X19']::text[],false,'{"seq":13,"concept":"K3-1-u4-C21","difficulty":2,"kind":"mc","stem":"「싹을 틔워」에서 「틔우다」의 뜻으로 알맞은 것은 무엇일까요?","options":[{"t":"싹이 돋아 나오게 하다","correct":true},{"t":"땅에 깊이 묻다","mis":"K3-1-u4-X19"},{"t":"튀어 오르게 하다","mis":"K3-1-u4-X19"},{"t":"도토리를 먹다","mis":"K3-1-u4-X19"}],"explanation":["봄에","나무로 자람","돋아 나옴"],"asset":{"type":"passage","lines":["다람쥐는 가을에 도토리를 모아 땅에 묻어 둡니다.","겨울잠을 자다 깨면 묻어 둔 도토리를 꺼내 먹습니다.","찾지 못한 도토리는 봄에 싹을 틔워 나무로 자랍니다.","이렇게 다람쥐가 묻은 도토리는 다람쥐도 살리고 숲도 키웁니다."],"title":"다람쥐가 묻은 도토리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_c#14','kor',3,1,'u4','','g3_1_kor_u4_review_c','unit_review','K3-1-u4-C19',2,'mc','auto','「두부가 만들어지는 과정」 ②문단의 중심 문장은 무엇일까요?',ARRAY['K3-1-u4-X17','K3-1-u4-X15']::text[],false,'{"seq":14,"concept":"K3-1-u4-C19","difficulty":2,"kind":"mc","stem":"「두부가 만들어지는 과정」 ②문단의 중심 문장은 무엇일까요?","options":[{"t":"그다음 불린 콩을 갈아 끓인 뒤 천에 거릅니다.","correct":true},{"t":"찌꺼기는 천에 남고 콩물만 빠져나옵니다.","mis":"K3-1-u4-X17"},{"t":"콩이 물을 먹어 통통하게 부풀어 오릅니다.","mis":"K3-1-u4-X15"},{"t":"몽글몽글 엉긴 것을 틀에 눌러 담으면 두부가 됩니다.","mis":"K3-1-u4-X15"}],"explanation":["②문단","대표","중심 문장"],"asset":{"type":"passage","lines":["① 먼저 콩을 물에 하룻밤 불립니다.","콩이 물을 먹어 통통하게 부풀어 오릅니다.","② 그다음 불린 콩을 갈아 끓인 뒤 천에 거릅니다.","찌꺼기는 천에 남고 콩물만 빠져나옵니다.","③ 마지막으로 콩물에 굳히는 물을 넣어 엉기게 합니다.","몽글몽글 엉긴 것을 틀에 눌러 담으면 두부가 됩니다."],"title":"두부가 만들어지는 과정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_c#15','kor',3,1,'u4','','g3_1_kor_u4_review_c','unit_review','K3-1-u4-C25',2,'mc','auto','「비 오는 하굣길」에 나온 장소를 일어난 차례대로 쓴 것은 무엇일까요?',ARRAY['K3-1-u4-X23','K3-1-u4-X24']::text[],false,'{"seq":15,"concept":"K3-1-u4-C25","difficulty":2,"kind":"mc","stem":"「비 오는 하굣길」에 나온 장소를 일어난 차례대로 쓴 것은 무엇일까요?","options":[{"t":"학교 현관 앞 → 빗속 길 → 하은이네 집 앞","correct":true},{"t":"하은이네 집 앞 → 학교 현관 앞","mis":"K3-1-u4-X23"},{"t":"운동장 → 교실","mis":"K3-1-u4-X24"},{"t":"장소는 나오지 않는다","mis":"K3-1-u4-X24"}],"explanation":["현관 앞","빗속","집 앞"],"asset":{"type":"passage","lines":["아침부터 비가 내렸습니다.","수업이 끝나고 보니 하은이의 우산이 우산꽂이에 없었습니다.","하은이는 학교 현관 앞에서 발을 동동 굴렀습니다.","그때 예린이가 다가와 「같이 쓰고 가자.」 하고 우산을 펼쳤습니다.","둘은 어깨를 맞대고 빗속을 걸었습니다.","하은이네 집 앞에서 하은이는 「정말 고마워.」 하고 손을 흔들었습니다.","다음 날, 하은이는 예린이에게 줄 사탕을 주머니에 넣고 학교에 갔습니다."],"title":"비 오는 하굣길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_c#16','kor',3,1,'u4','','g3_1_kor_u4_review_c','unit_review','K3-1-u4-C32',2,'mc','auto','메모 점검표에 넣기에 알맞지 않은 물음은 무엇일까요?',ARRAY['K3-1-u4-X31']::text[],false,'{"seq":16,"concept":"K3-1-u4-C32","difficulty":2,"kind":"mc","stem":"메모 점검표에 넣기에 알맞지 않은 물음은 무엇일까요?","options":[{"t":"글씨를 얼마나 많이 썼나요?","correct":true},{"t":"알맞은 제목을 썼나요?","mis":"K3-1-u4-X31"},{"t":"숫자나 기호를 썼나요?","mis":"K3-1-u4-X31"},{"t":"한눈에 알아볼 수 있나요?","mis":"K3-1-u4-X31"}],"explanation":["제목","숫자 · 기호","한눈에"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_c#17','kor',3,1,'u4','','g3_1_kor_u4_review_c','unit_review','K3-1-u4-C6',3,'mc','auto','체험학습 안내를 듣는 목적에 맞게 들은 모습은 무엇일까요?',ARRAY['K3-1-u4-X05','K3-1-u4-X06']::text[],false,'{"seq":17,"concept":"K3-1-u4-C6","difficulty":3,"kind":"mc","stem":"체험학습 안내를 듣는 목적에 맞게 들은 모습은 무엇일까요?","options":[{"t":"언제, 어디로, 무엇을 챙겨 가는지에 귀를 기울였다.","correct":true},{"t":"선생님 목소리가 어떤지에만 귀를 기울였다.","mis":"K3-1-u4-X05"},{"t":"딴생각하다 마지막 말만 들었다.","mis":"K3-1-u4-X05"},{"t":"가장 신기한 말을 찾았다.","mis":"K3-1-u4-X06"}],"explanation":["언제","어디로","무엇을"],"asset":{"type":"speech","turns":[{"who":"선생님","text":"다음 주 수요일에 현장 체험학습을 가요."},{"who":"선생님","text":"아침 여덟 시 반까지 학교 정문에 모여요."},{"who":"선생님","text":"도시락과 물, 모자를 챙겨요."},{"who":"선생님","text":"꼭 기억할 것은 선생님 곁을 떠나지 않는 거예요. 다시 말할게요. 선생님 곁을 떠나지 않아요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_c#18','kor',3,1,'u4','','g3_1_kor_u4_review_c','unit_review','K3-1-u4-C15',3,'mc','auto','「페트병 버리는 방법」을 메모할 때 화면 글을 함께 보면 좋은 점은 무엇일까요?',ARRAY['K3-1-u4-X10','K3-1-u4-X11','K3-1-u4-X12']::text[],false,'{"seq":18,"concept":"K3-1-u4-C15","difficulty":3,"kind":"mc","stem":"「페트병 버리는 방법」을 메모할 때 화면 글을 함께 보면 좋은 점은 무엇일까요?","options":[{"t":"「비우고 · 떼고 · 누르고」처럼 중요한 말을 짧게 옮길 수 있어요.","correct":true},{"t":"좋은 점이 없어요 — 소리만 적으면 돼요.","mis":"K3-1-u4-X10"},{"t":"화면 글은 꾸밈이라 옮기면 안 돼요.","mis":"K3-1-u4-X11"},{"t":"그림을 볼 필요가 없어져요.","mis":"K3-1-u4-X12"}],"explanation":["화면 글","짧은 말","메모"],"asset":{"type":"passage","lines":["(소리) 페트병은 이렇게 버려요.","(화면 글) 비우고 · 떼고 · 누르고","(그림) 아이가 페트병 속 물을 비워요.","(그림) 병에 붙은 비닐을 뜯어요.","(그림) 병을 발로 꾹 눌러 납작하게 해요.","(소리) 깨끗하게 버려야 다시 쓸 수 있어요.","(화면 글) 깨끗하게 버려야 다시 써요!"],"title":"영상 — 페트병 버리는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_c#19','kor',3,1,'u4','','g3_1_kor_u4_review_c','unit_review','K3-1-u4-C22',3,'mc','auto','설명하는 글을 간추릴 때 예만 모으면 생기는 문제는 무엇일까요?',ARRAY['K3-1-u4-X21','K3-1-u4-X20','K3-1-u4-X18']::text[],false,'{"seq":19,"concept":"K3-1-u4-C22","difficulty":3,"kind":"mc","stem":"설명하는 글을 간추릴 때 예만 모으면 생기는 문제는 무엇일까요?","options":[{"t":"글 전체가 말하려는 중요한 내용이 빠져요.","correct":true},{"t":"문제없어요 — 예가 가장 중요해요.","mis":"K3-1-u4-X21"},{"t":"글이 너무 길어져요.","mis":"K3-1-u4-X20"},{"t":"제목을 못 써요.","mis":"K3-1-u4-X18"}],"explanation":["예만","중심이 빠짐","간추리기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_c#20','kor',3,1,'u4','','g3_1_kor_u4_review_c','unit_review','K3-1-u4-C29',3,'mc','auto','「비 오는 하굣길」을 읽고 떠올린 경험으로 가장 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X28']::text[],false,'{"seq":20,"concept":"K3-1-u4-C29","difficulty":3,"kind":"mc","stem":"「비 오는 하굣길」을 읽고 떠올린 경험으로 가장 알맞은 것은 무엇일까요?","options":[{"t":"준비물을 두고 와 걱정할 때 짝이 빌려줘서 고마웠던 일","correct":true},{"t":"비 오는 날 집에서 텔레비전을 본 일","mis":"K3-1-u4-X28"},{"t":"사탕을 사 먹은 일","mis":"K3-1-u4-X28"},{"t":"운동회 달리기를 한 일","mis":"K3-1-u4-X28"}],"explanation":["걱정","도움","고마움"],"asset":{"type":"passage","lines":["아침부터 비가 내렸습니다.","수업이 끝나고 보니 하은이의 우산이 우산꽂이에 없었습니다.","하은이는 학교 현관 앞에서 발을 동동 굴렀습니다.","그때 예린이가 다가와 「같이 쓰고 가자.」 하고 우산을 펼쳤습니다.","둘은 어깨를 맞대고 빗속을 걸었습니다.","하은이네 집 앞에서 하은이는 「정말 고마워.」 하고 손을 흔들었습니다.","다음 날, 하은이는 예린이에게 줄 사탕을 주머니에 넣고 학교에 갔습니다."],"title":"비 오는 하굣길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_c#21','kor',3,1,'u4','','g3_1_kor_u4_review_c','unit_review','K3-1-u4-C30',3,'mc','auto','「우유갑 화분 만들기」를 차례대로 메모하는 까닭은 무엇일까요?',ARRAY['K3-1-u4-X29','K3-1-u4-X12']::text[],false,'{"seq":21,"concept":"K3-1-u4-C30","difficulty":3,"kind":"mc","stem":"「우유갑 화분 만들기」를 차례대로 메모하는 까닭은 무엇일까요?","options":[{"t":"메모를 보고 그대로 따라 만들 수 있어서","correct":true},{"t":"차례는 아무래도 상관없어서","mis":"K3-1-u4-X29"},{"t":"짧게 쓰려고 차례를 빼려고","mis":"K3-1-u4-X29"},{"t":"그림을 안 봐도 되어서","mis":"K3-1-u4-X12"}],"explanation":["차례대로","따라 만들기","숫자"],"asset":{"type":"passage","lines":["(소리) 다 마신 우유갑으로 화분을 만들어 봐요.","(그림) 우유갑을 물로 깨끗이 씻어요.","(그림) 어른과 함께 우유갑 옆면을 잘라 내요.","(그림) 바닥에 작은 구멍을 서너 개 뚫어요.","(소리) 물이 빠질 구멍을 꼭 뚫어야 뿌리가 썩지 않아요.","(화면 글) 구멍은 꼭!"],"title":"영상 — 우유갑 화분 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_c#22','kor',3,1,'u4','','g3_1_kor_u4_review_c','unit_review','K3-1-u4-C33',3,'mc','auto','「할머니가 시장에 가신다」의 띄어쓰기를 바르게 설명한 것은 무엇일까요?',ARRAY['K3-1-u4-X33','K3-1-u4-X32']::text[],false,'{"seq":22,"concept":"K3-1-u4-C33","difficulty":3,"kind":"mc","stem":"「할머니가 시장에 가신다」의 띄어쓰기를 바르게 설명한 것은 무엇일까요?","options":[{"t":"「가」와 「에」는 앞말에 붙여 쓰고, 낱말과 낱말은 띄어 썼어요.","correct":true},{"t":"「가」와 「에」도 앞말과 띄어 써야 해요.","mis":"K3-1-u4-X33"},{"t":"모두 붙여 써도 뜻은 같아요.","mis":"K3-1-u4-X32"},{"t":"띄어쓰기는 마음대로 해도 돼요.","mis":"K3-1-u4-X32"}],"explanation":["붙는 말","앞말에","낱말끼리 띄움"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_c#23','kor',3,1,'u4','','g3_1_kor_u4_review_c','unit_review','K3-1-u4-C11',4,'essay','teacher','「우유갑 화분 만들기」에서 소리 · 화면 글 · 그림으로 알게 된 것을 하나씩 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-1-u4-C11","difficulty":4,"kind":"essay","stem":"「우유갑 화분 만들기」에서 소리 · 화면 글 · 그림으로 알게 된 것을 하나씩 쓰세요.","answer_guide":{"answer":"예: 소리 — 물이 빠질 구멍을 뚫어야 뿌리가 썩지 않는다. 화면 글 — 구멍은 꼭 뚫어야 한다. 그림 — 우유갑을 씻고 옆면을 잘라 내는 모습.","scoring_points":["소리로 알게 된 것을 썼는가","화면 글로 알게 된 것을 썼는가","그림으로 알게 된 것을 썼는가"]},"explanation":["소리","화면 글","그림"],"asset":{"type":"passage","lines":["(소리) 다 마신 우유갑으로 화분을 만들어 봐요.","(그림) 우유갑을 물로 깨끗이 씻어요.","(그림) 어른과 함께 우유갑 옆면을 잘라 내요.","(그림) 바닥에 작은 구멍을 서너 개 뚫어요.","(소리) 물이 빠질 구멍을 꼭 뚫어야 뿌리가 썩지 않아요.","(화면 글) 구멍은 꼭!"],"title":"영상 — 우유갑 화분 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_c#24','kor',3,1,'u4','','g3_1_kor_u4_review_c','unit_review','K3-1-u4-C24',4,'essay','teacher','「비 오는 하굣길」에서 일어난 일을 처음 · 가운데 · 끝으로 나누어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-1-u4-C24","difficulty":4,"kind":"essay","stem":"「비 오는 하굣길」에서 일어난 일을 처음 · 가운데 · 끝으로 나누어 쓰세요.","answer_guide":{"answer":"예: 처음 — 수업이 끝나고 하은이의 우산이 없어졌다. 가운데 — 예린이가 우산을 같이 쓰자고 해서 함께 걸었다. 끝 — 하은이는 고맙다고 하고 다음 날 사탕을 챙겼다.","scoring_points":["처음에 일어난 일을 썼는가","가운데에 일어난 일을 썼는가","끝에 일어난 일을 차례대로 썼는가"]},"explanation":["처음","가운데","끝"],"asset":{"type":"passage","lines":["아침부터 비가 내렸습니다.","수업이 끝나고 보니 하은이의 우산이 우산꽂이에 없었습니다.","하은이는 학교 현관 앞에서 발을 동동 굴렀습니다.","그때 예린이가 다가와 「같이 쓰고 가자.」 하고 우산을 펼쳤습니다.","둘은 어깨를 맞대고 빗속을 걸었습니다.","하은이네 집 앞에서 하은이는 「정말 고마워.」 하고 손을 흔들었습니다.","다음 날, 하은이는 예린이에게 줄 사탕을 주머니에 넣고 학교에 갔습니다."],"title":"비 오는 하굣길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_c#25','kor',3,1,'u4','','g3_1_kor_u4_review_c','unit_review','K3-1-u4-C34',4,'essay','teacher','「여름」을 주제로 생각그물을 만들어 기준 세 가지와 기준마다 어울리는 낱말을 두 개씩 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-1-u4-C34","difficulty":4,"kind":"essay","stem":"「여름」을 주제로 생각그물을 만들어 기준 세 가지와 기준마다 어울리는 낱말을 두 개씩 쓰세요.","answer_guide":{"answer":"예: 날씨 — 덥다, 소나기. 먹을거리 — 수박, 팥빙수. 놀이 — 물놀이, 잠자리 잡기.","scoring_points":["기준 세 가지를 정했는가","기준마다 낱말 두 개를 썼는가","낱말이 기준에 맞는가"]},"explanation":["주제","기준","낱말"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_d#1','kor',3,1,'u4','','g3_1_kor_u4_review_d','unit_review','K3-1-u4-C10',1,'mc','auto','정리할 때 제목은 무슨 일을 할까요?',ARRAY['K3-1-u4-X08']::text[],false,'{"seq":1,"concept":"K3-1-u4-C10","difficulty":1,"kind":"mc","stem":"정리할 때 제목은 무슨 일을 할까요?","options":[{"t":"내용을 한눈에 알게 묶어 줘요.","correct":true},{"t":"차례를 매겨 줘요.","mis":"K3-1-u4-X08"},{"t":"가장 중요한 한 곳만 눈에 띄게 해요.","mis":"K3-1-u4-X08"},{"t":"아무 일도 하지 않아요.","mis":"K3-1-u4-X08"}],"explanation":["제목","묶기","한눈에"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_d#2','kor',3,1,'u4','','g3_1_kor_u4_review_d','unit_review','K3-1-u4-C9',1,'mc','auto','이 안내에서 책은 한 번에 몇 권까지 빌릴 수 있을까요?',ARRAY['K3-1-u4-X07']::text[],false,'{"seq":2,"concept":"K3-1-u4-C9","difficulty":1,"kind":"mc","stem":"이 안내에서 책은 한 번에 몇 권까지 빌릴 수 있을까요?","options":[{"t":"두 권","correct":true},{"t":"한 권","mis":"K3-1-u4-X07"},{"t":"세 권","mis":"K3-1-u4-X07"},{"t":"마음대로","mis":"K3-1-u4-X07"}],"explanation":["한 번에","두 권","까지"],"asset":{"type":"speech","turns":[{"who":"사서 선생님","text":"도서실을 새로 열었어요."},{"who":"사서 선생님","text":"쉬는 시간과 점심시간에 이용할 수 있어요."},{"who":"사서 선생님","text":"책은 한 번에 두 권까지 빌려요."},{"who":"사서 선생님","text":"가장 중요한 약속! 빌린 책은 일주일 안에 꼭 돌려주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_d#3','kor',3,1,'u4','','g3_1_kor_u4_review_d','unit_review','K3-1-u4-C14',1,'mc','auto','영상에서 강조하는 내용을 찾는 방법으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X06','K3-1-u4-X13']::text[],false,'{"seq":3,"concept":"K3-1-u4-C14","difficulty":1,"kind":"mc","stem":"영상에서 강조하는 내용을 찾는 방법으로 알맞은 것은 무엇일까요?","options":[{"t":"여러 번 나오거나 화면 글로도 보여 주는 내용을 찾는다.","correct":true},{"t":"그림이 가장 귀여운 장면을 찾는다.","mis":"K3-1-u4-X06"},{"t":"맨 처음 들린 말만 찾는다.","mis":"K3-1-u4-X06"},{"t":"대충 넘겨 보며 찾는다.","mis":"K3-1-u4-X13"}],"explanation":["여러 번","화면 글로도","강조"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_d#4','kor',3,1,'u4','','g3_1_kor_u4_review_d','unit_review','K3-1-u4-C20',1,'mc','auto','설명하는 글을 읽을 때 중요한 낱말에 표시하면 좋은 점은 무엇일까요?',ARRAY['K3-1-u4-X15','K3-1-u4-X09','K3-1-u4-X18']::text[],false,'{"seq":4,"concept":"K3-1-u4-C20","difficulty":1,"kind":"mc","stem":"설명하는 글을 읽을 때 중요한 낱말에 표시하면 좋은 점은 무엇일까요?","options":[{"t":"다시 볼 때 중요한 내용이 한눈에 보여요.","correct":true},{"t":"아무 낱말에나 표시해도 똑같아요.","mis":"K3-1-u4-X15"},{"t":"모든 낱말에 표시해야 해요.","mis":"K3-1-u4-X09"},{"t":"표시하면 제목을 안 봐도 돼요.","mis":"K3-1-u4-X18"}],"explanation":["중요한 낱말","표시","한눈에"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_d#5','kor',3,1,'u4','','g3_1_kor_u4_review_d','unit_review','K3-1-u4-C17',1,'mc','auto','설명하는 글과 이야기를 바르게 구별한 것은 무엇일까요?',ARRAY['K3-1-u4-X36','K3-1-u4-X18']::text[],false,'{"seq":5,"concept":"K3-1-u4-C17","difficulty":1,"kind":"mc","stem":"설명하는 글과 이야기를 바르게 구별한 것은 무엇일까요?","options":[{"t":"설명하는 글은 무엇을 알려 주고, 이야기는 인물에게 일어난 일을 들려줘요.","correct":true},{"t":"둘은 같은 글이에요.","mis":"K3-1-u4-X36"},{"t":"이야기는 무엇을 알려 주기만 해요.","mis":"K3-1-u4-X36"},{"t":"설명하는 글에는 제목이 없어요.","mis":"K3-1-u4-X18"}],"explanation":["알려 주는 글","일어난 일","구별"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_d#6','kor',3,1,'u4','','g3_1_kor_u4_review_d','unit_review','K3-1-u4-C29',1,'mc','auto','이야기와 비슷한 경험을 떠올릴 때 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X28','K3-1-u4-X27']::text[],false,'{"seq":6,"concept":"K3-1-u4-C29","difficulty":1,"kind":"mc","stem":"이야기와 비슷한 경험을 떠올릴 때 알맞은 것은 무엇일까요?","options":[{"t":"이야기 속 일과 닮은 내 일을 떠올린다.","correct":true},{"t":"이야기와 관계없는 일을 떠올린다.","mis":"K3-1-u4-X28"},{"t":"이야기를 읽지 않고 내 이야기만 한다.","mis":"K3-1-u4-X28"},{"t":"끝부분만 읽고 떠올린다.","mis":"K3-1-u4-X27"}],"explanation":["이야기 속 일","닮은","내 경험"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_d#7','kor',3,1,'u4','','g3_1_kor_u4_review_d','unit_review','K3-1-u4-C31',1,'mc','auto','설명을 듣고 방법을 메모할 때 함께 적으면 좋은 것은 무엇일까요?',ARRAY['K3-1-u4-X37','K3-1-u4-X01']::text[],false,'{"seq":7,"concept":"K3-1-u4-C31","difficulty":1,"kind":"mc","stem":"설명을 듣고 방법을 메모할 때 함께 적으면 좋은 것은 무엇일까요?","options":[{"t":"그 방법의 좋은 점","correct":true},{"t":"설명한 사람의 옷차림","mis":"K3-1-u4-X37"},{"t":"방법과 관계없는 내 생각","mis":"K3-1-u4-X37"},{"t":"들은 말 전부","mis":"K3-1-u4-X01"}],"explanation":["방법","좋은 점","짝"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_d#8','kor',3,1,'u4','','g3_1_kor_u4_review_d','unit_review','K3-1-u4-C35',1,'mc','auto','중요한 내용을 찾는 방법은 언제 쓸 수 있을까요?',ARRAY['K3-1-u4-X35']::text[],false,'{"seq":8,"concept":"K3-1-u4-C35","difficulty":1,"kind":"mc","stem":"중요한 내용을 찾는 방법은 언제 쓸 수 있을까요?","options":[{"t":"안내 방송을 들을 때나 책을 읽을 때처럼 생활 곳곳에서","correct":true},{"t":"국어 시간에만","mis":"K3-1-u4-X35"},{"t":"시험 볼 때만","mis":"K3-1-u4-X35"},{"t":"쓸 때가 없어요","mis":"K3-1-u4-X35"}],"explanation":["안내 방송","책 읽기","생활 곳곳"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_d#9','kor',3,1,'u4','','g3_1_kor_u4_review_d','unit_review','K3-1-u4-C5',2,'mc','auto','「도서실 이용 안내」를 짧게 메모한 것으로 가장 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X02','K3-1-u4-X01','K3-1-u4-X03']::text[],false,'{"seq":9,"concept":"K3-1-u4-C5","difficulty":2,"kind":"mc","stem":"「도서실 이용 안내」를 짧게 메모한 것으로 가장 알맞은 것은 무엇일까요?","options":[{"t":"쉬는 시간 · 점심시간 / 두 권까지 / ★ 일주일 안에 돌려주기","correct":true},{"t":"「도서실」","mis":"K3-1-u4-X02"},{"t":"안내한 말을 한 글자도 빼지 않고 옮긴 것","mis":"K3-1-u4-X01"},{"t":"메모 없이 외우기","mis":"K3-1-u4-X03"}],"explanation":["필요한 것만","짧게","★"],"asset":{"type":"speech","turns":[{"who":"사서 선생님","text":"도서실을 새로 열었어요."},{"who":"사서 선생님","text":"쉬는 시간과 점심시간에 이용할 수 있어요."},{"who":"사서 선생님","text":"책은 한 번에 두 권까지 빌려요."},{"who":"사서 선생님","text":"가장 중요한 약속! 빌린 책은 일주일 안에 꼭 돌려주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_d#10','kor',3,1,'u4','','g3_1_kor_u4_review_d','unit_review','K3-1-u4-C3',2,'mc','auto','민재가 메모를 해 두면 체험학습 날 아침에 좋은 점은 무엇일까요?',ARRAY['K3-1-u4-X05','K3-1-u4-X04','K3-1-u4-X03']::text[],false,'{"seq":10,"concept":"K3-1-u4-C3","difficulty":2,"kind":"mc","stem":"민재가 메모를 해 두면 체험학습 날 아침에 좋은 점은 무엇일까요?","options":[{"t":"메모를 보고 준비물과 모이는 곳을 다시 확인할 수 있어요.","correct":true},{"t":"메모가 있으니 안내를 듣지 않아도 됐어요.","mis":"K3-1-u4-X05"},{"t":"메모는 학교 공부에만 쓸모 있어요.","mis":"K3-1-u4-X04"},{"t":"메모를 안 해도 다 기억났을 거예요.","mis":"K3-1-u4-X03"}],"explanation":["그날 아침","다시 보기","확인"],"asset":{"type":"passage","lines":["제목: 현장 체험학습","1. 다음 주 수요일","2. 아침 8시 30분, 학교 정문","3. 도시락 · 물 · 모자","★ 선생님 곁을 떠나지 않기"],"title":"민재의 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_d#11','kor',3,1,'u4','','g3_1_kor_u4_review_d','unit_review','K3-1-u4-C15',2,'mc','auto','「우유갑 화분 만들기」를 보고 쓴 메모로 가장 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X02','K3-1-u4-X01','K3-1-u4-X29']::text[],false,'{"seq":11,"concept":"K3-1-u4-C15","difficulty":2,"kind":"mc","stem":"「우유갑 화분 만들기」를 보고 쓴 메모로 가장 알맞은 것은 무엇일까요?","options":[{"t":"1. 씻기 2. 옆면 자르기 3. ★ 바닥에 구멍 뚫기","correct":true},{"t":"우유갑","mis":"K3-1-u4-X02"},{"t":"영상에서 들린 말 전부","mis":"K3-1-u4-X01"},{"t":"구멍 · 자르기 · 씻기(차례 없이)","mis":"K3-1-u4-X29"}],"explanation":["숫자","차례","★"],"asset":{"type":"passage","lines":["(소리) 다 마신 우유갑으로 화분을 만들어 봐요.","(그림) 우유갑을 물로 깨끗이 씻어요.","(그림) 어른과 함께 우유갑 옆면을 잘라 내요.","(그림) 바닥에 작은 구멍을 서너 개 뚫어요.","(소리) 물이 빠질 구멍을 꼭 뚫어야 뿌리가 썩지 않아요.","(화면 글) 구멍은 꼭!"],"title":"영상 — 우유갑 화분 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_d#12','kor',3,1,'u4','','g3_1_kor_u4_review_d','unit_review','K3-1-u4-C16',2,'mc','auto','「횡단보도를 건너는 방법」을 보고 내일 등굣길에 실천할 일로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X14']::text[],false,'{"seq":12,"concept":"K3-1-u4-C16","difficulty":2,"kind":"mc","stem":"「횡단보도를 건너는 방법」을 보고 내일 등굣길에 실천할 일로 알맞은 것은 무엇일까요?","options":[{"t":"초록불이 켜져도 차가 멈췄는지 살핀 뒤 손을 들고 건넌다.","correct":true},{"t":"초록불이 켜지면 바로 뛴다.","mis":"K3-1-u4-X14"},{"t":"영상 속 아이만 지키면 된다.","mis":"K3-1-u4-X14"},{"t":"영상 내용은 잊는다.","mis":"K3-1-u4-X14"}],"explanation":["등굣길","살피고 건너기","실천"],"asset":{"type":"passage","lines":["(소리) 횡단보도를 건널 때는 세 가지를 기억해요.","(화면 글) 멈춰요 → 살펴요 → 건너요","(그림) 초록불 앞에 멈춘 아이가 왼쪽과 오른쪽을 봐요.","(소리) 초록불이 켜져도 차가 멈췄는지 꼭 살펴요.","(화면 글) 차가 멈췄는지 꼭 확인!","(그림) 아이가 손을 들고 천천히 건너요."],"title":"영상 — 횡단보도를 건너는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_d#13','kor',3,1,'u4','','g3_1_kor_u4_review_d','unit_review','K3-1-u4-C22',2,'mc','auto','「다람쥐가 묻은 도토리」를 간추린 것으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X21','K3-1-u4-X20']::text[],false,'{"seq":13,"concept":"K3-1-u4-C22","difficulty":2,"kind":"mc","stem":"「다람쥐가 묻은 도토리」를 간추린 것으로 알맞은 것은 무엇일까요?","options":[{"t":"다람쥐가 묻은 도토리는 다람쥐의 겨울 먹이가 되고, 남은 것은 나무로 자라 숲을 키운다.","correct":true},{"t":"다람쥐는 겨울잠을 잔다.","mis":"K3-1-u4-X21"},{"t":"글의 모든 문장을 그대로 옮긴 것","mis":"K3-1-u4-X20"},{"t":"도토리는 가을에 떨어진다.","mis":"K3-1-u4-X21"}],"explanation":["중심 생각","먹이 · 숲","짧게"],"asset":{"type":"passage","lines":["다람쥐는 가을에 도토리를 모아 땅에 묻어 둡니다.","겨울잠을 자다 깨면 묻어 둔 도토리를 꺼내 먹습니다.","찾지 못한 도토리는 봄에 싹을 틔워 나무로 자랍니다.","이렇게 다람쥐가 묻은 도토리는 다람쥐도 살리고 숲도 키웁니다."],"title":"다람쥐가 묻은 도토리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_d#14','kor',3,1,'u4','','g3_1_kor_u4_review_d','unit_review','K3-1-u4-C18',2,'mc','auto','「거북의 등딱지」에서 뒷받침 문장들이 공통으로 말하는 것은 무엇일까요?',ARRAY['K3-1-u4-X15','K3-1-u4-X17']::text[],false,'{"seq":14,"concept":"K3-1-u4-C18","difficulty":2,"kind":"mc","stem":"「거북의 등딱지」에서 뒷받침 문장들이 공통으로 말하는 것은 무엇일까요?","options":[{"t":"등딱지가 거북의 몸을 지키는 여러 가지 모습","correct":true},{"t":"거북이 좋아하는 먹이","mis":"K3-1-u4-X15"},{"t":"거북이 사는 곳","mis":"K3-1-u4-X15"},{"t":"등딱지의 색깔","mis":"K3-1-u4-X17"}],"explanation":["숨기 · 단단함 · 햇볕","지키는 모습","공통"],"asset":{"type":"passage","lines":["거북은 위험하면 머리와 다리를 등딱지 속에 쏙 넣습니다.","단단한 등딱지는 다른 동물이 깨물어도 잘 부서지지 않습니다.","뜨거운 햇볕도 등딱지가 막아 줍니다.","이처럼 등딱지는 거북의 몸을 지켜 줍니다."],"title":"거북의 등딱지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_d#15','kor',3,1,'u4','','g3_1_kor_u4_review_d','unit_review','K3-1-u4-C28',2,'mc','auto','「비 오는 하굣길」을 간추린 것으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X27','K3-1-u4-X20']::text[],false,'{"seq":15,"concept":"K3-1-u4-C28","difficulty":2,"kind":"mc","stem":"「비 오는 하굣길」을 간추린 것으로 알맞은 것은 무엇일까요?","options":[{"t":"우산이 없어 걱정하던 하은이가 예린이와 우산을 같이 쓰고 와서 고마운 마음을 전하려 했다.","correct":true},{"t":"아침부터 비가 내렸다.","mis":"K3-1-u4-X27"},{"t":"하은이가 사탕을 챙겼다.","mis":"K3-1-u4-X27"},{"t":"이야기의 모든 문장을 그대로 옮긴 것","mis":"K3-1-u4-X20"}],"explanation":["처음","가운데","끝"],"asset":{"type":"passage","lines":["아침부터 비가 내렸습니다.","수업이 끝나고 보니 하은이의 우산이 우산꽂이에 없었습니다.","하은이는 학교 현관 앞에서 발을 동동 굴렀습니다.","그때 예린이가 다가와 「같이 쓰고 가자.」 하고 우산을 펼쳤습니다.","둘은 어깨를 맞대고 빗속을 걸었습니다.","하은이네 집 앞에서 하은이는 「정말 고마워.」 하고 손을 흔들었습니다.","다음 날, 하은이는 예린이에게 줄 사탕을 주머니에 넣고 학교에 갔습니다."],"title":"비 오는 하굣길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_d#16','kor',3,1,'u4','','g3_1_kor_u4_review_d','unit_review','K3-1-u4-C30',2,'mc','auto','「종이컵 전화기 만들기」에서 가장 강조한 것은 무엇일까요?',ARRAY['K3-1-u4-X06','K3-1-u4-X07']::text[],false,'{"seq":16,"concept":"K3-1-u4-C30","difficulty":2,"kind":"mc","stem":"「종이컵 전화기 만들기」에서 가장 강조한 것은 무엇일까요?","options":[{"t":"실을 팽팽하게 당겨야 소리가 잘 들린다는 것","correct":true},{"t":"종이컵의 색깔","mis":"K3-1-u4-X06"},{"t":"구멍을 뚫는 것 — 맨 처음 나와서","mis":"K3-1-u4-X06"},{"t":"컵이 두 개라는 것","mis":"K3-1-u4-X07"}],"explanation":["가장 중요한 것!","화면 글로 또","팽팽하게"],"asset":{"type":"passage","lines":["(소리) 종이컵 전화기를 만들어 봐요.","(그림) 어른과 함께 종이컵 두 개의 바닥 가운데에 작은 구멍을 뚫어요.","(그림) 구멍에 실을 넣고 컵 안쪽에서 매듭을 지어요.","(그림) 다른 컵에도 실 끝을 똑같이 끼워 묶어요.","(소리) 가장 중요한 것! 실을 팽팽하게 당겨야 소리가 잘 들려요.","(화면 글) 실은 팽팽하게!"],"title":"영상 — 종이컵 전화기 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_d#17','kor',3,1,'u4','','g3_1_kor_u4_review_d','unit_review','K3-1-u4-C10',3,'mc','auto','메모의 모든 줄에 별표를 붙이면 생기는 문제는 무엇일까요?',ARRAY['K3-1-u4-X09','K3-1-u4-X08']::text[],false,'{"seq":17,"concept":"K3-1-u4-C10","difficulty":3,"kind":"mc","stem":"메모의 모든 줄에 별표를 붙이면 생기는 문제는 무엇일까요?","options":[{"t":"무엇이 가장 중요한지 눈에 띄지 않아요.","correct":true},{"t":"문제없어요 — 별표는 많을수록 좋아요.","mis":"K3-1-u4-X09"},{"t":"차례가 더 잘 보여요.","mis":"K3-1-u4-X08"},{"t":"제목이 없어도 돼요.","mis":"K3-1-u4-X08"}],"explanation":["모든 줄 ★","눈에 안 띔","가장 중요한 곳만"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_d#18','kor',3,1,'u4','','g3_1_kor_u4_review_d','unit_review','K3-1-u4-C16',3,'mc','auto','영상을 보고 「나와 관련짓기」를 해야 하는 까닭은 무엇일까요?',ARRAY['K3-1-u4-X14','K3-1-u4-X13','K3-1-u4-X03']::text[],false,'{"seq":18,"concept":"K3-1-u4-C16","difficulty":3,"kind":"mc","stem":"영상을 보고 「나와 관련짓기」를 해야 하는 까닭은 무엇일까요?","options":[{"t":"알게 된 것을 내 생활에서 실천할 수 있어서","correct":true},{"t":"영상 속 일은 나와 관계없어서","mis":"K3-1-u4-X14"},{"t":"영상을 다시 안 봐도 되어서","mis":"K3-1-u4-X13"},{"t":"메모를 안 해도 되어서","mis":"K3-1-u4-X03"}],"explanation":["알게 된 것","내 생활","실천"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_d#19','kor',3,1,'u4','','g3_1_kor_u4_review_d','unit_review','K3-1-u4-C20',3,'mc','auto','「다람쥐가 묻은 도토리」를 읽으며 표시하기에 가장 알맞은 낱말은 무엇일까요?',ARRAY['K3-1-u4-X15','K3-1-u4-X09']::text[],false,'{"seq":19,"concept":"K3-1-u4-C20","difficulty":3,"kind":"mc","stem":"「다람쥐가 묻은 도토리」를 읽으며 표시하기에 가장 알맞은 낱말은 무엇일까요?","options":[{"t":"묻어 둡니다 · 꺼내 먹습니다 · 나무로 자랍니다","correct":true},{"t":"가을에 · 깨면 · 봄에","mis":"K3-1-u4-X15"},{"t":"글의 모든 낱말","mis":"K3-1-u4-X09"},{"t":"표시할 낱말이 없다","mis":"K3-1-u4-X15"}],"explanation":["중요한 낱말","표시","한눈에"],"asset":{"type":"passage","lines":["다람쥐는 가을에 도토리를 모아 땅에 묻어 둡니다.","겨울잠을 자다 깨면 묻어 둔 도토리를 꺼내 먹습니다.","찾지 못한 도토리는 봄에 싹을 틔워 나무로 자랍니다.","이렇게 다람쥐가 묻은 도토리는 다람쥐도 살리고 숲도 키웁니다."],"title":"다람쥐가 묻은 도토리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_d#20','kor',3,1,'u4','','g3_1_kor_u4_review_d','unit_review','K3-1-u4-C28',3,'mc','auto','「할머니 댁 감나무」를 두 문장으로 간추린 것으로 가장 알맞은 것은 무엇일까요?',ARRAY['K3-1-u4-X27','K3-1-u4-X20']::text[],false,'{"seq":20,"concept":"K3-1-u4-C28","difficulty":3,"kind":"mc","stem":"「할머니 댁 감나무」를 두 문장으로 간추린 것으로 가장 알맞은 것은 무엇일까요?","options":[{"t":"준서는 감을 따다 터뜨려 속상했다. 할머니께 방법을 배워 감을 따고 이웃과 나누며 기뻐했다.","correct":true},{"t":"준서가 고맙다는 말을 들었다. 얼굴이 환해졌다.","mis":"K3-1-u4-X27"},{"t":"가을이었다. 감나무가 있었다.","mis":"K3-1-u4-X27"},{"t":"이야기의 모든 문장을 그대로 옮긴 것","mis":"K3-1-u4-X20"}],"explanation":["처음","가운데","끝"],"asset":{"type":"passage","lines":["가을, 준서는 시골 할머니 댁에 감을 따러 갔습니다.","마당의 감나무에는 주황색 감이 주렁주렁 달려 있었습니다.","준서는 신이 나서 긴 장대로 감을 툭 쳤습니다.","감은 땅에 떨어져 퍽 터져 버렸습니다. 준서는 울상이 되었습니다.","할머니가 웃으며 「감은 바구니로 받쳐야 안 터진단다.」 하셨습니다.","둘이 함께 감을 따니 바구니가 금세 가득 찼습니다.","저녁에 준서는 옆집 할아버지께 감 한 바구니를 갖다드렸습니다.","「고맙다.」라는 말을 듣고 준서의 얼굴이 환해졌습니다."],"title":"할머니 댁 감나무"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_d#21','kor',3,1,'u4','','g3_1_kor_u4_review_d','unit_review','K3-1-u4-C35',3,'mc','auto','박물관에서 해설을 들을 때 배운 것을 살린 모습은 무엇일까요?',ARRAY['K3-1-u4-X35','K3-1-u4-X01','K3-1-u4-X06']::text[],false,'{"seq":21,"concept":"K3-1-u4-C35","difficulty":3,"kind":"mc","stem":"박물관에서 해설을 들을 때 배운 것을 살린 모습은 무엇일까요?","options":[{"t":"해설사가 강조하는 내용을 찾아 짧게 메모하고 나중에 친구와 나눈다.","correct":true},{"t":"국어 시간이 아니니 대충 듣는다.","mis":"K3-1-u4-X35"},{"t":"해설을 한 글자도 빼지 않고 받아 적는다.","mis":"K3-1-u4-X01"},{"t":"가장 신기한 물건 이름만 기억한다.","mis":"K3-1-u4-X06"}],"explanation":["강조","짧게 메모","나누기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_d#22','kor',3,1,'u4','','g3_1_kor_u4_review_d','unit_review','K3-1-u4-C35',3,'mc','auto','책을 읽으며 중요한 곳에 밑줄을 긋는 까닭은 무엇일까요?',ARRAY['K3-1-u4-X09','K3-1-u4-X35']::text[],false,'{"seq":22,"concept":"K3-1-u4-C35","difficulty":3,"kind":"mc","stem":"책을 읽으며 중요한 곳에 밑줄을 긋는 까닭은 무엇일까요?","options":[{"t":"나중에 다시 볼 때 중요한 내용을 빨리 찾으려고","correct":true},{"t":"모든 줄에 그어야 해서","mis":"K3-1-u4-X09"},{"t":"책을 예쁘게 꾸미려고","mis":"K3-1-u4-X35"},{"t":"국어책에만 긋는 것이라서","mis":"K3-1-u4-X35"}],"explanation":["밑줄","다시 보기","빨리 찾기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_d#23','kor',3,1,'u4','','g3_1_kor_u4_review_d','unit_review','K3-1-u4-C16',4,'essay','teacher','「페트병 버리는 방법」을 보고 나와 관련지어 실천할 일을 쓰고, 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-1-u4-C16","difficulty":4,"kind":"essay","stem":"「페트병 버리는 방법」을 보고 나와 관련지어 실천할 일을 쓰고, 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 우리 집에서 마신 페트병을 비우고 비닐을 떼어 눌러서 내놓겠다. 깨끗하게 버려야 다시 쓸 수 있다고 영상에서 강조했기 때문이다.","scoring_points":["실천할 일을 썼는가","영상 내용과 이어지는가","까닭을 썼는가"]},"explanation":["실천","영상 내용","까닭"],"asset":{"type":"passage","lines":["(소리) 페트병은 이렇게 버려요.","(화면 글) 비우고 · 떼고 · 누르고","(그림) 아이가 페트병 속 물을 비워요.","(그림) 병에 붙은 비닐을 뜯어요.","(그림) 병을 발로 꾹 눌러 납작하게 해요.","(소리) 깨끗하게 버려야 다시 쓸 수 있어요.","(화면 글) 깨끗하게 버려야 다시 써요!"],"title":"영상 — 페트병 버리는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_d#24','kor',3,1,'u4','','g3_1_kor_u4_review_d','unit_review','K3-1-u4-C26',4,'essay','teacher','하은이의 마음이 어떻게 바뀌었는지 쓰고, 그렇게 짐작한 까닭을 하은이의 말과 행동에서 찾아 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-1-u4-C26","difficulty":4,"kind":"essay","stem":"하은이의 마음이 어떻게 바뀌었는지 쓰고, 그렇게 짐작한 까닭을 하은이의 말과 행동에서 찾아 쓰세요.","answer_guide":{"answer":"예: 걱정하다가 고마워졌다. 「발을 동동 굴렀습니다」에서 걱정을, 「정말 고마워.」라는 말과 사탕을 챙긴 행동에서 고마운 마음을 짐작했다.","scoring_points":["바뀐 마음을 차례대로 썼는가","하은이의 행동을 단서로 들었는가","하은이의 말을 단서로 들었는가"]},"explanation":["바뀐 마음","행동","말"],"asset":{"type":"passage","lines":["아침부터 비가 내렸습니다.","수업이 끝나고 보니 하은이의 우산이 우산꽂이에 없었습니다.","하은이는 학교 현관 앞에서 발을 동동 굴렀습니다.","그때 예린이가 다가와 「같이 쓰고 가자.」 하고 우산을 펼쳤습니다.","둘은 어깨를 맞대고 빗속을 걸었습니다.","하은이네 집 앞에서 하은이는 「정말 고마워.」 하고 손을 흔들었습니다.","다음 날, 하은이는 예린이에게 줄 사탕을 주머니에 넣고 학교에 갔습니다."],"title":"비 오는 하굣길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u4_review_d#25','kor',3,1,'u4','','g3_1_kor_u4_review_d','unit_review','K3-1-u4-C35',4,'essay','teacher','이 단원에서 배운 중요한 내용 찾기를 생활 속에서 쓸 수 있는 때를 두 가지 쓰고, 어떻게 할지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-1-u4-C35","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 중요한 내용 찾기를 생활 속에서 쓸 수 있는 때를 두 가지 쓰고, 어떻게 할지 쓰세요.","answer_guide":{"answer":"예: 학교 안내 방송을 들을 때 무엇을 알려 주는지 생각하며 꼭 할 일을 메모하겠다. 과학책을 읽을 때 문단마다 중심 문장에 밑줄을 긋겠다.","scoring_points":["두 가지 때를 썼는가","어떻게 할지 썼는가","배운 방법과 이어지는가"]},"explanation":["생활 속","방법","실천"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
